-- BEGIN GENERATED FRESH BOOTSTRAP prerequisite guard
begin;
do $filey_bootstrap$
begin
  if to_regclass('public.filey_bootstrap_migrations') is null and exists(
    select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='public' and c.relkind in ('r','p','v','m','f')
        and not exists(select 1 from pg_depend d where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype='e')
  ) then
    raise exception 'This canonical installer is for fresh Filey databases. Use the documented upgrade migrations for an existing installation.';
  end if;
end;
$filey_bootstrap$;
create table if not exists public.filey_bootstrap_migrations (
  name text primary key,
  source_sha256 text not null check(source_sha256 ~ '^[0-9a-f]{64}$'),
  installed_at timestamptz not null default now()
);
alter table public.filey_bootstrap_migrations enable row level security;
revoke all on public.filey_bootstrap_migrations from public,anon,authenticated;
-- END GENERATED FRESH BOOTSTRAP prerequisite guard

-- ============================================================
--  Filey ERP & CRM — Supabase schema
--  Run this once in:  Supabase Dashboard → SQL Editor → New query
--  Safe to re-run (idempotent).
-- ============================================================

-- Profile policies reference memberships during CREATE POLICY, so this base
-- relation must precede profiles on an empty database.
create table if not exists org_members (
  id bigint generated by default as identity primary key,
  org_id text not null,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  role text not null default 'staff',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, user_id)
);
alter table org_members add column if not exists modules text[];

-- ---------- PROFILES (one row per auth user) ----------
create table if not exists profiles (
  id          uuid primary key references auth.users(id) on delete cascade,
  org_id      text not null default 'default',
  email       text not null default '',
  name        text not null default 'User',
  company     text not null default '',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- Extra profile fields (additive, safe on existing projects)
alter table profiles add column if not exists phone text;
alter table profiles add column if not exists role text default 'Administrator';
alter table profiles add column if not exists username text;
alter table profiles add column if not exists avatar text;
alter table profiles add column if not exists language text default 'English (US)';
alter table profiles add column if not exists timezone text;
alter table profiles add column if not exists date_format text;
alter table profiles add column if not exists time_format text;

alter table profiles enable row level security;
-- SECURITY: a user may read/insert/delete only their own profile, and may
-- only switch their active org_id to an organization they actually belong
-- to. The old "for all" policy let a user set org_id to ANY org, which made
-- current_org() return that org and exposed its shared data.
drop policy if exists profiles_owner on profiles;
drop policy if exists profiles_self_select on profiles;
drop policy if exists profiles_self_insert on profiles;
drop policy if exists profiles_self_update on profiles;
drop policy if exists profiles_self_delete on profiles;

create policy profiles_self_select on profiles for select
  using (id = auth.uid());
create policy profiles_self_insert on profiles for insert
  with check (id = auth.uid() and (org_id = 'default' or exists (
    select 1 from public.org_members m where m.org_id = profiles.org_id and m.user_id = auth.uid()
  )));
create policy profiles_self_update on profiles for update
  using (id = auth.uid())
  with check (
    id = auth.uid()
    and (
      org_id = 'default'
      or exists (
        select 1 from public.org_members m
        where m.org_id = profiles.org_id and m.user_id = auth.uid()
      )
    )
  );
create policy profiles_self_delete on profiles for delete
  using (id = auth.uid());

-- ---------- shared updated_at trigger fn ----------
create or replace function set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

drop trigger if exists trg_profiles_updated on profiles;
create trigger trg_profiles_updated before update on profiles
  for each row execute function set_updated_at();

-- ---------- business tables ----------
-- Numeric ids (bigint identity) keep the desktop app's TypeScript unchanged.
-- Every row is owned by the inserting user via user_id default auth.uid().

-- ===== ERP =====
create table if not exists products (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  sku text not null default '',
  name text not null default '',
  description text,
  category text,
  unit_price numeric(14,2) not null default 0,
  cost_price numeric(14,2) not null default 0,
  quantity numeric(14,3) not null default 0,
  reorder_level numeric(14,3) not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists orders (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  order_number text not null default '',
  customer_name text not null default '',
  status text not null default 'draft',
  total numeric(14,2) not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists order_items (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  order_id bigint references orders(id) on delete cascade,
  product_id bigint,
  quantity numeric(14,3) not null default 1,
  unit_price numeric(14,2) not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- The app uses invoice_docs. Retain any historical invoices relation rather
-- than deleting customer data when the canonical installer is repeated.

-- ===== HR =====
create table if not exists employees (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  employee_code text not null default '',
  name text not null default '',
  email text,
  phone text,
  department text,
  position text,
  salary numeric(14,2) not null default 0,
  hire_date date,
  status text not null default 'active',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists attendance (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  employee_id bigint references employees(id) on delete cascade,
  date date not null default current_date,
  check_in text,
  check_out text,
  status text not null default 'present',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists payroll (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  employee_id bigint references employees(id) on delete cascade,
  period text not null default '',
  basic numeric(14,2) not null default 0,
  allowances numeric(14,2) not null default 0,
  deductions numeric(14,2) not null default 0,
  net_pay numeric(14,2) not null default 0,
  status text not null default 'pending',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ===== FINANCE =====
create table if not exists accounts (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  code text not null default '',
  name text not null default '',
  account_type text not null default 'asset',
  balance numeric(16,2) not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists expenses (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  category text not null default '',
  description text,
  amount numeric(14,2) not null default 0,
  expense_date date not null default current_date,
  account_id bigint,
  details jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists transactions (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  account_id bigint,
  txn_type text not null default 'debit',
  amount numeric(16,2) not null default 0,
  description text,
  txn_date date not null default current_date,
  -- Link back to the document that created this entry (invoice, order, etc.).
  ref text,
  source text,
  invoice_id bigint, -- FK installed after invoice_docs is created below.
  -- Set when a bank reconciliation confirmed this entry against a statement.
  reconciled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table transactions add column if not exists reconciled_at timestamptz;

create index if not exists idx_transactions_invoice_id on transactions(invoice_id);
create index if not exists idx_transactions_ref on transactions(ref);

-- ===== SUPPLIERS / PURCHASE ORDERS =====
create table if not exists suppliers (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  name text not null default '',
  contact_person text,
  email text,
  phone text,
  address text,
  tax_id text,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table products add column if not exists supplier_id bigint references suppliers(id) on delete set null;
alter table products add column if not exists batch_number  text;
alter table products add column if not exists expiry_date   date;
alter table products add column if not exists barcode       text;
alter table products add column if not exists warehouse     text;
alter table products add column if not exists is_serialized boolean not null default false;
alter table products add column if not exists custom_fields jsonb;

-- Party-level prepayment credit ledger (customer/supplier advances). Negative
-- rows consume credit (applied to an invoice); balance = sum of a party's rows.
create table if not exists advances (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  party_type text not null default 'customer',
  party_id bigint not null,
  party_name text not null default '',
  amount numeric(14,2) not null default 0,
  note text,
  paid_at date not null default current_date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_advances_party on advances(party_type, party_id);

-- One row per stock quantity change (sale, purchase, order, manual in/out,
-- count adjustment). qty is signed: positive = in, negative = out.
create table if not exists stock_movements (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  product_id bigint references products(id) on delete cascade,
  qty numeric(14,3) not null,
  type text not null default 'adjust',
  ref text,
  note text,
  moved_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_stock_movements_product on stock_movements(product_id);
create index if not exists idx_stock_movements_moved on stock_movements(moved_at);

create table if not exists purchase_orders (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  po_number text not null default '',
  supplier_id bigint references suppliers(id) on delete set null,
  status text not null default 'draft',
  template text not null default 'uae',
  accent text not null default '#222222',
  currency text not null default 'AED',
  total numeric(14,2) not null default 0,
  order_date date not null default current_date,
  expected_date date,
  notes text,
  terms text,
  doc_title text,
  custom_columns jsonb,
  unit_price_formula jsonb,
  discount numeric(14,2) not null default 0,
  tax_rate numeric(8,3) not null default 0,
  shared boolean not null default false,
  share_token uuid not null default gen_random_uuid(),
  logo text,
  seller_name text not null default '',
  seller_address text,
  seller_trn text,
  seller_email text,
  seller_phone text,
  supplier_name text,
  supplier_address text,
  supplier_trn text,
  supplier_email text,
  supplier_phone text,
  show_stamp boolean not null default false,
  show_signature boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists purchase_order_items (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  po_id bigint references purchase_orders(id) on delete cascade,
  product_id bigint references products(id) on delete set null,
  description text not null default '',
  quantity numeric(14,3) not null default 1,
  unit_cost numeric(14,2) not null default 0,
  unit text,
  custom jsonb,
  position bigint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ===== TOOLS =====
create table if not exists app_users (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  username text not null default '',
  full_name text not null default '',
  role text not null default 'staff',
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists app_settings (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  key text not null default '',
  value text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint app_settings_user_id_key unique (user_id, key)
);

create table if not exists audit_log (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  actor text not null default '',
  action text not null default '',
  entity text not null default '',
  details text,
  changes jsonb,            -- before->after diff captured by log_audit()
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table audit_log add column if not exists changes jsonb;

-- ===== CRM =====
create table if not exists crm_leads (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  name text not null default '',
  company text,
  email text,
  phone text,
  source text,
  status text not null default 'new',
  est_value numeric(14,2) not null default 0,
  owner text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists crm_customers (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  name text not null default '',
  company text,
  email text,
  phone text,
  phone_e164 text,
  address text,
  trn text,
  segment text,
  custom_fields jsonb default '{}',
  shared boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists crm_opportunities (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  title text not null default '',
  customer_name text not null default '',
  stage text not null default 'qualification',
  value numeric(14,2) not null default 0,
  probability bigint not null default 20,
  owner text,
  expected_close date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists crm_activities (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  kind text not null default 'task',
  subject text not null default '',
  related_to text,
  due_date date,
  done boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ===== BILLING / INVOICING =====
create table if not exists company_profile (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  name text not null default '',
  address text,
  trn text,
  email text,
  phone text,
  logo text,
  default_accent text not null default '#0A0A0A',
  default_template text not null default 'minimal',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id)
);

-- Extra company-profile fields (additive, safe on existing projects)
alter table company_profile add column if not exists business_type text;
alter table company_profile add column if not exists city text;
alter table company_profile add column if not exists zip text;
alter table company_profile add column if not exists vat_number text;
alter table company_profile add column if not exists tax_type text default 'VAT';
alter table company_profile add column if not exists website text;
alter table company_profile add column if not exists currency text default 'AED';
alter table company_profile add column if not exists default_tax_rate numeric(8,3) default 5;

-- WPS (UAE Wage Protection System) payroll identifiers — the SIF a bank forwards
-- to MOHRE needs an employer identity and a per-employee one. Nullable: a
-- business that doesn't file WPS never has to fill these in.
-- See supabase/2026-08-02-wps-payroll-fields.sql
alter table company_profile add column if not exists mol_establishment_id text;
alter table company_profile add column if not exists wps_bank_code text;
-- Business WhatsApp number (E.164); see supabase/2026-08-03-company-whatsapp.sql
alter table company_profile add column if not exists whatsapp text;
alter table employees add column if not exists labour_card_no text;
alter table employees add column if not exists iban text;
alter table employees add column if not exists bank_routing_code text;

create table if not exists invoice_docs (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  number text not null default '',
  status text not null default 'draft',
  template text not null default 'minimal',
  accent text not null default '#0A0A0A',
  currency text not null default 'AED',
  seller_name text not null default '',
  seller_address text,
  seller_trn text,
  seller_email text,
  seller_phone text,
  logo text,
  customer_name text not null default '',
  customer_address text,
  customer_trn text,
  customer_email text,
  issue_date date,
  due_date date,
  notes text,
  terms text,
  tax_rate numeric(8,3) not null default 5,
  discount numeric(14,2) not null default 0,
  custom_columns jsonb,
  unit_price_formula jsonb,
  doc_title text,
  po_number text,
  stamp jsonb,
  signature jsonb,
  show_stamp boolean not null default false,
  show_signature boolean not null default false,
  shared boolean not null default false,
  share_token uuid not null default gen_random_uuid(),
  fx_rate numeric,            -- AED per 1 unit of currency, frozen at save
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table invoice_docs add column if not exists fx_rate numeric;

create table if not exists invoice_doc_items (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  invoice_id bigint references invoice_docs(id) on delete cascade,
  product_id bigint references products(id) on delete set null,
  description text not null default '',
  qty numeric(14,3) not null default 1,
  unit_price numeric(14,2) not null default 0,
  unit text,
  custom jsonb,
  position bigint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Generic edge between any two records. See 2026-08-31-entity-links.sql
-- for the reasoning; kept here so a fresh database gets it too.
create table if not exists entity_links (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  from_type text not null,
  from_id bigint not null,
  to_type text not null,
  to_id bigint not null,
  kind text not null default 'related',
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists entity_links_unique
  on entity_links (from_type, from_id, to_type, to_id, kind);
create index if not exists entity_links_from_idx on entity_links (from_type, from_id);
create index if not exists entity_links_to_idx on entity_links (to_type, to_id);

-- Payments recorded against an invoice (partial or full).
create table if not exists invoice_payments (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  invoice_id bigint references invoice_docs(id) on delete cascade,
  amount numeric(14,2) not null default 0,
  method text,
  note text,
  paid_at date not null default current_date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ===== QUOTING =====
