);

-- Supplier payments against purchase orders. Previously lived only in
-- po-payments-migration.sql — schema.sql's audit loop already referenced it,
-- so a fresh install broke; and it shipped WITHOUT RLS (cross-tenant leak,
-- fixed 2026-07-09 by adding it to the RLS loop below).
create table if not exists po_payments (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  po_id bigint not null references public.purchase_orders(id) on delete cascade,
  amount numeric(14,2) not null default 0,
  method text,
  paid_at date not null default current_date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_po_payments_po on po_payments (po_id);

-- ===== TOOLS activity =====
create table if not exists tool_runs (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  tool text not null default '',
  tool_name text not null default '',
  file_name text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
-- Stored output object paths in the tool-outputs bucket (additive).
alter table tool_runs add column if not exists storage_paths text[] not null default '{}';
alter table tool_runs add column if not exists size_bytes bigint not null default 0;

-- ---------- MULTI-TENANCY (organizations + members + RBAC) ----------
create extension if not exists pgcrypto;

create table if not exists organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null default 'My Organization',
  owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Monthly creation usage is private; the Basic-web migration installs the
-- invoice trigger and authenticated current-workspace usage RPC.
create table if not exists public.invoice_monthly_usage (
  org_id uuid not null references public.organizations(id) on delete cascade,
  month date not null,
  used integer not null default 0 check (used >= 0),
  primary key (org_id, month)
);
alter table public.invoice_monthly_usage enable row level security;
revoke all on public.invoice_monthly_usage from public, anon, authenticated;

-- Caller's active organization key (text). Defaults to 'default' so any
-- pre-existing single-user data keeps working unchanged after migration.
create or replace function public.current_org()
returns text language sql stable security definer set search_path = public as $$
  select coalesce(
    (select org_id from public.profiles where id = auth.uid()),
    'default'
  )
$$;

-- Company message board — an org-wide team feed (everyone in the org can
-- read; members post their own messages; authors or admins can delete).
create table if not exists org_messages (
  id bigint generated by default as identity primary key,
  org_id text not null default public.current_org(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  body text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
-- Threaded replies: a reply points at its parent message.
alter table org_messages add column if not exists parent_id bigint
  references org_messages(id) on delete cascade;

-- Pending team invitations issued by an org owner/admin.
create table if not exists invitations (
  id uuid primary key default gen_random_uuid(),
  org_id text not null,
  email text not null,
  role text not null default 'staff',
  modules text[],
  invited_by uuid default auth.uid() references auth.users(id) on delete set null,
  status text not null default 'pending',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Fresh and legacy canonical installs use the same expiring invitations.
alter table public.invitations add column if not exists expires_at timestamptz
  not null default (now()+interval '7 days');


-- SECURITY: force org_id to the caller's active org and make it immutable.
-- Without this, a client could INSERT a row carrying ANOTHER org's org_id
-- (and shared=true) — the per-member RLS check passes on the user_id branch
-- regardless of org_id, so the row would surface in the victim org's shared
-- feed (cross-tenant injection / fake-invoice phishing). On UPDATE we pin
-- org_id to its previous value so a row can never be moved between orgs.
create or replace function public.force_org_id()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  -- Admin / service_role / SQL-migration context (no JWT) is trusted and must
  -- stay able to backfill org_id. Only pin org_id for real client requests.
  if auth.uid() is null then
    return new;
  end if;
  if (TG_OP = 'INSERT') then
    new.org_id := public.current_org();
  else
    new.org_id := old.org_id;
  end if;
  return new;
end $$;

-- True when the caller is an owner/admin of their active org.
-- security definer avoids RLS recursion on org_members.
create or replace function public.is_org_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.org_members
    where org_id = public.current_org()
      and user_id = auth.uid()
      and role in ('owner', 'admin')
  )
$$;

alter table organizations enable row level security;
drop policy if exists organizations_access on organizations;
create policy organizations_access on organizations for all
  using (id::text = public.current_org() or owner_id = auth.uid())
  with check (owner_id = auth.uid());
drop trigger if exists trg_organizations_updated on organizations;
create trigger trg_organizations_updated before update on organizations
  for each row execute function set_updated_at();

alter table org_members enable row level security;
drop policy if exists org_members_select on org_members;
create policy org_members_select on org_members for select
  using (org_id = (select public.current_org()) or user_id = (select auth.uid()));

-- SECURITY: members may NOT freely insert/update their own membership —
-- that allowed self-escalation to owner/admin and joining arbitrary orgs.
drop policy if exists org_members_self on org_members;

-- A member may leave (delete) their own membership.
drop policy if exists org_members_self_leave on org_members;
create policy org_members_self_leave on org_members for delete
  using (user_id = (select auth.uid()));

-- A user may add ONLY themselves, and ONLY to an organization they own
-- (covers creating a new org). Joining someone else's org is invite-only
-- (handled by an admin via org_members_admin).
drop policy if exists org_members_create_own on org_members;
create policy org_members_create_own on org_members for insert
  with check (
    user_id = (select auth.uid())
    and exists (
      select 1 from public.organizations o
      where o.id::text = org_members.org_id
        and o.owner_id = (select auth.uid())
    )
  );

-- Owners/admins manage membership + roles within their active org.
drop policy if exists org_members_admin on org_members;
create policy org_members_admin on org_members for all
  using (org_id = (select public.current_org()) and (select public.is_org_admin()))
  with check (org_id = (select public.current_org()) and (select public.is_org_admin()));
drop trigger if exists trg_org_members_updated on org_members;
create trigger trg_org_members_updated before update on org_members
  for each row execute function set_updated_at();

-- Team members may read each other's profiles within the same org.
drop policy if exists profiles_org_read on profiles;
create policy profiles_org_read on profiles for select
  using (org_id = (select public.current_org()));

-- ---------- invitations RLS + accept flow ----------
alter table invitations enable row level security;
drop trigger if exists trg_invitations_updated on invitations;
create trigger trg_invitations_updated before update on invitations
  for each row execute function set_updated_at();

-- Caller's own email (security definer to read auth/profile safely).
create or replace function public.my_email()
returns text language sql stable security definer set search_path = public,pg_temp as $$
  select lower(email) from auth.users where id=auth.uid() and email_confirmed_at is not null
$$;
revoke all on function public.my_email() from public,anon;
grant execute on function public.my_email() to authenticated;

-- Org admins manage invitations for their active org.
drop policy if exists invitations_admin on invitations;
create policy invitations_admin on invitations for all
  using (org_id = (select public.current_org()) and (select public.is_org_admin()))
  with check (org_id = (select public.current_org()) and (select public.is_org_admin()));

-- An invitee may read pending invitations addressed to their email.
drop policy if exists invitations_invitee_read on invitations;
create policy invitations_invitee_read on invitations for select
  using (lower(email) = lower(coalesce(public.my_email(), '')));

-- Accept an invitation: validated by email match, runs as definer so it
-- can add the membership and switch the caller's active org safely.
-- ---------- notifications (per-user inbox; e.g. @mentions) ----------
create table if not exists notifications (
  id bigint generated by default as identity primary key,
  org_id text not null,
  user_id uuid not null references auth.users(id) on delete cascade, -- recipient
  actor text not null default '',
  kind text not null default 'info',
  body text not null default '',
  link text,
  read boolean not null default false,
  created_at timestamptz not null default now()
);
alter table notifications enable row level security;
-- A user only ever sees / mutates their own notifications. There is NO
-- client insert policy on purpose: rows are created only by the
-- security-definer mention trigger below.
drop policy if exists notifications_select_own on notifications;
create policy notifications_select_own on notifications for select
  using (user_id = auth.uid());
drop policy if exists notifications_update_own on notifications;
create policy notifications_update_own on notifications for update
  using (user_id = auth.uid()) with check (user_id = auth.uid());
drop policy if exists notifications_delete_own on notifications;
create policy notifications_delete_own on notifications for delete
  using (user_id = auth.uid());
create index if not exists idx_notifications_inbox
  on notifications (user_id, read, created_at desc);

-- Fan out @mentions in a new message to the mentioned org members.
-- Handle = first name (lowercased), matching MentionInput's insertion.
create or replace function public.notify_mentions()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  actor_name text;
  h text;
  rec record;
begin
  select coalesce(name, email, 'Someone') into actor_name
    from public.profiles where id = new.user_id;
  for h in
    select distinct lower(t[1])
    from regexp_matches(new.body, '@([A-Za-z0-9_.\-]+)', 'g') as t
  loop
    for rec in
      select p.id
      from public.profiles p
      join public.org_members om
        on om.user_id = p.id and om.org_id = new.org_id
      where lower(split_part(p.name, ' ', 1)) = h
        and p.id <> new.user_id
    loop
      insert into public.notifications (org_id, user_id, actor, kind, body, link)
      values (new.org_id, rec.id, actor_name, 'mention',
              left(new.body, 140), '/overview');
    end loop;
  end loop;
  return new;
end $$;

drop trigger if exists trg_notify_mentions on org_messages;
create trigger trg_notify_mentions after insert on org_messages
  for each row execute function public.notify_mentions();

-- ---------- org_messages RLS ----------
alter table org_messages enable row level security;
drop trigger if exists trg_org_messages_updated on org_messages;
create trigger trg_org_messages_updated before update on org_messages
  for each row execute function set_updated_at();
drop policy if exists org_messages_read on org_messages;
create policy org_messages_read on org_messages for select
  using (org_id = public.current_org());
drop policy if exists org_messages_insert on org_messages;
create policy org_messages_insert on org_messages for insert
  with check (user_id = auth.uid() and org_id = public.current_org());
drop policy if exists org_messages_modify on org_messages;
create policy org_messages_modify on org_messages for delete
  using (
    org_id = public.current_org()
    and (user_id = auth.uid() or public.is_org_admin())
  );
create index if not exists idx_org_messages_org_created
  on org_messages (org_id, created_at desc);

create or replace function public.accept_invitation(invite uuid)
returns void language plpgsql security definer set search_path = public,pg_temp as $$
declare inv public.invitations; v_email text:=public.my_email();
begin
  if auth.uid() is null or v_email is null then raise exception 'Verify your account email before joining'; end if;
  select * into inv from public.invitations where id=invite for update;
  if inv.id is null or lower(inv.email)<>v_email then raise exception 'Sign in with the email address this invitation was sent to'; end if;
  if inv.status<>'pending' or inv.expires_at<=now() then raise exception 'This invitation has expired or is no longer available. Ask for a new invitation'; end if;
  if inv.role not in ('admin','manager','accountant','staff') then raise exception 'Ask the owner to replace this invitation'; end if;
  -- Old invitations must not change an existing member's current permissions.
  insert into public.org_members(org_id,user_id,role,modules) values(inv.org_id,auth.uid(),inv.role,inv.modules)
    on conflict(org_id,user_id) do nothing;
  update public.profiles set org_id=inv.org_id where id=auth.uid();
  if not found then raise exception 'Complete your account profile before joining'; end if;
  update public.invitations set status=case when id=inv.id then 'accepted' else 'revoked' end,updated_at=now()
    where org_id=inv.org_id and lower(invitations.email)=v_email and status='pending';
end $$;
revoke all on function public.accept_invitation(uuid) from public,anon;
grant execute on function public.accept_invitation(uuid) to authenticated;

-- ---------- marketing campaigns + the opt-out list ----------
-- Standalone migration for existing projects:
-- supabase/2026-08-02-campaigns.sql (also creates the unique/opt-out indexes).
create table if not exists campaigns (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  name text not null default '',
  subject text not null default '',
  body_html text not null default '',
  status text not null default 'draft',      -- draft | sending | sent | paused
  audience jsonb not null default '{}'::jsonb,
  recipients jsonb not null default '[]'::jsonb,
  sent_count integer not null default 0,
  failed_count integer not null default 0,
  sent_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Who asked not to be contacted. Checked before every campaign send; nothing in
-- the app deletes from it.
create table if not exists email_optouts (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  email text not null,
  reason text not null default 'unsubscribed', -- unsubscribed | bounced | manual
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------- RLS + org scoping + privacy model + updated_at trigger ----------
-- Privacy model (per the product spec):
--   * A member's records are PRIVATE to them by default.
--   * Org owners/admins can see and manage everything in the org.
--   * A record becomes visible to the whole org only when its owner sets
--     `shared = true` (opt-in, per record). Shared records are read-only
--     to other members (only the owner or an admin can edit them).
-- Org-level tables (settings, audit, company profile, legacy app_users)
-- stay org-scoped rather than per-member.
do $$
declare
  t text;
  tables text[] := array[
    'products','orders','order_items',
    'employees','attendance','payroll',
    'accounts','expenses','transactions',
    'app_users','app_settings','audit_log',
    'crm_leads','crm_customers','crm_opportunities','crm_activities',
    'company_profile','invoice_docs','invoice_doc_items','invoice_payments',
    'quotations','quotation_items','quotation_templates','tool_runs',
    'suppliers','purchase_orders','purchase_order_items','stock_movements',
    'advances','po_payments','payment_receipts','entity_links',
    'campaigns','email_optouts'
  ];
  org_only text[] := array[
    'company_profile','app_settings','audit_log','app_users'
  ];
begin
  foreach t in array tables loop
    execute format(
      'alter table %I add column if not exists org_id text not null default public.current_org();',
      t
    );
    execute format('alter table %I enable row level security;', t);
    execute format('drop trigger if exists %I on %I;', 'trg_' || t || '_updated', t);
    execute format(
      'create trigger %I before update on %I for each row execute function set_updated_at();',
      'trg_' || t || '_updated', t
    );

    -- SECURITY: pin org_id to the caller's org on insert and freeze it on
    -- update (prevents cross-tenant row injection — see force_org_id()).
    execute format('drop trigger if exists %I on %I;', 'trg_' || t || '_org', t);
    execute format(
      'create trigger %I before insert or update on %I for each row execute function public.force_org_id();',
      'trg_' || t || '_org', t
    );

    -- clear any prior policy variants
    execute format('drop policy if exists %I on %I;', t || '_owner', t);
    execute format('drop policy if exists %I on %I;', t || '_org', t);
    execute format('drop policy if exists %I on %I;', t || '_access', t);

    -- PERF: every function call below is wrapped in a scalar subquery so the
    -- planner evaluates it once per query (InitPlan) instead of once per row.
    -- current_org() and is_org_admin() are SECURITY DEFINER functions that run
    -- their own queries, so per-row evaluation dominated every list read.
    if t = any(org_only) then
      execute format(
        'create policy %I on %I for all using (org_id = (select public.current_org())) with check (org_id = (select public.current_org()));',
        t || '_org', t
      );
    else
      execute format(
        'alter table %I add column if not exists shared boolean not null default false;',
        t
      );
      -- SECURITY: the admin / shared branches MUST be scoped to the
      -- caller's own org. is_org_admin() is true for an admin of *their*
      -- org; without the org_id match it would grant access to every
      -- org's rows (cross-tenant leak). Always require org_id = current_org
      -- on anything that isn't the caller's own row.
      execute format(
        'create policy %I on %I for all '
        || 'using (user_id = (select auth.uid()) '
        || 'or (org_id = (select public.current_org()) '
        || 'and ((select public.is_org_admin()) or shared = true))) '
        || 'with check (user_id = (select auth.uid()) '
        || 'or (org_id = (select public.current_org()) and (select public.is_org_admin())));',
        t || '_access', t
      );
    end if;
  end loop;
end $$;

-- Declared after the loop above, which is what adds org_id to these tables.
-- One opt-out per address per org, case-insensitive: someone who unsubscribed
-- as Sales@Acme.ae must not become reachable again as sales@acme.ae.
create unique index if not exists idx_email_optouts_unique
  on email_optouts (org_id, lower(email));
create index if not exists idx_campaigns_org_status on campaigns (org_id, status);

-- ---------- backfill org_id from each row owner's profile ----------
-- When org_id was first added, the default public.current_org() ran with a
-- null auth.uid() (admin/SQL context) and resolved to 'default' for every
-- existing row. That orphans pre-migration rows in org 'default' while a
-- signed-in user's current_org() is their real org UUID, so RLS blocks
-- updates. Re-point each row to its owner's actual org. Idempotent.
-- NOTE: company_profile is intentionally excluded — it has a unique(org_id)
-- constraint and is collapsed to one row per org in its own section below.
-- Backfilling it here (before that dedup) can violate the constraint when
-- legacy duplicates exist, so leave its org_id to the dedicated block.
do $$
declare
  t text;
  tables text[] := array[
    'products','orders','order_items',
    'employees','attendance','payroll',
    'accounts','expenses','transactions',
    'app_users','app_settings','audit_log',
    'crm_leads','crm_customers','crm_opportunities','crm_activities',
    'invoice_docs','invoice_doc_items','invoice_payments',
    'quotations','quotation_items','quotation_templates','tool_runs',
    'suppliers','purchase_orders','purchase_order_items','stock_movements',
    'advances','po_payments','payment_receipts','entity_links'
  ];
begin
  foreach t in array tables loop
    execute format(
      'update public.%I x set org_id = p.org_id
         from public.profiles p
        where x.user_id = p.id
          and x.org_id = ''default''
          and x.org_id is distinct from p.org_id;',
      t
    );
  end loop;
end $$;

-- ---------- company_profile: one shared profile per organization ----------
-- The company identity belongs to the org, not each member. Keep a single
-- row per org, let any member read it, but only org admins (owner/admin)
-- may change it — so invited members cannot rename the company.
do $$
begin
  -- Ambiguous legacy duplicates need an explicit migration/review. Never
  -- delete company data while installing or repeating the canonical schema.
  if exists(select 1 from public.company_profile group by org_id having count(*)>1) then
    raise exception 'Resolve duplicate company profiles with a data-preserving upgrade before installing the canonical schema.';
  end if;

  if exists (
    select 1 from pg_constraint where conname = 'company_profile_user_id_key'
  ) then
    alter table public.company_profile drop constraint company_profile_user_id_key;
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'company_profile_org_id_key'
  ) then
    alter table public.company_profile
      add constraint company_profile_org_id_key unique (org_id);
  end if;
end $$;

-- Read for all org members; write for org admins only.
drop policy if exists company_profile_org on company_profile;
drop policy if exists company_profile_read on company_profile;
drop policy if exists company_profile_write on company_profile;
create policy company_profile_read on company_profile for select
  using (org_id = public.current_org());
create policy company_profile_write on company_profile for all
  using (org_id = public.current_org() and public.is_org_admin())
  with check (org_id = public.current_org() and public.is_org_admin());

-- ---------- auto-provision a personal org + profile on signup ----------
create or replace function handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  new_org uuid;
begin
  insert into public.organizations (id, name, owner_id)
  values (gen_random_uuid(), coalesce(new.email, 'My Organization'), new.id)
  returning id into new_org;

  insert into public.profiles (id, email, name, org_id)
  values (
    new.id,
    coalesce(new.email, ''),
    coalesce(new.raw_user_meta_data->>'full_name', 'User'),
    new_org::text
  )
  on conflict (id) do nothing;

  insert into public.org_members (org_id, user_id, role)
  values (new_org::text, new.id, 'owner')
  on conflict (org_id, user_id) do nothing;

  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function handle_new_user();

-- ---------- realtime: broadcast row changes for live multi-client sync ----------
-- Every table the app reads is added to the supabase_realtime publication
-- so changes from any client (desktop, web, or a direct DB edit) stream to
-- open sessions. RLS still filters the feed: a client only receives changes
-- for rows it may read. Idempotent — safe to re-run.
do $$
declare
  t text;
  rt_tables text[] := array[
    'products','orders','order_items',
    'employees','attendance','payroll',
    'accounts','expenses','transactions',
    'app_users','app_settings','audit_log',
    'crm_leads','crm_customers','crm_opportunities','crm_activities',
    'company_profile','invoice_docs','invoice_doc_items','invoice_payments',
    'quotations','quotation_items','quotation_templates','tool_runs',
    'suppliers','purchase_orders','purchase_order_items','stock_movements',
    'advances',
    'organizations','org_members','profiles','invitations','org_messages',
    'notifications'
  ];
begin
  if not exists (
    select 1 from pg_publication where pubname = 'supabase_realtime'
  ) then
    create publication supabase_realtime;
  end if;
  foreach t in array rt_tables loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime'
        and schemaname = 'public'
        and tablename = t
    ) then
      execute format(
        'alter publication supabase_realtime add table public.%I;', t
      );
    end if;
  end loop;
end $$;

-- ---------- referential integrity + normalization (additive) ----------
-- Bring legacy text-keyed fields into proper relations without breaking
-- any existing rows. Each constraint is added only when missing.

-- New FK columns (safe — defaults to null for legacy rows).
alter table orders          add column if not exists customer_id bigint references crm_customers(id) on delete set null;
alter table invoice_docs    add column if not exists customer_id bigint references crm_customers(id) on delete set null;
alter table quotations      add column if not exists customer_id bigint references crm_customers(id) on delete set null;
alter table invoice_docs    add column if not exists quotation_id bigint references quotations(id) on delete set null;

-- Invoice UI columns (safe additive — live DB already has these; schema.sql drifted).
alter table invoice_docs add column if not exists doc_title text;
alter table invoice_docs add column if not exists po_number text;
alter table invoice_docs add column if not exists payment_terms text;
alter table invoice_docs add column if not exists po_date date;
alter table invoice_docs add column if not exists date_of_supply date;
alter table invoice_docs add column if not exists round_off boolean not null default false;
alter table crm_customers add column if not exists credit_limit numeric(14,2);
alter table crm_customers add column if not exists opening_balance numeric(14,2);
alter table invoice_docs add column if not exists custom_columns jsonb;
alter table invoice_docs add column if not exists unit_price_formula jsonb;
