  to authenticated
  using (
    bucket_id = 'tool-outputs'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- ---------- RETENTION: auto-purge old tool outputs ----------
-- Deletes tool_runs (and their stored files) older than max_age. Run on a
-- schedule via pg_cron when available; client also enforces a per-user
-- storage quota. security definer so the scheduled job may touch storage.
create or replace function public.prune_tool_runs(max_age interval default '30 days')
returns void language plpgsql security definer
set search_path = public, storage as $$
begin
  delete from storage.objects o
   using public.tool_runs r
   where o.bucket_id = 'tool-outputs'
     and o.name = any(r.storage_paths)
     and r.created_at < now() - max_age;
  delete from public.tool_runs where created_at < now() - max_age;
end $$;

do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    -- pg_cron 1.4+ upserts by job name; safe to re-run.
    perform cron.schedule(
      'prune-tool-runs',
      '0 3 * * *',
      'select public.prune_tool_runs();'
    );
  end if;
end $$;

-- ---------- performance: indexes on hot columns ----------
-- RLS filters on user_id/org_id/shared on every query; FKs and created_at
-- are common sort/join keys. Index them so the app stays fast at scale.
do $$
declare
  t text;
  tables text[] := array[
    'products','orders','order_items','employees','attendance','payroll',
    'accounts','expenses','transactions','crm_leads','crm_customers',
    'crm_opportunities','crm_activities','invoice_docs','invoice_doc_items','invoice_payments',
    'quotations','quotation_items','quotation_templates','tool_runs',
    'suppliers','purchase_orders','purchase_order_items','stock_movements',
    'advances','entity_links'
  ];
begin
  foreach t in array tables loop
    execute format('create index if not exists %I on public.%I (org_id);', 'idx_'||t||'_org', t);
    execute format('create index if not exists %I on public.%I (user_id);', 'idx_'||t||'_user', t);
  end loop;
end $$;
create index if not exists idx_order_items_order on public.order_items (order_id);
create index if not exists idx_invoice_doc_items_doc on public.invoice_doc_items (invoice_id);
create index if not exists idx_invoice_payments_invoice on public.invoice_payments (invoice_id);
create index if not exists idx_quotation_items_quote on public.quotation_items (quotation_id);
create index if not exists idx_po_items_po on public.purchase_order_items (po_id);
create index if not exists idx_org_members_user on public.org_members (user_id);
create index if not exists idx_invitations_email on public.invitations (lower(email));
create index if not exists idx_tool_runs_created on public.tool_runs (created_at);

-- ---------- integrity: non-negative money/quantity checks ----------
-- Added NOT VALID so they enforce new/updated rows without failing on any
-- pre-existing data; validate later once data is known clean.
do $$
declare
  c record;
  checks jsonb := jsonb_build_array(
    jsonb_build_object('t','products','n','chk_products_nonneg','e','unit_price >= 0 and cost_price >= 0 and quantity >= 0 and reorder_level >= 0'),
    jsonb_build_object('t','orders','n','chk_orders_nonneg','e','total >= 0'),
    jsonb_build_object('t','order_items','n','chk_order_items_nonneg','e','quantity >= 0 and unit_price >= 0'),
    jsonb_build_object('t','invoice_docs','n','chk_invoice_docs_nonneg','e','tax_rate >= 0 and discount >= 0'),
    jsonb_build_object('t','invoice_doc_items','n','chk_invoice_items_nonneg','e','qty >= 0 and unit_price >= 0'),
    jsonb_build_object('t','invoice_payments','n','chk_invoice_payments_nonneg','e','amount >= 0'),
    jsonb_build_object('t','quotation_items','n','chk_quote_items_nonneg','e','qty >= 0 and rate >= 0'),
    jsonb_build_object('t','expenses','n','chk_expenses_nonneg','e','amount >= 0'),
    jsonb_build_object('t','transactions','n','chk_txn_nonneg','e','amount >= 0'),
    jsonb_build_object('t','payroll','n','chk_payroll_nonneg','e','basic >= 0 and allowances >= 0 and deductions >= 0'),
    jsonb_build_object('t','purchase_order_items','n','chk_po_items_nonneg','e','quantity >= 0 and unit_cost >= 0')
  );
begin
  for c in select * from jsonb_to_recordset(checks) as x(t text, n text, e text) loop
    if not exists (select 1 from pg_constraint where conname = c.n) then
      execute format('alter table public.%I add constraint %I check (%s) not valid;', c.t, c.n, c.e);
    end if;
  end loop;
end $$;

-- ---------- audit log: auto-record create/update/delete ----------
-- Populates audit_log for key entities with the acting user + entity ref.
-- security definer so it can write the row regardless of the caller's RLS;
-- failures never block the underlying operation.
create or replace function public.log_audit()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  actor_name text;
  rid text;
  diff jsonb;
  old_j jsonb;
  new_j jsonb;
begin
  begin
    select coalesce(name, email, 'system') into actor_name
      from public.profiles where id = auth.uid();

    if (TG_OP = 'DELETE') then
      rid  := old.id::text;
      diff := jsonb_build_object('_deleted', to_jsonb(old));
    elsif (TG_OP = 'INSERT') then
      rid  := new.id::text;
      diff := jsonb_build_object('_created', to_jsonb(new));
    else
      -- UPDATE: record only the columns that actually changed (old -> new),
      -- ignoring updated_at noise. A no-op update writes no audit row.
      rid   := new.id::text;
      old_j := to_jsonb(old);
      new_j := to_jsonb(new);
      select coalesce(
               jsonb_object_agg(k, jsonb_build_object('old', old_j -> k, 'new', new_j -> k)),
               '{}'::jsonb)
        into diff
        from jsonb_object_keys(new_j) as k
       where (new_j -> k) is distinct from (old_j -> k)
         and k <> 'updated_at';
      if diff = '{}'::jsonb then
        return new;
      end if;
    end if;

    insert into public.audit_log (actor, action, entity, details, changes, org_id, user_id)
    values (
      coalesce(actor_name, 'system'),
      lower(TG_OP),
      TG_TABLE_NAME,
      TG_TABLE_NAME || ' #' || coalesce(rid, '?'),
      diff,
      public.current_org(),
      auth.uid()
    );
  exception when others then
    null; -- never let auditing break the real write
  end;
  if (TG_OP = 'DELETE') then return old; else return new; end if;
end $$;

do $$
declare
  t text;
  audited text[] := array[
    'products','orders','invoice_docs','quotations','crm_customers',
    'crm_leads','crm_opportunities','expenses','suppliers',
    'purchase_orders','employees','payroll',
    'invoice_payments','po_payments','advances'   -- money movements belong in the trail
  ];
begin
  foreach t in array audited loop
    execute format('drop trigger if exists %I on public.%I;', 'trg_audit_'||t, t);
    execute format(
      'create trigger %I after insert or update or delete on public.%I '
      || 'for each row execute function public.log_audit();',
      'trg_audit_'||t, t
    );
  end loop;
end $$;

-- ---------- audit_log is append-only (immutable) ----------
-- Members may READ their org's trail and APPEND rows (manual logAction + the
-- log_audit trigger), but NO ONE may update or delete an audit row — not even
-- an org admin. Immutability is the whole point of an audit log. Replace the
-- generic `audit_log_org` (for all) policy with explicit select + insert; the
-- absence of update/delete policies makes RLS deny those by default.
drop policy if exists audit_log_org on audit_log;
drop policy if exists audit_log_select on audit_log;
drop policy if exists audit_log_insert on audit_log;
create policy audit_log_select on audit_log for select
  using (org_id = public.current_org());
create policy audit_log_insert on audit_log for insert
  with check (org_id = public.current_org());

-- ---------- atomic counter updates (avoid lost-update races) ----------
-- The app is realtime/multi-client, so client-side read-modify-write on a
-- counter (select → compute → update) loses concurrent updates. These do the
-- arithmetic in a single statement. SECURITY INVOKER (default) so RLS still
-- scopes the write to rows the caller may update.
-- Deliberately NOT greatest(0, …). Every move through this function has a
-- reverse (revert an invoice to draft, delete a bill), and clamping made the
-- pair asymmetric: selling 5 from a stock of 3 clamped to 0, and reverting it
-- added 5 back to leave 5 where 3 had been. Overselling invented inventory and
-- desynced the products row from the stock_movements ledger, which records the
-- true -5/+5. Negative stock is a fact worth keeping — it says units are owed.
create or replace function public.adjust_product_stock(p_id bigint, p_delta numeric)
returns bigint language sql as $$
  update public.products
     set quantity = quantity + p_delta
   where id = p_id
  returning quantity;
$$;
grant execute on function public.adjust_product_stock(bigint, numeric) to authenticated;

create or replace function public.adjust_account_balance(p_id bigint, p_delta numeric)
returns numeric language sql as $$
  update public.accounts
     set balance = balance + p_delta
   where id = p_id
  returning balance;
$$;
grant execute on function public.adjust_account_balance(bigint, numeric) to authenticated;

-- Done. Tables are row-level-secured to the signed-in user.

