-- ---------- local → cloud push support ----------
-- After "Push local data to cloud" inserts rows with their original local ids,
-- each identity sequence must jump past max(id) or the next normal insert
-- collides. Security definer (sequences need owner rights); only ever moves
-- sequences FORWARD to the table''s current max — harmless to call anytime.
create or replace function public.sync_bump_sequences()
returns void
language plpgsql
security definer
set search_path = public
as $fn$
declare
  t text;
  seq text;
  mx bigint;
  tables text[] := array[
    'products','orders','order_items',
    'employees','attendance','payroll',
    'accounts','expenses','transactions',
    'app_users','app_settings','audit_log',
    'crm_leads','crm_customers','crm_opportunities','crm_activities',
    'company_profile','invoice_docs','invoice_doc_items','invoice_payments',
    'quotations','quotation_items','quotation_templates','tool_runs',
    'suppliers','purchase_orders','purchase_order_items','stock_movements',
    'advances','po_payments','payment_receipts','entity_links','follow_ups',
    'invoice_recurrence','notifications',
    'campaigns','email_optouts'
  ];
begin
  foreach t in array tables loop
    begin
      seq := pg_get_serial_sequence('public.' || quote_ident(t), 'id');
      if seq is null then continue; end if;
      execute format('select coalesce(max(id),0) from public.%I', t) into mx;
      if mx > 0 then
        perform setval(seq, mx);
      end if;
    exception when others then
      null; -- table without numeric id / missing table: skip
    end;
  end loop;
end $fn$;

revoke all on function public.sync_bump_sequences() from public;
grant execute on function public.sync_bump_sequences() to authenticated;

-- ---------- licensing: one-time desktop licenses + device slots ----------

create table if not exists licenses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  product text not null default 'filey-desktop',
  status text not null default 'active',            -- active | revoked
  stripe_payment_intent text,                       -- legacy: Stripe-era purchases
  dodo_payment_id text,                             -- current: Dodo Payments
  created_at timestamptz not null default now()
);
-- Idempotency for the Dodo webhook; NULL for Stripe-era and voucher licences.
create unique index if not exists licenses_dodo_payment_id_key
  on public.licenses (dodo_payment_id)
  where dodo_payment_id is not null;

create table if not exists license_devices (
  id uuid primary key default gen_random_uuid(),
  license_id uuid not null references licenses(id) on delete cascade,
  fingerprint text not null,
  device_name text,
  activated_at timestamptz not null default now(),
  deactivated_at timestamptz
);

create unique index if not exists idx_license_devices_unique
  on license_devices(license_id, fingerprint);
create index if not exists idx_licenses_user on licenses(user_id);

alter table licenses enable row level security;
drop policy if exists licenses_read on licenses;
create policy licenses_read on licenses for select
  using (user_id = auth.uid());

alter table license_devices enable row level security;
drop policy if exists license_devices_read on license_devices;
create policy license_devices_read on license_devices for select
  using (exists (
    select 1 from licenses l
    where l.id = license_id and l.user_id = auth.uid()
  ));


-- ---------- cloud device registry: 20 devices per org ----------

create table if not exists org_devices (
  id uuid primary key default gen_random_uuid(),
  org_id text not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  fingerprint text not null,
  device_name text,
  last_seen timestamptz not null default now(),
  created_at timestamptz not null default now()
);

create unique index if not exists idx_org_devices_unique
  on org_devices(org_id, fingerprint);
create index if not exists idx_org_devices_org on org_devices(org_id);

alter table org_devices enable row level security;

-- Members see their org's devices; a member may release their own device,
-- an org admin may release any. Inserts/updates happen only through the
-- register_device() RPC (security definer) so the 20-slot limit can't be
-- bypassed with a direct insert.
drop policy if exists org_devices_select on org_devices;
create policy org_devices_select on org_devices for select
  using (org_id = public.current_org());

drop policy if exists org_devices_delete on org_devices;
create policy org_devices_delete on org_devices for delete
  using (org_id = public.current_org()
         and (user_id = auth.uid() or public.is_org_admin()));

create or replace function public.register_device(p_fingerprint text, p_name text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_org text := public.current_org();
  v_id uuid;
  v_active int;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  end if;
  if p_fingerprint is null or length(trim(p_fingerprint)) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'missing_fingerprint');
  end if;

  -- SECURITY: serialize per-org registrations — two devices racing the
  -- count check below could both pass and exceed the slot limit (TOCTOU).
  perform pg_advisory_xact_lock(hashtext('org_devices:' || v_org));

  select id into v_id
    from org_devices
   where org_id = v_org and fingerprint = p_fingerprint;

  if v_id is not null then
    update org_devices
       set last_seen = now(),
           user_id = auth.uid(),
           device_name = coalesce(nullif(p_name, ''), device_name)
     where id = v_id;
    return jsonb_build_object('ok', true, 'existing', true);
  end if;

  select count(*) into v_active from org_devices where org_id = v_org;
  if v_active >= 20 then
    return jsonb_build_object('ok', false, 'reason', 'limit', 'limit', 20);
  end if;

  insert into org_devices (org_id, user_id, fingerprint, device_name)
  values (v_org, auth.uid(), p_fingerprint, nullif(p_name, ''));
  return jsonb_build_object('ok', true);
end $fn$;

revoke all on function public.register_device(text, text) from public;
grant execute on function public.register_device(text, text) to authenticated;


-- ---------- agent pending actions: confirm-gated channel agent ----------

create table if not exists agent_pending_actions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  org_id text not null,
  code text not null,                       -- short approval code the owner types
  action text not null,                     -- e.g. 'send_payment_reminder'
  payload jsonb not null default '{}'::jsonb,
  status text not null default 'pending',   -- pending | approved | rejected | expired
  created_at timestamptz not null default now(),
  executed_at timestamptz
);

create index if not exists idx_agent_pending_user
  on agent_pending_actions(user_id, status);

alter table agent_pending_actions enable row level security;
drop policy if exists agent_pending_read on agent_pending_actions;
create policy agent_pending_read on agent_pending_actions for select
  using (user_id = auth.uid());


-- ---------- desktop → cloud auto-sync bookkeeping ----------
-- One row per (user, table): when the desktop's auto-sync (src/lib/sync.ts)
-- last pushed that table. Lets the web UI show "desktop last synced …" and
-- makes sync failures diagnosable. Written by the desktop client as the
-- signed-in user; RLS keeps it per-account.

create table if not exists sync_state (
  user_id uuid not null references auth.users(id) on delete cascade,
  table_name text not null,
  synced_at timestamptz not null default now(),
  primary key (user_id, table_name)
);

alter table sync_state enable row level security;
drop policy if exists sync_state_own on sync_state;
create policy sync_state_own on sync_state for all
  using (user_id = auth.uid())
  with check (user_id = auth.uid());




