-- RLS: users see only rows in their current org.
-- Helper for org membership (already present from schema.sql usually, but safe to create).
create or replace function current_org_id() returns text as $$
  select current_setting('app.current_org_id', true);
$$ language sql stable;

drop policy if exists "org_isolation" on sms_providers;
create policy "org_isolation" on sms_providers
  for all to authenticated
  using (org_id = current_org_id())
  with check (org_id = current_org_id());

drop policy if exists "org_isolation" on sms_templates;
create policy "org_isolation" on sms_templates
  for all to authenticated
  using (org_id = current_org_id())
  with check (org_id = current_org_id());

drop policy if exists "org_isolation" on sms_logs;
create policy "org_isolation" on sms_logs
  for all to authenticated
  using (org_id = current_org_id())
  with check (org_id = current_org_id());

drop policy if exists "org_isolation" on otp_codes;
create policy "org_isolation" on otp_codes
  for all to authenticated
  using (org_id = current_org_id())
  with check (org_id = current_org_id());

drop policy if exists "org_isolation" on custom_entity_fields;
create policy "org_isolation" on custom_entity_fields
  for all to authenticated
  using (org_id = current_org_id())
  with check (org_id = current_org_id());

drop policy if exists "org_isolation" on custom_entity_values;
create policy "org_isolation" on custom_entity_values
  for all to authenticated
  using (org_id = current_org_id())
  with check (org_id = current_org_id());

-- Trigger: set updated_at
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

drop trigger if exists set_updated_at on sms_providers;
create trigger set_updated_at before update on sms_providers
  for each row execute procedure set_updated_at();

drop trigger if exists set_updated_at on sms_templates;
create trigger set_updated_at before update on sms_templates
  for each row execute procedure set_updated_at();

drop trigger if exists set_updated_at on custom_entity_fields;
create trigger set_updated_at before update on custom_entity_fields
  for each row execute procedure set_updated_at();

drop trigger if exists set_updated_at on custom_entity_values;
create trigger set_updated_at before update on custom_entity_values
  for each row execute procedure set_updated_at();
