-- ============================================================
--  Filey ERP — Unify Quotation / Purchase Order / Payment Receipt
--  document model with invoice_docs parity.
--  Safe to re-run (idempotent).
-- ============================================================

-- ----- Quotations -----
alter table public.quotations add column if not exists custom_columns jsonb;
