-- Source: supabase/2026-09-21-ai-video.sql
do $filey_bootstrap$
begin
  if exists(select 1 from public.filey_bootstrap_migrations where name='2026-09-21-ai-video.sql' and source_sha256<>'d8cdfc6dc57c822e649399145f3391248336931c6c6ee1530895f2addfe926d3') then
    raise exception 'Installed bootstrap source 2026-09-21-ai-video.sql changed. Use a new reviewed upgrade migration instead of rewriting installed history.';
  end if;
