  if exists(select 1 from public.filey_bootstrap_migrations where name='2026-09-30-channel-agent-drafts.sql' and source_sha256<>'7b45f356ebca47f0412a2f1f07dafca4def7248ba5f9c0156d79e59865e07465') then
