  if exists(select 1 from public.filey_bootstrap_migrations where name='2026-09-30-stripe-payment-integrity.sql' and source_sha256<>'af3cb12f1ad3890cde3a62542f7b32ccdc4caaceea18d6ca6bd7167d71d37f4a') then
