do $filey_bootstrap$
begin
  if exists(select 1 from public.filey_bootstrap_migrations where name='2026-10-03-stocktake-reliability.sql' and source_sha256<>'b7f59d4dc9b193b63bdc4d3e1d1293964945483eacd81bb928e6176a4b385f3e') then
    raise exception 'Installed bootstrap source 2026-10-03-stocktake-reliability.sql changed. Use a new reviewed upgrade migration instead of rewriting installed history.';
  end if;
