alter table crm_customers add column if not exists country_code text;           -- default AE
alter table public.invoice_docs add column if not exists einvoice jsonb;
alter table public.company_profile add column if not exists einvoice jsonb;
comment on column public.invoice_docs.einvoice is 'PINT-AE document UUID and seller/buyer identity snapshots. Never store provider credentials here.';
comment on column public.company_profile.einvoice is 'Corporate Tax identity and registered electronic address, separate from VAT TRN.';

-- Protect identity through all cloud writers, including stale clients/sync.
create or replace function public.preserve_einvoice_uuid() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.einvoice is not null and jsonb_typeof(new.einvoice) <> 'object' then
    raise exception 'E-invoice details must be an object.';
  end if;
  if tg_op = 'UPDATE' and old.einvoice->>'uuid' is not null then
    new.einvoice := coalesce(new.einvoice, old.einvoice) || jsonb_build_object('uuid', old.einvoice->>'uuid');
  end if;
  return new;
end;
$$;
drop trigger if exists invoice_einvoice_identity on public.invoice_docs;
create trigger invoice_einvoice_identity before insert or update on public.invoice_docs
for each row execute function public.preserve_einvoice_uuid();
notify pgrst, 'reload schema';

-- Mirrored from 2026-09-30-channel-agent-drafts.sql
-- Hosted relay only: draft header, lines and audit trail commit together.
-- Apply before deploying the hardened channel-webhook. No customer rows change.

create or replace function public.filey_channel_create_draft(
  p_owner uuid, p_org text, p_kind text, p_input jsonb
) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_id bigint; v_number text; v_name text; v_currency text;
  v_items jsonb; v_item jsonb; v_qty numeric; v_price numeric;
  v_tax numeric := 0; v_total numeric := 0; v_position integer := 0;
  v_allowed text[]; v_line_allowed text[]; v_supplier bigint;
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'Hosted agent access required' using errcode='42501';
  end if;
  -- Service role bypasses RLS: pin the current workspace and active admin
  -- membership, and hold both rows until the document transaction commits.
  perform 1 from public.profiles p join public.org_members m
    on m.user_id=p.id and m.org_id=p.org_id
    where p.id=p_owner and p.org_id=p_org and m.role in ('owner','admin')
    for share of p,m;
  if not found then raise exception 'Workspace access denied' using errcode='42501'; end if;
  if p_kind='invoice' then
    v_allowed := array['customer_name','customer_email','items','currency','tax_rate'];
  elsif p_kind='quote' then
    v_allowed := array['customer_name','items','currency'];
  elsif p_kind='po' then
    v_allowed := array['supplier_name','items','currency'];
  else raise exception 'Unsupported draft type' using errcode='22023'; end if;
  if p_input is null or jsonb_typeof(p_input)<>'object'
    or exists(select 1 from jsonb_object_keys(p_input) k where not k=any(v_allowed)) then
    raise exception 'Invalid draft fields' using errcode='22023';
  end if;
  v_name := trim(p_input->>case when p_kind='po' then 'supplier_name' else 'customer_name' end);
  v_currency := upper(coalesce(p_input->>'currency','AED'));
  v_items := p_input->'items';
  if jsonb_typeof(p_input->case when p_kind='po' then 'supplier_name' else 'customer_name' end) is distinct from 'string'
    or (p_input ? 'currency' and jsonb_typeof(p_input->'currency')<>'string')
    or v_name is null or length(v_name) not between 1 and 200 or v_currency !~ '^[A-Z]{3}$'
    or v_items is null or jsonb_typeof(v_items)<>'array' then
    raise exception 'Invalid draft name, currency or items' using errcode='22023';
  end if;
  if jsonb_array_length(v_items) not between 1 and 30 then
    raise exception 'A draft needs 1 to 30 lines' using errcode='22023';
  end if;
  if p_kind='invoice' then
    if p_input ? 'tax_rate' and jsonb_typeof(p_input->'tax_rate')<>'number' then raise exception 'Invalid tax rate' using errcode='22023'; end if;
    v_tax := coalesce((p_input->>'tax_rate')::numeric,5);
    if v_tax not between 0 and 100 then raise exception 'Invalid tax rate' using errcode='22023'; end if;
    if p_input ? 'customer_email' and (jsonb_typeof(p_input->'customer_email')<>'string'
      or length(p_input->>'customer_email')>200) then raise exception 'Invalid customer email' using errcode='22023'; end if;
  end if;
  v_line_allowed := array['description','qty',case when p_kind='po' then 'unit_cost' else 'unit_price' end];
  for v_item in select value from jsonb_array_elements(v_items) loop
    if jsonb_typeof(v_item)<>'object'
      or exists(select 1 from jsonb_object_keys(v_item) k where not k=any(v_line_allowed))
      or jsonb_typeof(v_item->'description') is distinct from 'string'
      or length(trim(v_item->>'description')) not between 1 and 300
      or jsonb_typeof(v_item->case when p_kind='po' then 'unit_cost' else 'unit_price' end) is distinct from 'number'
      or (v_item ? 'qty' and jsonb_typeof(v_item->'qty')<>'number') then
      raise exception 'Invalid draft line' using errcode='22023';
    end if;
    v_qty := coalesce((v_item->>'qty')::numeric,1);
    v_price := (v_item->>case when p_kind='po' then 'unit_cost' else 'unit_price' end)::numeric;
    if v_qty not between 0.001 and 1000000 or v_price not between 0 and 1000000000 then
      raise exception 'Invalid draft quantity or price' using errcode='22023';
    end if;
    -- Numeric columns retain 3 quantity decimals and 2 price decimals. Do
    -- not report a total from values that would be rounded on insertion.
    if v_qty<>round(v_qty,3) or v_price<>round(v_price,2) then
      raise exception 'Draft quantity or price has unsupported precision' using errcode='22023';
    end if;
    -- Match Filey's document totals: round each line amount before summing.
    v_total := v_total + round(v_qty*v_price,2);
  end loop;
  v_total := round(v_total*(1+v_tax/100),2);
  if v_total>999999999999.99 then raise exception 'Draft total is too large' using errcode='22023'; end if;
  v_number := (case p_kind when 'invoice' then 'INV' when 'quote' then 'Q' else 'PO' end)
    || '-' || extract(year from current_date)::text || '-A' || left(replace(gen_random_uuid()::text,'-',''),12);
  if p_kind='invoice' then
    insert into public.invoice_docs(user_id,org_id,number,status,currency,customer_name,customer_email,doc_type,tax_rate,issue_date)
    values(p_owner,p_org,v_number,'draft',v_currency,v_name,nullif(p_input->>'customer_email',''),'invoice',v_tax,current_date) returning id into v_id;
  elsif p_kind='quote' then
    insert into public.quotations(user_id,org_id,number,status,currency,customer_name,quote_date)
    values(p_owner,p_org,v_number,'draft',v_currency,v_name,current_date) returning id into v_id;
  else
    -- Exact, unique supplier match only; never choose the first fuzzy match.
    select min(id) into v_supplier from public.suppliers where org_id=p_org and lower(name)=lower(v_name) having count(*)=1;
    insert into public.purchase_orders(user_id,org_id,po_number,status,currency,supplier_id,supplier_name,total,order_date)
    values(p_owner,p_org,v_number,'draft',v_currency,v_supplier,v_name,v_total,current_date) returning id into v_id;
  end if;
  for v_item in select value from jsonb_array_elements(v_items) loop
    v_qty := coalesce((v_item->>'qty')::numeric,1);
    if p_kind='invoice' then
      insert into public.invoice_doc_items(user_id,org_id,invoice_id,description,qty,unit_price,position)
      values(p_owner,p_org,v_id,trim(v_item->>'description'),v_qty,(v_item->>'unit_price')::numeric,v_position);
    elsif p_kind='quote' then
      insert into public.quotation_items(user_id,org_id,quotation_id,product,qty,rate,position)
      values(p_owner,p_org,v_id,trim(v_item->>'description'),v_qty,(v_item->>'unit_price')::numeric,v_position);
    else
      insert into public.purchase_order_items(user_id,org_id,po_id,description,quantity,unit_cost,position)
      values(p_owner,p_org,v_id,trim(v_item->>'description'),v_qty,(v_item->>'unit_cost')::numeric,v_position);
    end if;
    v_position := v_position+1;
  end loop;
  insert into public.audit_log(user_id,actor,action,entity,details)
    values(p_owner,'agent','agent.create_draft_'||p_kind,p_kind||':'||v_id,v_number||' saved as a draft');
  return jsonb_build_object('created','draft','id',v_id,'number',v_number,'total',v_total,'currency',v_currency,
    'note','Draft saved in Filey for review. It has not been sent.');
end;
$$;
revoke all on function public.filey_channel_create_draft(uuid,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.filey_channel_create_draft(uuid,text,text,jsonb) to service_role;
notify pgrst,'reload schema';

-- September 30 scheduled/license write integrity (additive).
-- Apply before deploying dodo/stripe and agent-jobs. No existing rows change.

create or replace function public.filey_claim_license_device(
  p_user uuid, p_fingerprint text, p_device_name text default ''
) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_license public.licenses; v_device public.license_devices;
begin
  if coalesce(auth.role(),'')<>'service_role' then
    raise exception 'License service access required' using errcode='42501';
  end if;
  if p_user is null or p_fingerprint is null or length(p_fingerprint) not between 1 and 256
    or length(coalesce(p_device_name,''))>200 then
    raise exception 'Invalid device' using errcode='22023';
  end if;
  select * into v_license from public.licenses
    where user_id=p_user and status='active' order by created_at,id limit 1 for update;
  if not found then raise exception 'No active license' using errcode='PT404'; end if;
  select * into v_device from public.license_devices
    where license_id=v_license.id and fingerprint=p_fingerprint;
  if v_device.id is not null and v_device.deactivated_at is null then
    return jsonb_build_object('license_id',v_license.id,'product',v_license.product);
  end if;
  if (select count(*) from public.license_devices where license_id=v_license.id and deactivated_at is null)>=2 then
    raise exception 'Device slots full' using errcode='PT409';
  end if;
  insert into public.license_devices(license_id,fingerprint,device_name)
    values(v_license.id,p_fingerprint,nullif(p_device_name,''))
    on conflict(license_id,fingerprint) do update
      set deactivated_at=null,activated_at=now(),device_name=excluded.device_name;
  return jsonb_build_object('license_id',v_license.id,'product',v_license.product);
end $$;
revoke all on function public.filey_claim_license_device(uuid,text,text) from public,anon,authenticated;
grant execute on function public.filey_claim_license_device(uuid,text,text) to service_role;

create or replace function public.filey_agent_lowstock_po(p_owner uuid,p_org text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_group record; v_product record; v_supplier public.suppliers;
  v_id bigint; v_number text; v_qty numeric; v_total numeric; v_position integer;
  v_created jsonb := '[]'::jsonb;
begin
  if coalesce(auth.role(),'')<>'service_role' then
    raise exception 'Scheduled agent access required' using errcode='42501';
  end if;
  perform 1 from public.profiles p join public.org_members m on m.user_id=p.id and m.org_id=p.org_id
    where p.id=p_owner and p.org_id=p_org and m.role in ('owner','admin') for share of p,m;
  if not found then raise exception 'Workspace access denied' using errcode='42501'; end if;
  -- Concurrent schedules share one transaction lock. Header, lines and audit
  -- either all commit or all roll back; no empty draft can mask a retry.
  perform pg_advisory_xact_lock(hashtextextended('filey-lowstock:'||p_org||':'||current_date,0));
  for v_group in select distinct supplier_id from public.products
    where org_id=p_org and reorder_level>0 and quantity<=reorder_level loop
    if exists(select 1 from public.purchase_orders po where po.org_id=p_org
      and po.supplier_id is not distinct from v_group.supplier_id and po.order_date=current_date
      and po.notes='Auto-created from low stock (agent)'
      and exists(select 1 from public.purchase_order_items i where i.po_id=po.id and i.org_id=p_org)) then
      continue;
    end if;
    v_supplier := null;
    if v_group.supplier_id is not null then
      select * into v_supplier from public.suppliers where id=v_group.supplier_id and org_id=p_org for share;
      if not found then raise exception 'Low-stock supplier is outside this workspace' using errcode='42501'; end if;
    end if;
    v_number := 'PO-'||extract(year from current_date)::text||'-A'||left(replace(gen_random_uuid()::text,'-',''),12);
    insert into public.purchase_orders(user_id,org_id,po_number,status,supplier_id,supplier_name,
      supplier_address,supplier_email,supplier_phone,supplier_trn,currency,total,order_date,notes)
    values(p_owner,p_org,v_number,'draft',v_group.supplier_id,coalesce(v_supplier.name,''),
      coalesce(v_supplier.address,''),coalesce(v_supplier.email,''),coalesce(v_supplier.phone,''),
      coalesce(v_supplier.tax_id,''),'AED',0,current_date,'Auto-created from low stock (agent)') returning id into v_id;
    v_total := 0; v_position := 0;
    for v_product in select * from public.products where org_id=p_org
      and supplier_id is not distinct from v_group.supplier_id and reorder_level>0 and quantity<=reorder_level
      order by id for share loop
      v_qty := greatest(1,2*v_product.reorder_level-v_product.quantity);
      if v_product.cost_price<0 then raise exception 'Invalid low-stock product cost' using errcode='22023'; end if;
      insert into public.purchase_order_items(user_id,org_id,po_id,product_id,description,quantity,unit_cost,unit,position)
        values(p_owner,p_org,v_id,v_product.id,v_product.name,v_qty,v_product.cost_price,v_product.unit,v_position);
      v_total := v_total+round(v_qty*v_product.cost_price,2); v_position := v_position+1;
    end loop;
    if v_position=0 then raise exception 'Stock changed during draft creation; retry' using errcode='40001'; end if;
    update public.purchase_orders set total=v_total where id=v_id;
    insert into public.audit_log(user_id,actor,action,entity,details)
      values(p_owner,'agent','agent.lowstock_po','purchase_orders:'||v_id,v_number||' saved as a draft');
    v_created := v_created||jsonb_build_array(jsonb_build_object('id',v_id,'number',v_number,'supplier_name',coalesce(v_supplier.name,'')));
  end loop;
  return v_created;
end $$;
revoke all on function public.filey_agent_lowstock_po(uuid,text) from public,anon,authenticated;
grant execute on function public.filey_agent_lowstock_po(uuid,text) to service_role;
notify pgrst,'reload schema';

-- October 1 team owner membership integrity (additive).
-- Protect workspace ownership in direct PostgREST and definer RPC writes.
-- Existing memberships are not rewritten. Trusted account/workspace cleanup
-- and future server-managed owner transfers remain available to service role.

do $$ begin
  if has_column_privilege('authenticated','public.organizations','owner_id','UPDATE')
    or has_column_privilege('anon','public.organizations','owner_id','UPDATE') then
    raise exception 'Apply 2026-09-30-workspace-billing-acl.sql before team owner integrity';
  end if;
end $$;
create or replace function public.filey_guard_team_owner()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_owner uuid;
begin
  if auth.uid() is null or coalesce(auth.role(),'')='service_role' then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if tg_op='UPDATE' and (new.org_id is distinct from old.org_id or new.user_id is distinct from old.user_id) then
    raise exception 'Team membership identity cannot be changed' using errcode='42501';
  end if;
  if tg_op='INSERT' then
    select owner_id into v_owner from public.organizations where id::text=new.org_id for share;
  else
    select owner_id into v_owner from public.organizations where id::text=old.org_id for share;
  end if;
  if tg_op='DELETE' then
    if old.user_id=v_owner then raise exception 'The workspace owner cannot leave or be removed. Delete the workspace instead.' using errcode='42501'; end if;
    return old;
  end if;
  if new.user_id=v_owner and new.role<>'owner' then
    raise exception 'The workspace owner role cannot be changed' using errcode='42501';
  end if;
  if new.role='owner' and (v_owner is null or new.user_id<>v_owner) then
    raise exception 'Only the workspace owner may hold the owner role' using errcode='42501';
  end if;
  return new;
end $$;
drop trigger if exists filey_guard_team_owner on public.org_members;
create trigger filey_guard_team_owner before insert or update or delete on public.org_members
  for each row execute function public.filey_guard_team_owner();
revoke all on function public.filey_guard_team_owner() from public,anon,authenticated;
notify pgrst,'reload schema';

-- October 1 Stripe subscription ordering integrity
-- Apply after workspace-billing-acl and before deploying stripe.
-- Current provider state is passed only by the verified service-role handler.

do $$ begin
  if has_column_privilege('authenticated','public.organizations','stripe_subscription_id','UPDATE') then
    raise exception 'Apply 2026-09-30-workspace-billing-acl.sql before Stripe subscription integrity';
  end if;
end $$;
alter table public.organizations
  add column if not exists stripe_event_at timestamptz,
  add column if not exists stripe_observed_at timestamptz,
  add column if not exists stripe_subscription_created_at timestamptz;
revoke insert(stripe_event_at,stripe_observed_at,stripe_subscription_created_at),
  update(stripe_event_at,stripe_observed_at,stripe_subscription_created_at)
  on public.organizations from public,anon,authenticated;

create or replace function public.filey_apply_stripe_subscription(
  p_subscription text,p_customer text,p_org text,p_plan text,p_status text,
  p_period_end timestamptz,p_created_at timestamptz,p_event_at timestamptz,p_observed_at timestamptz,p_bind boolean default false
) returns text language plpgsql security definer set search_path=public,pg_temp as $$
declare v_org public.organizations; v_paid boolean := p_status in ('active','trialing','past_due');
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'Billing service access required' using errcode='42501'; end if;
  if p_subscription is null or p_subscription !~ '^sub_[A-Za-z0-9]+$'
    or p_customer is null or p_customer !~ '^cus_[A-Za-z0-9]+$'
    or p_plan is null or p_plan not in ('pro','business')
    or p_status is null or p_status not in ('active','trialing','past_due','incomplete','incomplete_expired','canceled','unpaid','paused')
    or p_period_end is null or p_created_at is null or p_event_at is null or p_observed_at is null then
    raise exception 'Invalid subscription state' using errcode='22023';
  end if;
  if (select count(*) from public.organizations where stripe_customer_id=p_customer)>1 then
    raise exception 'Stripe customer workspace is ambiguous' using errcode='42501';
  end if;
  select * into v_org from public.organizations where stripe_customer_id=p_customer
    and (p_org is null or id::text=p_org) for update;
  if not found then raise exception 'Stripe customer workspace is not authorized' using errcode='42501'; end if;
  -- A shared customer never permits moving a subscription to another org.
  if exists(select 1 from public.organizations where stripe_subscription_id=p_subscription and id<>v_org.id) then
    raise exception 'Subscription belongs to another workspace' using errcode='42501';
  end if;
  if v_org.stripe_subscription_id is not null and v_org.stripe_subscription_id<>p_subscription then
    -- Only a verified paid checkout can replace a bound subscription. Old
    -- lifecycle events cannot retake the workspace using a customer id.
    if not coalesce(p_bind,false) or not v_paid then return 'ignored replaced subscription'; end if;
    if v_org.stripe_subscription_created_at is not null and p_created_at<=v_org.stripe_subscription_created_at then
      return 'ignored older subscription';
    end if;
    if v_org.plan in ('pro','business') and v_org.plan_status in ('active','trialing','past_due') then
      return 'another Stripe subscription is active';
    end if;
  end if;
  if v_org.stripe_event_at is not null and (p_event_at<v_org.stripe_event_at
    or (p_event_at=v_org.stripe_event_at and p_observed_at<=v_org.stripe_observed_at)) then
    return 'ignored older event';
  end if;
  -- Stripe cancellation is terminal for a subscription id. Same-second
  -- delivery races must never resurrect an already canceled subscription.
  if v_org.stripe_subscription_id=p_subscription and v_org.plan_status in ('canceled','incomplete_expired') and v_paid then
    return 'ignored terminal subscription';
  end if;
  -- A Stripe retry/cancellation cannot revoke the other provider's access or
  -- an owner's permanent Ultra license. These are separate entitlements.
  if v_org.plan='ultra' or v_org.cloud_grandfathered
    or exists(select 1 from public.licenses where user_id=v_org.owner_id and status='active')
    or (v_org.dodo_subscription_id is not null and (
      (v_org.plan='cloud' and v_org.plan_status in ('active','trialing','past_due'))
      or exists(select 1 from public.pending_entitlements where dodo_subscription_id=v_org.dodo_subscription_id
        and plan_status in ('active','trialing','past_due')))) then
    return 'protected by another entitlement';
  end if;
  update public.organizations set plan=case when v_paid then p_plan else 'free' end,
    plan_status=p_status,current_period_end=p_period_end,stripe_subscription_id=p_subscription,
    stripe_subscription_created_at=p_created_at,stripe_event_at=p_event_at,stripe_observed_at=p_observed_at
    where id=v_org.id;
  return 'applied';
end $$;
revoke all on function public.filey_apply_stripe_subscription(text,text,text,text,text,timestamptz,timestamptz,timestamptz,timestamptz,boolean)
  from public,anon,authenticated;
grant execute on function public.filey_apply_stripe_subscription(text,text,text,text,text,timestamptz,timestamptz,timestamptz,timestamptz,boolean) to service_role;
notify pgrst,'reload schema';

-- Correspondence uses the existing org-scoped settings and sync revisions.
-- Apply after the packaging/module-access migrations. No business rows change.

alter table public.app_settings drop constraint if exists app_settings_user_id_key;
alter table public.app_settings drop constraint if exists app_settings_user_id_key_key;
drop index if exists public.app_settings_user_id_key;
drop index if exists public.app_settings_user_id_key_key;
drop index if exists public.app_settings_user_setting_key;
create unique index app_settings_user_setting_key
  on public.app_settings(user_id,key) where key not in ('packaging_lists','letters');
create unique index if not exists app_settings_packaging_org_key
  on public.app_settings(org_id,key) where key = 'packaging_lists';
create unique index if not exists app_settings_letters_org_key
  on public.app_settings(org_id,key) where key = 'letters';

create or replace function public.filey_setting_access(p_key text,p_write boolean default false) returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
  select exists(select 1 from public.org_members m
    where m.user_id=auth.uid() and m.org_id=public.current_org() and
      (m.role in ('owner','admin') or
        case when p_key in ('bank_accounts','cheque_register','declaration_letters','delivery_challans','packaging_lists','letters') then
          m.modules is null or (case p_key when 'bank_accounts' then 'bank-accounts'
            when 'cheque_register' then 'cheques' when 'declaration_letters' then 'declaration'
            when 'delivery_challans' then 'delivery-challans' when 'packaging_lists' then 'packaging-list'
            when 'letters' then 'letters' end)=any(m.modules)
        when p_key in ('packaging_list_number_format','letter_number_format') then not p_write and
          (m.modules is null or (case p_key when 'packaging_list_number_format' then 'packaging-list' else 'letters' end)=any(m.modules))
        else not p_write and (m.modules is null or p_key in
          ('modules.disabled','company_letterhead','company_stamp','company_signature','company_bank','doc_presets','custom_templates')
          or p_key like 'custom_fields_%' or p_key like 'number_format_%' or p_key like 'notify.%') end))
$$;
revoke all on function public.filey_setting_access(text,boolean) from public,anon;
grant execute on function public.filey_setting_access(text,boolean) to authenticated;

-- Formatting is structured data, not arbitrary CSS. This guard also covers
-- direct cloud writes and offline sync, including the issued snapshot.
create or replace function public.filey_letter_text_style_valid(p_style jsonb) returns boolean
language plpgsql immutable set search_path=public,pg_temp as $$
declare v_key text; v_value jsonb;
begin
  if p_style is null then return true; end if;
  if jsonb_typeof(p_style) <> 'object' then return false; end if;
  for v_key,v_value in select key,value from jsonb_each(p_style) loop
    if v_key='font' then
      if jsonb_typeof(v_value)<>'string' or (v_value#>>'{}') not in ('modern','classic','mono') then return false; end if;
    elsif v_key='align' then
      if jsonb_typeof(v_value)<>'string' or (v_value#>>'{}') not in ('left','center','right') then return false; end if;
    elsif v_key='color' then
      if jsonb_typeof(v_value)<>'string' or (v_value#>>'{}') !~* '^#[0-9a-f]{6}$' then return false; end if;
    elsif v_key in ('bold','italic','underline') then
      if jsonb_typeof(v_value)<>'boolean' then return false; end if;
    elsif v_key in ('fontSize','lineSpacing','paragraphSpacing') then
      if jsonb_typeof(v_value)<>'number' then return false; end if;
      if v_key='fontSize' and ((v_value#>>'{}')::numeric<8 or (v_value#>>'{}')::numeric>36) then return false; end if;
      if v_key='lineSpacing' and ((v_value#>>'{}')::numeric<1 or (v_value#>>'{}')::numeric>2.5) then return false; end if;
      if v_key='paragraphSpacing' and ((v_value#>>'{}')::numeric<0 or (v_value#>>'{}')::numeric>32) then return false; end if;
    else return false;
    end if;
  end loop;
  return true;
end $$;

create or replace function public.filey_letter_form_format_valid(p_form jsonb) returns boolean
language plpgsql immutable set search_path=public,pg_temp as $$
declare v_key text; v_block jsonb;
begin
  if jsonb_typeof(p_form) is distinct from 'object' then return false; end if;
  foreach v_key in array array['show_reference','show_company_header'] loop
    if p_form?v_key and jsonb_typeof(p_form->v_key)<>'boolean' then return false; end if;
  end loop;
  foreach v_key in array array['text_style','title_style'] loop
    if p_form?v_key and not public.filey_letter_text_style_valid(p_form->v_key) then return false; end if;
  end loop;
  if jsonb_typeof(p_form->'blocks') is distinct from 'array' then return false; end if;
  for v_block in select value from jsonb_array_elements(p_form->'blocks') loop
    if jsonb_typeof(v_block)<>'object' then return false; end if;
    if v_block?'style' and not public.filey_letter_text_style_valid(v_block->'style') then return false; end if;
  end loop;
  return true;
end $$;

create or replace function public.filey_validate_letter_setting() returns trigger
language plpgsql set search_path=public,pg_temp as $$
declare v_records jsonb; v_record jsonb;
begin
  if new.key<>'letters' then return new; end if;
  begin v_records:=new.value::jsonb;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'Letter content or formatting could not be read' using errcode='23514';
  end;
  if jsonb_typeof(v_records) is distinct from 'array' then
    raise exception 'Letter content must be a collection' using errcode='23514'; end if;
  for v_record in select value from jsonb_array_elements(v_records) loop
    if jsonb_typeof(v_record)<>'object' or not public.filey_letter_form_format_valid(v_record->'form') then
      raise exception 'Letter formatting is invalid' using errcode='23514'; end if;
    if v_record?'issued_snapshot' and v_record->'issued_snapshot'<>'null'::jsonb
      and not public.filey_letter_form_format_valid(v_record->'issued_snapshot') then
      raise exception 'Issued Letter formatting is invalid' using errcode='23514'; end if;
  end loop;
  return new;
end $$;
drop trigger if exists filey_letter_format on public.app_settings;
create trigger filey_letter_format before insert or update of key,value on public.app_settings
  for each row when (new.key='letters') execute function public.filey_validate_letter_setting();

notify pgrst,'reload schema';

-- One physical count = one atomic, repeatable operation. A lost response must
-- never replay a delta, and another stock change must not be overwritten.

create table if not exists public.stocktake_requests (
  request_id uuid not null,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  org_id text not null default public.current_org(),
  product_id bigint not null references public.products(id) on delete cascade,
  expected_quantity numeric(14,3) not null,
  counted_quantity numeric(14,3) not null check (counted_quantity >= 0),
  created_at timestamptz not null default now(),
  primary key (org_id, user_id, request_id)
);
alter table public.stocktake_requests enable row level security;
revoke all on public.stocktake_requests from public, anon, authenticated;
grant select, insert on public.stocktake_requests to authenticated;
drop policy if exists stocktake_requests_read on public.stocktake_requests;
create policy stocktake_requests_read on public.stocktake_requests for select to authenticated
  using (user_id = (select auth.uid()) and org_id = (select public.current_org())
    and (select public.filey_can_use('inventory')));
drop policy if exists stocktake_requests_insert on public.stocktake_requests;
create policy stocktake_requests_insert on public.stocktake_requests for insert to authenticated
  with check (user_id = (select auth.uid()) and org_id = (select public.current_org())
    and (select public.filey_can_use('inventory')));

create or replace function public.filey_record_stocktake(
  p_id bigint, p_counted numeric, p_expected numeric, p_request uuid
) returns numeric language plpgsql security invoker set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid(); v_org text := public.current_org();
  v_quantity numeric; v_delta numeric; v_inserted uuid;
  v_receipt public.stocktake_requests%rowtype;
begin
  if v_uid is null then raise exception 'Sign in to post a stocktake'; end if;
  if v_org is null or not public.filey_can_use('inventory') then
    raise exception 'Your account cannot post stocktakes in this workspace' using errcode='42501';
  end if;
  if p_id is null or p_id <= 0 or p_request is null
    or p_counted is null or p_expected is null
    or p_counted::text in ('NaN','Infinity','-Infinity') or p_expected::text in ('NaN','Infinity','-Infinity')
    or p_counted < 0 or abs(p_counted) >= 100000000000 or abs(p_expected) >= 100000000000
    or abs(p_counted-p_expected) >= 100000000000
    or p_counted <> round(p_counted,3) or p_expected <> round(p_expected,3) then
    raise exception 'Enter a valid physical quantity with at most 3 decimal places' using errcode='22023';
  end if;

  -- RLS controls both visibility and update rights. Every request locks just
  -- its product, then reserves its scoped receipt before changing anything.
  select quantity into v_quantity from public.products where id=p_id for update;
  if not found then raise exception 'Product not found or stock access denied' using errcode='42501'; end if;
  insert into public.stocktake_requests(request_id,user_id,org_id,product_id,expected_quantity,counted_quantity)
    values(p_request,v_uid,v_org,p_id,p_expected,p_counted)
    on conflict (org_id,user_id,request_id) do nothing returning request_id into v_inserted;
  if v_inserted is null then
    select * into v_receipt from public.stocktake_requests
      where org_id=v_org and user_id=v_uid and request_id=p_request;
    if not found or v_receipt.product_id<>p_id or v_receipt.expected_quantity<>p_expected or v_receipt.counted_quantity<>p_counted then
      raise exception 'This stocktake request was already used for a different count' using errcode='22023';
    end if;
    return v_receipt.counted_quantity;
  end if;

  if v_quantity is distinct from p_expected then
    raise exception 'Stock changed after this count was opened. Reload stock and review the physical count before posting again.' using errcode='40001';
  end if;
  v_delta := p_counted - v_quantity;
  update public.products set quantity=p_counted where id=p_id returning quantity into v_quantity;
  if not found then raise exception 'Your account cannot update this product stock' using errcode='42501'; end if;
  if v_delta <> 0 then
    insert into public.stock_movements(product_id,qty,type,ref,note,moved_at)
      values(p_id,v_delta,'adjust','Stocktake','Counted '||p_counted||', book '||p_expected,now());
  end if;
  return v_quantity;
end $$;
revoke all on function public.filey_record_stocktake(bigint,numeric,numeric,uuid) from public, anon;
grant execute on function public.filey_record_stocktake(bigint,numeric,numeric,uuid) to authenticated;
notify pgrst,'reload schema';

-- Apply after Packaging and Letters. Old bootstrap databases generated the
-- name app_settings_user_id_key_key for UNIQUE(user_id,key). Name-only drops
-- missed that constraint and blocked one user's documents in a second org.
-- Replace only that unconditional pair, regardless of its legacy name.
-- No setting values, ownership, module gates or RLS policies are changed.

set local lock_timeout='5s';
set local statement_timeout='60s';
lock table public.app_settings in access exclusive mode;

drop index if exists public.app_settings_user_setting_key;
create unique index app_settings_user_setting_key
  on public.app_settings(user_id,key) where key not in ('packaging_lists','letters');
create unique index if not exists app_settings_packaging_org_key
  on public.app_settings(org_id,key) where key='packaging_lists';
create unique index if not exists app_settings_letters_org_key
  on public.app_settings(org_id,key) where key='letters';

do $$ declare v_name text; begin
  -- Drop a constraint through ALTER TABLE so its backing index is removed too.
  -- No CASCADE: an unexpected dependent object must abort this transaction.
  for v_name in
    select c.conname from pg_constraint c
    where c.conrelid='public.app_settings'::regclass and c.contype='u'
      and (select array_agg(a.attname::text order by a.attname::text)
        from unnest(c.conkey) col(attnum)
        join pg_attribute a on a.attrelid=c.conrelid and a.attnum=col.attnum)
        =array['key','user_id']::text[]
  loop
    execute format('alter table public.app_settings drop constraint %I',v_name);
  end loop;

  -- Some installations kept the same pair as a standalone unique index.
  for v_name in
    select idx.relname from pg_index i join pg_class idx on idx.oid=i.indexrelid
    where i.indrelid='public.app_settings'::regclass and i.indisunique
      and i.indpred is null and i.indnkeyatts=2
      and not exists(select 1 from pg_constraint c where c.conindid=i.indexrelid)
      and (select array_agg(a.attname::text order by a.attname::text)
        from unnest(i.indkey) with ordinality col(attnum,ordinality)
        join pg_attribute a on a.attrelid=i.indrelid and a.attnum=col.attnum
        where col.ordinality<=i.indnkeyatts)=array['key','user_id']::text[]
  loop
    execute format('drop index public.%I',v_name);
  end loop;
end $$;

notify pgrst,'reload schema';

-- A profile's active org can outlive its membership after removal or leaving.
-- Require current membership on shared identity reads, not just current_org().
-- Apply after the team and Basic-web migrations. No records are rewritten.

-- Definer avoids recursion when used by the org_members SELECT policy.
create or replace function public.filey_is_workspace_member(p_org text)
returns boolean language sql stable security definer set search_path=public,pg_temp as $$
  select exists(select 1 from public.org_members m
    where m.org_id=p_org and m.user_id=auth.uid())
$$;
revoke all on function public.filey_is_workspace_member(text) from public,anon;
grant execute on function public.filey_is_workspace_member(text) to authenticated;

drop policy if exists organizations_read on public.organizations;
create policy organizations_read on public.organizations for select to authenticated
  using (owner_id=auth.uid() or (id::text=public.current_org()
    and public.filey_is_workspace_member(id::text)));

drop policy if exists org_members_select on public.org_members;
create policy org_members_select on public.org_members for select to authenticated
  using (user_id=auth.uid() or (org_id=public.current_org()
    and public.filey_is_workspace_member(org_id)));

drop policy if exists profiles_org_read on public.profiles;
create policy profiles_org_read on public.profiles for select to authenticated
  using (org_id=public.current_org() and public.filey_is_workspace_member(org_id));

drop policy if exists company_profile_read on public.company_profile;
create policy company_profile_read on public.company_profile for select to authenticated
  using (org_id=public.current_org() and public.filey_is_workspace_member(org_id));

-- Audit diffs include complete private invoice/payroll records. A module gate
-- on the original row cannot protect that copied data; reserve reads to admins.
drop policy if exists audit_log_org on public.audit_log;
drop policy if exists audit_log_select on public.audit_log;
drop policy if exists audit_log_insert on public.audit_log;
create policy audit_log_select on public.audit_log for select to authenticated
  using (org_id=public.current_org() and public.is_org_admin());
create policy audit_log_insert on public.audit_log for insert to authenticated
  with check (org_id=public.current_org() and user_id=auth.uid()
    and public.filey_is_workspace_member(org_id));

-- Legacy local-user entries are still exposed by the cloud API. A stale active
-- workspace must not permit reading, creating or editing these rows either.
drop policy if exists filey_member_required on public.app_users;
create policy filey_member_required on public.app_users as restrictive for all to authenticated
  using (public.filey_is_workspace_member(org_id))
  with check (public.filey_is_workspace_member(org_id));

create or replace function public.filey_cloud_access() returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
  select public.filey_is_workspace_member(public.current_org())
    and exists(select 1 from public.organizations o where o.id::text=public.current_org())
$$;
revoke all on function public.filey_cloud_access() from public,anon;
grant execute on function public.filey_cloud_access() to authenticated;

-- This definer RPC must not reveal a former company's activity counter, or
-- bypass a restricted member's missing Invoicing permission.
create or replace function public.filey_invoice_usage() returns integer
language sql stable security definer set search_path=public,pg_temp as $$
  select coalesce((select used from public.invoice_monthly_usage
    where org_id::text=public.current_org() and public.filey_can_use('invoicing')
      and month=date_trunc('month',now() at time zone 'UTC')::date),0)
$$;
revoke all on function public.filey_invoice_usage() from public,anon;
grant execute on function public.filey_invoice_usage() to authenticated;

notify pgrst,'reload schema';

-- Child lines/payments are part of their parent document. A caller must not
-- inject their own row into another author's private/shared document, or use
-- an independently shared line to expose a private parent. Additive and safe
-- to repeat; no existing business rows or foreign keys are rewritten.

do $$
declare item record; visible_parent text; writable_parent text;
begin
  for item in select * from (values
    ('order_items','orders','order_id'),
    ('quotation_items','quotations','quotation_id'),
    ('purchase_order_items','purchase_orders','po_id'),
    ('po_payments','purchase_orders','po_id')
  ) as children(child_table,parent_table,parent_key) loop
    if to_regclass('public.'||item.child_table) is null
      or to_regclass('public.'||item.parent_table) is null then continue; end if;
    -- Parent SELECT runs as the caller, so parent module/sharing/MFA gates
    -- still apply. Nullable legacy child rows remain private owner data.
    visible_parent := format('org_id=(select public.current_org()) and '
      ||'((%I is null and user_id=(select auth.uid())) or exists '
      ||'(select 1 from public.%I d where d.id=%I.%I and d.org_id=%I.org_id))',
      item.parent_key,item.parent_table,item.child_table,item.parent_key,item.child_table);
    writable_parent := format('org_id=(select public.current_org()) and '
      ||'((%I is null and user_id=(select auth.uid())) or exists '
      ||'(select 1 from public.%I d where d.id=%I.%I and d.org_id=%I.org_id '
      ||'and (d.user_id=(select auth.uid()) or (select public.is_org_admin()))))',
      item.parent_key,item.parent_table,item.child_table,item.parent_key,item.child_table);
    execute format('drop policy if exists %I on public.%I',item.child_table||'_read',item.child_table);
    execute format('create policy %I on public.%I for select to authenticated using (%s)',
      item.child_table||'_read',item.child_table,visible_parent);
    -- Restrictive gates also constrain legacy permissive ALL/owner policies.
    execute format('drop policy if exists filey_parent_read on public.%I',item.child_table);
    execute format('create policy filey_parent_read on public.%I as restrictive for select to authenticated using (%s)',item.child_table,visible_parent);
    execute format('drop policy if exists filey_parent_insert on public.%I',item.child_table);
    execute format('create policy filey_parent_insert on public.%I as restrictive for insert to authenticated with check (%s)',item.child_table,writable_parent);
    execute format('drop policy if exists filey_parent_update on public.%I',item.child_table);
    execute format('create policy filey_parent_update on public.%I as restrictive for update to authenticated using (%s) with check (%s)',item.child_table,writable_parent,writable_parent);
    execute format('drop policy if exists filey_parent_delete on public.%I',item.child_table);
    execute format('create policy filey_parent_delete on public.%I as restrictive for delete to authenticated using (%s)',item.child_table,writable_parent);
  end loop;
end $$;
notify pgrst,'reload schema';

-- Queued tool specifications/results must not be editable while a trusted
-- worker runs them. Preserve owner reads/pending cancellation and current
-- engines; successful output/status writes belong to service role only.

create or replace function public.filey_admit_tool_job()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
  if auth.uid() is null or coalesce(auth.role(),'')='service_role' then return new; end if;
  if new.user_id is distinct from auth.uid() or new.status is distinct from 'pending'
    or new.error is not null or cardinality(new.output_paths) is distinct from 0 then
    raise exception 'New tool jobs must be pending without results' using errcode='42501';
  end if;
  if not ((new.engine='edge' and new.tool='rotate') or (new.engine='worker'
    and new.tool in ('office2pdf','pdf2docx','ocr','pdfa','compress')))
    or jsonb_typeof(new.params) is distinct from 'object' or octet_length(new.params::text)>65536
    or length(new.file_name)>240 or new.file_name ~ '[[:cntrl:]]'
    or new.size_bytes not between 0 and 52428800 then
    raise exception 'Invalid tool job specification' using errcode='22023';
  end if;
  if not public.filey_take_rate_limit(auth.uid()::text,'tool_job_create',15,3600) then
    raise exception 'Tool job limit reached. Try again later.' using errcode='42501';
  end if;
  return new;
end $$;
revoke all on function public.filey_admit_tool_job() from public,anon,authenticated;
do $$ declare column_name text; begin
  if to_regclass('public.tool_jobs') is null then return; end if;
  drop trigger if exists filey_admit_tool_job on public.tool_jobs;
  create trigger filey_admit_tool_job before insert on public.tool_jobs for each row execute function public.filey_admit_tool_job();
  revoke update on public.tool_jobs from public,anon,authenticated;
  -- A table-level revoke does not revoke any old column-level grant.
  for column_name in select attname from pg_attribute where attrelid='public.tool_jobs'::regclass
    and attnum>0 and not attisdropped loop
    execute format('revoke update (%I) on public.tool_jobs from public,anon,authenticated',column_name);
  end loop;
  drop policy if exists filey_cancel_pending on public.tool_jobs;
  create policy filey_cancel_pending on public.tool_jobs as restrictive for delete to authenticated using(status='pending');
end $$;
notify pgrst,'reload schema';

-- Atomic invoice/quote/purchase-order header and replacement lines. Caller RLS
-- remains authoritative; shared recipients cannot replace another author's lines.
-- Boolean-only authority check sees legacy lines hidden by ordinary RLS. A
-- non-admin cannot replace another creator's children; an admin may reconcile
-- same-org creators, but no caller can replace foreign/null-org footprints.
create or replace function public.filey_document_lines_replaceable(p_table text,p_id bigint)
returns boolean language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v_child text; v_key text; v_owner uuid; v_org text; v_module text; v_ok boolean;
begin
  if auth.uid() is null or not public.filey_is_workspace_member(public.current_org()) then return false; end if;
  case p_table
    when 'invoice_docs' then v_child:='invoice_doc_items'; v_key:='invoice_id';
      select user_id,org_id,case when doc_type='purchase' then 'purchase-invoices' else 'invoicing' end into v_owner,v_org,v_module from public.invoice_docs where id=p_id;
    when 'quotations' then v_child:='quotation_items'; v_key:='quotation_id'; v_module:='quoting';
      select user_id,org_id into v_owner,v_org from public.quotations where id=p_id;
    when 'purchase_orders' then v_child:='purchase_order_items'; v_key:='po_id'; v_module:='purchase-orders';
      select user_id,org_id into v_owner,v_org from public.purchase_orders where id=p_id;
    else return false;
  end case;
  if v_owner is null or v_org is distinct from public.current_org() or not public.filey_can_use(v_module)
    or (v_owner is distinct from auth.uid() and not public.is_org_admin()) then return false; end if;
  execute format('select not exists(select 1 from public.%I where %I=$1 and (org_id is distinct from $2 or (not public.is_org_admin() and user_id is distinct from $3)))',v_child,v_key)
    into v_ok using p_id,v_org,auth.uid();
  return v_ok;
end $$;
revoke all on function public.filey_document_lines_replaceable(text,bigint) from public,anon;
grant execute on function public.filey_document_lines_replaceable(text,bigint) to authenticated;
-- Header and replacement lines commit together; a rejected line preserves the original.
create or replace function public.filey_save_document(p_table text, p_header jsonb, p_items jsonb, p_id bigint default null)
returns bigint language plpgsql security invoker set search_path = public, pg_temp as $$
declare
  item_table text; fk text; header jsonb; item jsonb; cols text; vals text;
  result_id bigint; ordinal integer := 0; allowed text[]; original_status text; original_author uuid; original_org text;
begin
  if auth.uid() is null then raise exception 'Sign in to save documents'; end if;
  case p_table
    when 'invoice_docs' then item_table := 'invoice_doc_items'; fk := 'invoice_id';
    when 'quotations' then item_table := 'quotation_items'; fk := 'quotation_id';
    when 'purchase_orders' then item_table := 'purchase_order_items'; fk := 'po_id';
    else raise exception 'Unsupported document type';
  end case;
  if p_header is null or p_items is null or jsonb_typeof(p_header) <> 'object' or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 500 or octet_length(p_header::text)+octet_length(p_items::text)>8388608 then
    raise exception 'Invalid document payload';
  end if;
  header := p_header - array['id','user_id','org_id','created_at','updated_at','shared','shared_with','share_token','stock_received'];
  select array_agg(column_name::text) into allowed from information_schema.columns where table_schema='public' and table_name=p_table;
  if exists(select 1 from jsonb_object_keys(header) k where not (k = any(allowed))) then raise exception 'Unknown document field'; end if;
  if p_id is not null then
    execute format('select id, status, user_id, org_id from public.%I where id=$1 for update', p_table) into result_id, original_status, original_author, original_org using p_id;
    if result_id is null or original_org is distinct from public.current_org() or (original_author is distinct from auth.uid() and not public.is_org_admin()) then raise exception 'Document not found or edit access denied' using errcode='42501'; end if;
    if not public.filey_document_lines_replaceable(p_table,p_id) then raise exception 'Historic document lines require ownership reconciliation before replacement' using errcode='42501'; end if;
    if p_table in ('invoice_docs','purchase_orders') and current_user<>'filey_workflow_executor'
      and (original_status is distinct from 'draft' or coalesce(header->>'status',original_status) is distinct from 'draft') then
      raise exception 'Use the document workflow to change a finalized invoice or purchase order' using errcode='42501'; end if;
    select string_agg(format('%I = (jsonb_populate_record(null::public.%I, $1)).%I', k, p_table, k), ',') into vals from jsonb_object_keys(header) k;
    if vals is not null then execute format('update public.%I set %s where id=$2 returning id',p_table,vals) into result_id using header,p_id; end if;
    if result_id is null then raise exception 'Document update denied'; end if;
    execute format('delete from public.%I where %I=$1',item_table,fk) using p_id;
  else
    if p_table in ('invoice_docs','purchase_orders') and current_user<>'filey_workflow_executor'
      and coalesce(header->>'status','draft') is distinct from 'draft' then
      raise exception 'Use the document workflow to finalize an invoice or purchase order' using errcode='42501'; end if;
    original_author:=auth.uid(); original_org:=public.current_org();
    select string_agg(format('%I', k), ','), string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',p_table,k), ',') into cols,vals from jsonb_object_keys(header) k;
    if cols is null then raise exception 'Document header is required'; end if;
    execute format('insert into public.%I (%s) select %s returning id',p_table,cols,vals) into result_id using header;
  end if;
  select array_agg(column_name::text) into allowed from information_schema.columns where table_schema='public' and table_name=item_table;
  for item in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(item)<>'object' then raise exception 'Invalid document line'; end if;
    item := (item - array['id','user_id','org_id','created_at','updated_at','shared']) || jsonb_build_object(fk,result_id,'position',ordinal,'user_id',original_author,'org_id',original_org);
    if exists(select 1 from jsonb_object_keys(item) k where not (k = any(allowed))) then raise exception 'Unknown line field'; end if;
    select string_agg(format('%I',k),','), string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',item_table,k),',') into cols,vals from jsonb_object_keys(item) k;
    execute format('insert into public.%I (%s) select %s',item_table,cols,vals) using item;
    ordinal := ordinal + 1;
  end loop;
  return result_id;
end;
$$;
revoke all on function public.filey_save_document(text,jsonb,jsonb,bigint) from public, anon;
grant execute on function public.filey_save_document(text,jsonb,jsonb,bigint) to authenticated;

notify pgrst,'reload schema';

-- Registry fingerprints/session IDs are device credentials, not public team
-- identity. Removed members cannot inspect, occupy or release workspace slots.
-- Requires 2026-10-03-workspace-membership-read-integrity.sql.

drop policy if exists org_devices_select on public.org_devices;
create policy org_devices_select on public.org_devices for select to authenticated
  using(org_id=public.current_org() and public.filey_is_workspace_member(org_id)
    and (user_id=auth.uid() or public.is_org_admin()));
drop policy if exists filey_device_member on public.org_devices;
create policy filey_device_member on public.org_devices as restrictive for all to authenticated
  using(public.filey_is_workspace_member(org_id)) with check(public.filey_is_workspace_member(org_id));
create or replace function public.register_device(p_fingerprint text, p_name text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_org text := public.current_org();
  v_id uuid;
  v_active int;
  v_device public.org_devices;
  v_session text:=auth.jwt()->>'session_id';
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  end if;
  if not public.filey_is_workspace_member(v_org) then
    return jsonb_build_object('ok',false,'reason','workspace_access');
  end if;
  if p_fingerprint is null or length(trim(p_fingerprint)) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'missing_fingerprint');
  end if;

  if length(p_fingerprint)>256 or length(coalesce(p_name,''))>200 then
    return jsonb_build_object('ok',false,'reason','invalid_device');
  end if;

  -- SECURITY: serialize per-org registrations — two devices racing the
  -- count check below could both pass and exceed the slot limit (TOCTOU).
  perform pg_advisory_xact_lock(hashtext('org_devices:' || v_org));

  select * into v_device
    from org_devices
   where org_id = v_org and fingerprint = p_fingerprint;

  v_id:=v_device.id;
  if v_id is not null and v_device.user_id is distinct from auth.uid() then
    return jsonb_build_object('ok',false,'reason','device_in_use');
  end if;
  if v_id is not null and v_device.revoked_at is not null
     and (v_session is null or v_device.session_id is not distinct from v_session
       or (v_device.session_id is null and coalesce((select created_at<=v_device.revoked_at
         from auth.sessions where id::text=v_session and user_id=auth.uid()),true))) then
    return jsonb_build_object('ok',false,'reason','logged_out');
  end if;
  if v_id is not null and v_device.revoked_at is null then
    update org_devices
       set last_seen = now(),
           user_id = auth.uid(),
           session_id = v_session,
           device_name = coalesce(nullif(p_name, ''), device_name)
     where id = v_id;
    return jsonb_build_object('ok', true, 'existing', true);
  end if;

  select count(*) into v_active from org_devices where org_id = v_org and revoked_at is null;
  if v_active >= 20 then
    return jsonb_build_object('ok', false, 'reason', 'limit', 'limit', 20);
  end if;

  insert into org_devices (org_id, user_id, fingerprint, device_name,session_id)
  values (v_org, auth.uid(), p_fingerprint, nullif(p_name, ''),v_session)
  on conflict(org_id,fingerprint) do update set user_id=excluded.user_id,device_name=excluded.device_name,
    session_id=excluded.session_id,revoked_at=null,last_seen=now();
  return jsonb_build_object('ok', true);
end $fn$;

revoke all on function public.register_device(text, text) from public, anon;
grant execute on function public.register_device(text, text) to authenticated;

create or replace function public.filey_logout_device(p_id uuid) returns void
language plpgsql security definer set search_path=public,pg_temp as $$
begin
  if not public.filey_is_workspace_member(public.current_org()) then raise exception 'Workspace access denied' using errcode='42501'; end if;
  update public.org_devices set revoked_at=now() where id=p_id and org_id=public.current_org()
    and (user_id=auth.uid() or public.is_org_admin());
  if not found then raise exception 'This device could not be logged out. Refresh and try again'; end if;
end $$;
create or replace function public.filey_device_logged_out(p_fingerprint text) returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
  select public.filey_is_workspace_member(public.current_org()) and exists(select 1 from public.org_devices where org_id=public.current_org() and fingerprint=p_fingerprint
    and user_id=auth.uid() and revoked_at is not null
    and (session_id is not distinct from (auth.jwt()->>'session_id') or (auth.jwt()->>'session_id') is null
      or (session_id is null and coalesce((select created_at<=org_devices.revoked_at
        from auth.sessions where id::text=(auth.jwt()->>'session_id') and user_id=auth.uid()),true))))
$$;
revoke all on function public.filey_logout_device(uuid),public.filey_device_logged_out(text) from public,anon;
grant execute on function public.filey_logout_device(uuid),public.filey_device_logged_out(text) to authenticated;
notify pgrst,'reload schema';

-- One payroll run and its balanced postings commit together. Preserve historic
-- duplicate rows while reserving their periods against any further duplicates.

create table if not exists public.payroll_period_claims (
  org_id text not null,
  -- Keep the claim if a employee/payroll is deleted: recreating its old ID
  -- must not make a previously posted salary payable again.
  employee_id bigint not null,
  period text not null,
  payroll_id bigint references public.payroll(id) on delete set null,
  primary key (org_id,employee_id,period)
);
alter table public.payroll_period_claims enable row level security;
revoke all on public.payroll_period_claims from public,anon,authenticated;
grant all on public.payroll_period_claims to service_role;
insert into public.payroll_period_claims(org_id,employee_id,period,payroll_id)
  select distinct on (org_id,employee_id,btrim(period)) org_id,employee_id,btrim(period),id
  from public.payroll where employee_id is not null and org_id is not null
  order by org_id,employee_id,btrim(period),id
  on conflict do nothing;

-- This narrow trigger owns only the private period claim. The caller's normal
-- payroll RLS still controls the row; users cannot forge or clear a claim.
create or replace function public.filey_claim_payroll_period() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
begin
  if tg_op='UPDATE' then
    if new.org_id is distinct from old.org_id or new.employee_id is distinct from old.employee_id
      or btrim(new.period) is distinct from btrim(old.period)
      or new.basic is distinct from old.basic or new.allowances is distinct from old.allowances
      or new.deductions is distinct from old.deductions or new.net_pay is distinct from old.net_pay then
      raise exception 'Posted payroll identity and amounts cannot be changed. Open the original payslip.' using errcode='22023';
    end if;
    return new;
  end if;
  new.period:=btrim(new.period);
  if new.employee_id is null or new.org_id is null or new.period is null
    or new.period !~ '^[1-9][0-9]{3}-(0[1-9]|1[0-2])$' then
    raise exception 'Choose an employee and a YYYY-MM payroll period.' using errcode='22023';
  end if;
  if not exists(select 1 from public.employees e where e.id=new.employee_id and e.org_id=new.org_id
    and (auth.uid() is null or e.user_id=auth.uid() or e.shared or public.is_org_admin()))
    or (auth.uid() is not null and (new.org_id is distinct from public.current_org()
      or not public.filey_can_use('people') or not public.filey_can_use('accounting'))) then
    raise exception 'Employee not found or payroll access denied.' using errcode='42501';
  end if;
  begin
    insert into public.payroll_period_claims(org_id,employee_id,period,payroll_id)
      values(new.org_id,new.employee_id,new.period,new.id);
  exception when unique_violation then
    raise exception 'Payroll is already recorded for this employee and period. Open the existing payslip instead.' using errcode='23505';
  end;
  return new;
end $$;
revoke all on function public.filey_claim_payroll_period() from public,anon,authenticated;
drop trigger if exists filey_claim_payroll_period on public.payroll;
create trigger filey_claim_payroll_period after insert or update of org_id,employee_id,period,basic,allowances,deductions,net_pay
  on public.payroll for each row execute function public.filey_claim_payroll_period();

create or replace function public.filey_run_payroll(
  p_employee bigint,p_period text,p_basic numeric,p_allowances numeric,p_deductions numeric,
  p_account bigint,p_date date,p_org text,p_actor uuid
) returns bigint language plpgsql security invoker set search_path=public,pg_temp as $$
declare
  v_uid uuid:=auth.uid(); v_org text:=public.current_org(); v_id bigint;
  v_target bigint; v_cash bigint; v_net numeric; v_changed bigint;
begin
  if v_uid is null or p_actor is distinct from v_uid or p_org is distinct from v_org
    or v_org is null or not public.filey_can_use('people') or not public.filey_can_use('accounting') then
    raise exception 'Your account cannot post payroll in this workspace. Reopen People.' using errcode='42501';
  end if;
  p_period:=btrim(p_period);
  if p_employee is null or p_employee<=0 or p_period is null
    or p_period !~ '^[1-9][0-9]{3}-(0[1-9]|1[0-2])$' or p_date is null
    or p_basic is null or p_allowances is null or p_deductions is null
    or p_basic::text in ('NaN','Infinity','-Infinity') or p_allowances::text in ('NaN','Infinity','-Infinity')
    or p_deductions::text in ('NaN','Infinity','-Infinity') or least(p_basic,p_allowances,p_deductions)<0
    or greatest(p_basic,p_allowances,p_deductions)>=1000000000000
    or p_basic<>round(p_basic,2) or p_allowances<>round(p_allowances,2) or p_deductions<>round(p_deductions,2)
    or (p_account is not null and p_account<=0) then
    raise exception 'Choose an employee, a YYYY-MM period, and non-negative pay amounts with at most 2 decimal places.' using errcode='22023';
  end if;
  v_net:=p_basic+p_allowances-p_deductions;
  if v_net<0 or v_net>=1000000000000 then raise exception 'Net pay is outside the valid range.' using errcode='22023'; end if;

  -- Serialize the workspace's automatic account selection, then use ordinary
  -- row locks and RLS. No read-modify-write balance is performed in a browser.
  perform pg_advisory_xact_lock(hashtextextended(v_org||':payroll',0));
  perform 1 from public.employees where id=p_employee and org_id=v_org for update;
  if not found then raise exception 'Employee not found or payroll access denied.' using errcode='42501'; end if;
  if p_account is not null then v_target:=p_account;
  else
    select id into v_target from public.accounts where org_id=v_org and account_type='expense'
      and (user_id=v_uid or public.is_org_admin()) and name ~* '\m(salary|salaries|payroll|wages?)\M' order by id limit 1;
    if v_target is null then
      insert into public.accounts(code,name,account_type,balance) values('5200','Salaries & Wages','expense',0) returning id into v_target;
    end if;
  end if;
  perform 1 from public.accounts where id=v_target and org_id=v_org and account_type='expense' for update;
  if not found then raise exception 'Choose an accessible expense account for payroll.' using errcode='42501'; end if;
  insert into public.payroll(employee_id,period,basic,allowances,deductions,net_pay,status)
    values(p_employee,p_period,p_basic,p_allowances,p_deductions,v_net,'pending') returning id into v_id;
  if v_net>0 then
    select id into v_cash from public.accounts where org_id=v_org and account_type='asset'
      and (user_id=v_uid or public.is_org_admin()) and name ~* '(cash|bank)' order by id limit 1;
    if v_cash is null then
      insert into public.accounts(code,name,account_type,balance) values('1000','Cash & Bank','asset',0) returning id into v_cash;
    end if;
    insert into public.transactions(account_id,txn_type,amount,description,ref,source,txn_date)
      values(v_target,'debit',v_net,'Payroll '||p_period,'Payroll '||v_id,'payroll',p_date),
        (v_cash,'credit',v_net,'Payroll '||p_period||' — paid','Payroll '||v_id,'payroll',p_date);
    update public.accounts set balance=balance+v_net where id=v_target and org_id=v_org returning id into v_changed;
    if v_changed is null then raise exception 'Expense account update denied.' using errcode='42501'; end if;
    v_changed:=null;
    update public.accounts set balance=balance-v_net where id=v_cash and org_id=v_org returning id into v_changed;
    if v_changed is null then raise exception 'Cash account update denied.' using errcode='42501'; end if;
  end if;
  return v_id;
end $$;
revoke all on function public.filey_run_payroll(bigint,text,numeric,numeric,numeric,bigint,date,text,uuid) from public,anon;
grant execute on function public.filey_run_payroll(bigint,text,numeric,numeric,numeric,bigint,date,text,uuid) to authenticated;
notify pgrst,'reload schema';

-- Lock the eligible organization before consuming a parked paid entitlement.
-- Distinct purchasers must not both consume claims for the same workspace.

create or replace function public.filey_claim_entitlements()
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_uid uuid:=auth.uid(); v_email text; v_org text; v_row record;
  v_claimed_cloud int:=0; v_claimed_licence int:=0;
begin
  if v_uid is null then return jsonb_build_object('claimed',false,'reason','not signed in'); end if;
  select lower(email) into v_email from auth.users where id=v_uid and email_confirmed_at is not null;
  if v_email is null or v_email='' then
    return jsonb_build_object('claimed',false,'reason','verify your email first');
  end if;
  for v_row in select * from public.pending_entitlements
    where claimed_at is null and lower(email)=v_email order by created_at,id for update
  loop
    if v_row.kind='freedom' then
      if not exists(select 1 from public.licenses where user_id=v_uid and status='active') then
        insert into public.licenses(user_id,product,status,dodo_payment_id)
          values(v_uid,'filey-desktop','active',v_row.dodo_payment_id) on conflict do nothing;
        if not found then continue; end if;
        v_claimed_licence:=v_claimed_licence+1;
        update public.pending_entitlements set claimed_at=now(),claimed_by=v_uid where id=v_row.id;
      end if;
    elsif v_row.plan_status in ('active','trialing','past_due')
      and (v_row.current_period_end is null or v_row.current_period_end>now()) then
      -- FOR UPDATE rechecks this eligibility after waiting for an earlier
      -- claim's row lock. A different active purchase remains unclaimed.
      select o.id::text into v_org from public.organizations o
        where o.id::text=public.current_org() and (o.owner_id=v_uid or exists(
          select 1 from public.org_members m where m.org_id=o.id::text
            and m.user_id=v_uid and m.role in ('owner','admin')))
          and (o.dodo_subscription_id is null or o.dodo_subscription_id=v_row.dodo_subscription_id or o.plan='free')
        order by (o.id::text=public.current_org()) desc,o.created_at limit 1 for update of o;
      if v_org is not null then
        update public.organizations set plan='cloud',plan_status=v_row.plan_status,
          current_period_end=v_row.current_period_end,
          dodo_subscription_id=coalesce(v_row.dodo_subscription_id,dodo_subscription_id),
          dodo_customer_id=coalesce(v_row.dodo_customer_id,dodo_customer_id) where id::text=v_org;
        v_claimed_cloud:=v_claimed_cloud+1;
        update public.pending_entitlements set claimed_at=now(),claimed_by=v_uid where id=v_row.id;
      end if;
    end if;
  end loop;
  return jsonb_build_object('claimed',(v_claimed_cloud+v_claimed_licence)>0,'cloud',v_claimed_cloud,'licences',v_claimed_licence);
end $$;
revoke all on function public.filey_claim_entitlements() from public,anon;
grant execute on function public.filey_claim_entitlements() to authenticated;
notify pgrst,'reload schema';

-- Public share-token RPCs bypass RLS. Their child joins must therefore enforce
-- organization identity explicitly, even for malformed historical/admin rows.
-- Preserve customer document fields; strip only ownership/share authority.
-- Null organization identity cannot prove the child belongs to this document.

create or replace function public.get_shared_invoice(p_token uuid)
returns jsonb language sql security definer set search_path = public,pg_temp as $$
  select jsonb_build_object(
    'doc', to_jsonb(d) - array['user_id','org_id','share_token','shared_with'],
    'items', coalesce((
      select jsonb_agg(to_jsonb(i) - array['user_id','org_id','share_token','shared_with'] order by i.position)
      from public.invoice_doc_items i
      where i.invoice_id=d.id and i.org_id=d.org_id
    ), '[]'::jsonb)
  )
  from public.invoice_docs d
  where d.share_token=p_token and d.shared=true;
$$;

create or replace function public.get_shared_doc(p_token uuid)
returns jsonb language sql security definer set search_path = public,pg_temp as $$
  select jsonb_build_object(
    'doc_type', 'invoice',
    'doc', to_jsonb(d) - array['user_id','org_id','share_token','shared_with'],
    'items', coalesce((
      select jsonb_agg(to_jsonb(i) - array['user_id','org_id','share_token','shared_with'] order by i.position)
      from public.invoice_doc_items i
      where i.invoice_id=d.id and i.org_id=d.org_id
    ), '[]'::jsonb)
  ) from public.invoice_docs d where d.share_token=p_token and d.shared=true
  union all
  select jsonb_build_object(
    'doc_type', 'quotation',
    'doc', to_jsonb(q) - array['user_id','org_id','share_token','shared_with'],
    'items', coalesce((
      select jsonb_agg(to_jsonb(i) - array['user_id','org_id','share_token','shared_with'] order by i.position)
      from public.quotation_items i
      where i.quotation_id=q.id and i.org_id=q.org_id
    ), '[]'::jsonb)
  ) from public.quotations q where q.share_token=p_token and q.shared=true
  union all
  select jsonb_build_object(
    'doc_type', 'purchase_order',
    'doc', to_jsonb(po) - array['user_id','org_id','share_token','shared_with'],
    'items', coalesce((
      select jsonb_agg(to_jsonb(i) - array['user_id','org_id','share_token','shared_with'] order by i.position)
      from public.purchase_order_items i
      where i.po_id=po.id and i.org_id=po.org_id
    ), '[]'::jsonb)
  ) from public.purchase_orders po where po.share_token=p_token and po.shared=true
  union all
  select jsonb_build_object(
    'doc_type', 'receipt',
    'doc', to_jsonb(r) - array['user_id','org_id','share_token','shared_with'],
    'items', jsonb_build_array(jsonb_build_object(
      'description', coalesce(r.for_description,'Payment'),
      'qty', 1,
      'unit_price', r.amount
    ))
  ) from public.payment_receipts r where r.share_token=p_token and r.shared=true
  limit 1;
$$;

-- These two narrow token gates remain intentionally anonymous-readable.
revoke all on function public.get_shared_invoice(uuid) from public;
revoke all on function public.get_shared_doc(uuid) from public;
grant execute on function public.get_shared_invoice(uuid) to anon,authenticated;
grant execute on function public.get_shared_doc(uuid) to anon,authenticated;
notify pgrst,'reload schema';

-- BEGIN GENERATED FRESH BOOTSTRAP current authority
-- Source: supabase/2026-10-04-document-number-authority.sql
-- Reserve automatic numbers under an organization lock. Historical duplicates
-- remain intact, but every new/renumbered document is checked under that lock.

create table if not exists public.document_number_reservations (
  org_id text not null, namespace text not null, request_id uuid not null,
  user_id uuid not null, pattern text not null, year integer not null,
  number text not null, created_at timestamptz not null default now(),
  primary key(org_id,namespace,request_id), unique(org_id,namespace,number)
);
alter table public.document_number_reservations enable row level security;
revoke all on public.document_number_reservations from public,anon,authenticated;

create or replace function public.filey_document_numbers(p_namespace text,p_org text)
returns table(number text, identity text, setting_id bigint)
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_table text; v_column text; v_key text;
begin
  case p_namespace
    when 'invoice' then v_table:='invoice_docs'; v_column:='number';
    when 'quote' then v_table:='quotations'; v_column:='number';
    when 'purchase_order' then v_table:='purchase_orders'; v_column:='po_number';
    when 'sales_order' then v_table:='orders'; v_column:='order_number';
    when 'payment_receipt' then v_table:='payment_receipts'; v_column:='number';
    when 'letter' then v_key:='letters';
    when 'packaging_list' then v_key:='packaging_lists';
    when 'delivery_challan' then v_key:='delivery_challans';
    when 'declaration_letter' then v_key:='declaration_letters';
    else raise exception 'Unsupported number type';
  end case;
  if v_table is not null then
    return query execute format('select %I::text,id::text,null::bigint from public.%I where org_id=$1',v_column,v_table) using p_org;
  else
    return query select coalesce(r->'form'->>'number',r->>'number',r->>'ref'),r->>'id',s.id
      from public.app_settings s cross join lateral jsonb_array_elements(s.value::jsonb) r
      where s.org_id=p_org and s.key=v_key;
  end if;
end $$;
revoke all on function public.filey_document_numbers(text,text) from public,anon,authenticated;

create or replace function public.filey_reserve_document_number(
  p_kind text,p_pattern text,p_year integer,p_request uuid,p_actor uuid,p_org text
) returns text language plpgsql security definer set search_path=public,pg_temp as $$
declare v_namespace text; v_module text; v_pattern text; v_token text; v_tokens text[];
  v_prefix text; v_suffix text; v_seq numeric; v_max numeric:=0; v_value text; v_digits text;
  v_saved public.document_number_reservations; v_uid uuid:=auth.uid();
begin
  if v_uid is null or v_uid is distinct from p_actor or public.current_org() is distinct from p_org
    or not exists(select 1 from public.org_members m where m.org_id=p_org and m.user_id=v_uid) then
    raise exception 'Document number workspace access denied' using errcode='42501';
  end if;
  case p_kind
    when 'invoice' then v_namespace:='invoice'; v_module:='invoicing';
    when 'purchase_invoice' then v_namespace:='invoice'; v_module:='purchase-invoices';
    when 'quote' then v_namespace:='quote'; v_module:='quoting';
    when 'purchase_order' then v_namespace:='purchase_order'; v_module:='purchase-orders';
    when 'sales_order' then v_namespace:='sales_order'; v_module:='orders';
    when 'payment_receipt' then v_namespace:='payment_receipt'; v_module:='payment-receipts';
    when 'letter' then v_namespace:='letter'; v_module:='letters';
    when 'packaging_list' then v_namespace:='packaging_list'; v_module:='packaging-list';
    when 'delivery_challan' then v_namespace:='delivery_challan'; v_module:='delivery-challans';
    when 'declaration_letter' then v_namespace:='declaration_letter'; v_module:='declaration';
    else raise exception 'Unsupported number type';
  end case;
  if not public.filey_can_use(v_module) then raise exception 'Document module access denied' using errcode='42501'; end if;
  if p_request is null or p_pattern is null or length(p_pattern)>120 or p_pattern~'[[:cntrl:]]'
    or p_year is null or p_year not between 1900 and 9999 then raise exception 'Invalid document number format'; end if;
  select array_agg(x[1]) into v_tokens from regexp_matches(p_pattern,'\{([0-9]+)\}','g') x;
  if coalesce(array_length(v_tokens,1),0)<>1 or length(v_tokens[1])>12 then raise exception 'Number format needs one bounded counter'; end if;
  v_token:='{'||v_tokens[1]||'}';
  v_pattern:=regexp_replace(regexp_replace(p_pattern,'\{YYYY\}',p_year::text,'gi'),'\{YY\}',right(p_year::text,2),'gi');
  v_prefix:=split_part(v_pattern,v_token,1); v_suffix:=substr(v_pattern,length(v_prefix)+length(v_token)+1);
  perform pg_advisory_xact_lock(hashtextextended('filey:number:'||p_org||':'||v_namespace,0));
  select * into v_saved from public.document_number_reservations r
    where r.org_id=p_org and r.namespace=v_namespace and r.request_id=p_request;
  if found then
    if v_saved.user_id<>v_uid or v_saved.pattern<>p_pattern or v_saved.year<>p_year then raise exception 'Number request was already used differently'; end if;
    return v_saved.number;
  end if;
  for v_value in select n.number from public.filey_document_numbers(v_namespace,p_org) n
    union all select r.number from public.document_number_reservations r where r.org_id=p_org and r.namespace=v_namespace loop
    if lower(left(v_value,length(v_prefix)))=lower(v_prefix) and lower(right(v_value,length(v_suffix)))=lower(v_suffix)
      and length(v_value)>=length(v_prefix)+length(v_suffix)+1 then
      v_digits:=substr(v_value,length(v_prefix)+1,length(v_value)-length(v_prefix)-length(v_suffix));
      if v_digits~'^[0-9]{1,160}$' then v_max:=greatest(v_max,v_digits::numeric); end if;
    end if;
  end loop;
  v_seq:=greatest(v_max+1,greatest(v_tokens[1]::numeric,1));
  if v_seq>9007199254740991 then raise exception 'Document number counter exhausted'; end if;
  v_value:=v_prefix||lpad(v_seq::text,greatest(length(v_tokens[1]),length(v_seq::text)),'0')||v_suffix;
  if exists(select 1 from public.filey_document_numbers(v_namespace,p_org) n where lower(btrim(n.number))=lower(btrim(v_value))) then raise exception 'Document number collision'; end if;
  insert into public.document_number_reservations(org_id,namespace,request_id,user_id,pattern,year,number)
    values(p_org,v_namespace,p_request,v_uid,p_pattern,p_year,v_value);
  return v_value;
end $$;
revoke all on function public.filey_reserve_document_number(text,text,integer,uuid,uuid,text) from public,anon;
grant execute on function public.filey_reserve_document_number(text,text,integer,uuid,uuid,text) to authenticated;

create or replace function public.filey_document_number_guard()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_new jsonb:=to_jsonb(new); v_old jsonb; v_namespace text:=tg_argv[0]; v_column text:=tg_argv[1];
  v_number text; v_org text:=v_new->>'org_id'; v_id text:=v_new->>'id';
begin
  if tg_op='UPDATE' then v_old:=to_jsonb(old); end if;
  v_number:=v_new->>v_column;
  if tg_op='UPDATE' and v_number is not distinct from v_old->>v_column and v_org is not distinct from v_old->>'org_id' then return new; end if;
  if v_org is null or v_number is null or btrim(v_number)='' or length(v_number)>160 or v_number~'[[:cntrl:]]' then raise exception 'A valid workspace document number is required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('filey:number:'||v_org||':'||v_namespace,0));
  if exists(select 1 from public.filey_document_numbers(v_namespace,v_org) n where n.identity is distinct from v_id and lower(btrim(n.number))=lower(btrim(v_number))) then
    raise exception 'This document number is already in use. Choose another number.' using errcode='23505';
  end if;
  if auth.uid() is not null and exists(select 1 from public.document_number_reservations r
    where r.org_id=v_org and r.namespace=v_namespace and lower(btrim(r.number))=lower(btrim(v_number)) and r.user_id<>auth.uid()) then
    raise exception 'This document number is reserved by another user' using errcode='23505';
  end if;
  return new;
end $$;
revoke all on function public.filey_document_number_guard() from public,anon,authenticated;
do $$ declare s text[]; begin
  foreach s slice 1 in array array[
    ['invoice_docs','invoice','number'],['quotations','quote','number'],['purchase_orders','purchase_order','po_number'],
    ['orders','sales_order','order_number'],['payment_receipts','payment_receipt','number']
  ] loop
    execute format('drop trigger if exists zz_filey_document_number on public.%I',s[1]);
    execute format('create trigger zz_filey_document_number before insert or update on public.%I for each row execute function public.filey_document_number_guard(%L,%L)',s[1],s[2],s[3]);
  end loop;
end $$;

-- JSON-backed documents retain historical duplicate numbers unchanged. Newly
-- added or renamed record identities cannot introduce another duplicate.
create or replace function public.filey_setting_number_guard()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_namespace text; v_records jsonb; v_old jsonb:='[]'::jsonb; r jsonb; other jsonb; v_number text; v_identity text;
begin
  v_namespace:=case new.key when 'letters' then 'letter' when 'packaging_lists' then 'packaging_list'
    when 'delivery_challans' then 'delivery_challan' when 'declaration_letters' then 'declaration_letter' end;
  if v_namespace is null then return new; end if;
  v_records:=new.value::jsonb;
  if jsonb_typeof(v_records)<>'array' or jsonb_array_length(v_records)>10000 or new.org_id is null then raise exception 'Invalid numbered document collection'; end if;
  if tg_op='UPDATE' and old.key=new.key and old.org_id is not distinct from new.org_id then v_old:=old.value::jsonb; end if;
  perform pg_advisory_xact_lock(hashtextextended('filey:number:'||new.org_id||':'||v_namespace,0));
  for r in select value from jsonb_array_elements(v_records) loop
    v_number:=coalesce(r->'form'->>'number',r->>'number',r->>'ref'); v_identity:=r->>'id';
    if (select count(*) from jsonb_array_elements(v_records) n where n->>'id' is not distinct from v_identity)>
      greatest(1,(select count(*) from jsonb_array_elements(v_old) o where o->>'id' is not distinct from v_identity)) then
      raise exception 'A document identity cannot be duplicated. Create a new document.' using errcode='23505';
    end if;
    if (select count(*) from jsonb_array_elements(v_old) o where o->>'id' is not distinct from v_identity and coalesce(o->'form'->>'number',o->>'number',o->>'ref') is not distinct from v_number)>=
      (select count(*) from jsonb_array_elements(v_records) n where n->>'id' is not distinct from v_identity and coalesce(n->'form'->>'number',n->>'number',n->>'ref') is not distinct from v_number) then continue; end if;
    if v_identity is null or btrim(v_identity)='' then raise exception 'A new document needs a valid identity'; end if;
    if v_number is null or btrim(v_number)='' or length(v_number)>160 or v_number~'[[:cntrl:]]' then raise exception 'A valid document number is required'; end if;
    if auth.uid() is not null and exists(select 1 from public.document_number_reservations n
      where n.org_id=new.org_id and n.namespace=v_namespace and lower(btrim(n.number))=lower(btrim(v_number)) and n.user_id<>auth.uid()) then
      raise exception 'This document number is reserved by another user' using errcode='23505';
    end if;
    if exists(select 1 from public.filey_document_numbers(v_namespace,new.org_id) n where (n.setting_id is distinct from new.id or n.identity is distinct from v_identity) and lower(btrim(n.number))=lower(btrim(v_number)))
      or (select count(*) from jsonb_array_elements(v_records) o where lower(btrim(coalesce(o->'form'->>'number',o->>'number',o->>'ref')))=lower(btrim(v_number)))>1 then
      raise exception 'This document number is already in use. Choose another number.' using errcode='23505';
    end if;
  end loop;
  return new;
end $$;
revoke all on function public.filey_setting_number_guard() from public,anon,authenticated;
drop trigger if exists zz_filey_setting_number on public.app_settings;
create trigger zz_filey_setting_number before insert or update on public.app_settings for each row execute function public.filey_setting_number_guard();
notify pgrst,'reload schema';

-- Source: supabase/2026-10-04-atomic-lead-setup.sql
-- Service-only atomic inquiry, voucher, coupon and owner notification setup.
-- Existing inquiries/coupons are retained. Public callers use the bounded,
-- rate-limited lead-contact endpoint; they cannot call this RPC directly.

create table if not exists public.lead_setup_requests (
  request_id uuid primary key,
  payload jsonb not null,
  lead_id bigint not null references public.lead_requests(id),
  result jsonb not null,
  created_at timestamptz not null default now()
);
alter table public.lead_setup_requests enable row level security;
revoke all on public.lead_setup_requests from public,anon,authenticated;
grant all on public.lead_setup_requests to service_role;

create or replace function public.filey_record_lead(
  p_request uuid,p_name text,p_phone text,p_email text,p_message text,
  p_source text,p_ip text,p_plan text,p_code text,p_expires_at timestamptz
) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_payload jsonb; v_saved public.lead_setup_requests; v_id bigint; v_result jsonb;
  v_owner public.profiles; v_emailed boolean;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Service access required' using errcode='42501';
  end if;
  if p_request is null or p_name is null or btrim(p_name)='' or length(p_name)>120
    or p_phone is null or length(p_phone)>40 or length(regexp_replace(p_phone,'[^0-9]','','g'))<6
    or coalesce(length(p_email),0)>200 or coalesce(length(p_message),0)>1000
    or p_source is null or p_source not in ('app','website')
    or p_ip is null or length(p_ip)>128
    or p_plan is null or p_plan not in ('freedom','enterprise') then
    raise exception 'Invalid inquiry' using errcode='22023';
  end if;
  if (p_plan='enterprise' and (p_code is not null or p_expires_at is not null))
    or (p_plan='freedom' and (p_code is null
      or p_code!~'^FL-[23456789ABCDEFGHJKLMNPQRSTUVWXYZ]{5}-[23456789ABCDEFGHJKLMNPQRSTUVWXYZ]{5}-[23456789ABCDEFGHJKLMNPQRSTUVWXYZ]{5}-[23456789ABCDEFGHJKLMNPQRSTUVWXYZ]{5}$'
      or p_expires_at is null or p_expires_at<=now() or p_expires_at>now()+interval '31 days')) then
    raise exception 'Invalid inquiry follow-up' using errcode='22023';
  end if;
  -- Provider-generated coupon/expiry and changing network address are not part
  -- of the user's immutable form. A retry gets the originally stored values.
  v_payload:=jsonb_build_object('name',p_name,'phone',p_phone,'email',coalesce(p_email,''),
    'message',coalesce(p_message,''),'source',p_source,'plan',p_plan);
  perform pg_advisory_xact_lock(hashtextextended('filey:lead:'||p_request::text,0));
  select * into v_saved from public.lead_setup_requests where request_id=p_request;
  if found then
    if v_saved.payload is distinct from v_payload then
      raise exception 'Inquiry request was already used differently' using errcode='22023';
    end if;
    select emailed into strict v_emailed from public.lead_requests where id=v_saved.lead_id;
    return v_saved.result||jsonb_build_object('emailed',v_emailed);
  end if;
  insert into public.lead_requests(name,phone,email,message,plan,source,ip)
    values(p_name,p_phone,nullif(p_email,''),
      case when p_plan='enterprise' then '[Enterprise inquiry] '||coalesce(p_message,'') else nullif(p_message,'') end,
      p_plan,p_source,p_ip) returning id into v_id;
  if p_plan='freedom' then
    insert into public.vouchers(code,max_uses,expires_at) values(p_code,1,p_expires_at);
    insert into public.lead_coupons(lead_id,name,phone,email,message,source,code)
      values(v_id,p_name,p_phone,nullif(p_email,''),nullif(p_message,''),p_source,p_code);
  end if;
  -- A customer's signup order is never authority to receive private leads or
  -- license codes. Only the configured platform owner gets the notification.
  select p.* into v_owner from public.profiles p join public.platform_config c
    on c.key='owner_uid' and c.value=p.id::text;
  if found then
    insert into public.notifications(org_id,user_id,actor,kind,body,link)
      values(v_owner.org_id,v_owner.id,'Website','lead',
        case when p_plan='enterprise' then p_name||' requested Filey Enterprise. Review their requirements and contact details.'
          else p_name||' requested Filey Freedom. Coupon '||p_code||' (expires '||to_char(p_expires_at at time zone 'UTC','YYYY-MM-DD')||').' end,
        '/settings?section=billing');
  end if;
  v_result:=jsonb_build_object('id',v_id,'code',p_code,'expires_at',p_expires_at,'emailed',false);
  insert into public.lead_setup_requests(request_id,payload,lead_id,result) values(p_request,v_payload,v_id,v_result);
  return v_result;
end $$;
revoke all on function public.filey_record_lead(uuid,text,text,text,text,text,text,text,text,timestamptz) from public,anon,authenticated;
grant execute on function public.filey_record_lead(uuid,text,text,text,text,text,text,text,text,timestamptz) to service_role;
notify pgrst,'reload schema';

-- Source: supabase/2026-10-04-atomic-business-workflows.sql
-- Document, stock, ledger, credit allocation and receipt are one transaction.
-- Dispatchers run under a nonowner, nonbypass role inheriting ordinary RLS.
-- Invoker helpers retain record/module policies; no service-role shortcut.

-- The dispatcher owns neither business tables nor an RLS bypass. Inheriting
-- authenticated makes existing TO authenticated policies apply to its calls.
-- Clients are never members of this narrowly privileged execution role.
do $$ begin
  if not exists(select 1 from pg_roles where rolname='filey_workflow_executor') then
    create role filey_workflow_executor nologin nosuperuser nobypassrls inherit;
  end if;
  if exists(select 1 from pg_roles where rolname='filey_workflow_executor' and
      (rolcanlogin or rolsuper or rolbypassrls or rolcreaterole or rolcreatedb or rolreplication))
    or pg_has_role('authenticated','filey_workflow_executor','MEMBER')
    or pg_has_role('anon','filey_workflow_executor','MEMBER')
    or pg_has_role('service_role','filey_workflow_executor','MEMBER') then
    raise exception 'The workflow execution role must be nonlogin/nonbypass and unavailable to client roles.';
  end if;
end $$;
grant authenticated to filey_workflow_executor;
grant filey_workflow_executor to postgres;
-- ALTER FUNCTION OWNER requires CREATE for the new owner when the installer
-- is not a superuser (as on managed Postgres). It is revoked before commit.
grant usage,create on schema public to filey_workflow_executor;
alter table public.transactions add column if not exists po_id bigint;
alter table public.transactions add column if not exists workflow_payment_id bigint;
alter table public.transactions add column if not exists advance_id bigint;
alter table public.stock_movements add column if not exists workflow_kind text;
alter table public.stock_movements add column if not exists workflow_id bigint;
alter table public.stock_movements add column if not exists cost_before numeric;
alter table public.orders add column if not exists invoice_id bigint;
alter table public.invoice_docs add column if not exists order_id bigint;
alter table public.advances add column if not exists accounting_posted boolean not null default false;
create index if not exists transactions_po_workflow on public.transactions(po_id,workflow_payment_id);
create index if not exists stock_movement_workflow on public.stock_movements(workflow_kind,workflow_id);
create index if not exists orders_invoice_workflow on public.orders(invoice_id);

create table if not exists public.business_workflow_requests (
  user_id uuid not null default auth.uid(), org_id text not null default public.current_org(),
  request_id uuid not null, action text not null, payload jsonb not null, result jsonb not null,
  created_at timestamptz not null default now(), primary key(user_id,org_id,request_id)
);
alter table public.business_workflow_requests enable row level security;
revoke all on public.business_workflow_requests from public,anon,authenticated;
grant select on public.business_workflow_requests to authenticated;
grant select,insert on public.business_workflow_requests to filey_workflow_executor;
grant all on public.business_workflow_requests to service_role;
drop policy if exists business_workflow_owner on public.business_workflow_requests;
create policy business_workflow_owner on public.business_workflow_requests for select to authenticated
  using(user_id=auth.uid() and org_id=public.current_org() and public.filey_is_workspace_member(org_id));
drop policy if exists business_workflow_insert on public.business_workflow_requests;
create policy business_workflow_insert on public.business_workflow_requests for insert to authenticated
  with check(user_id=auth.uid() and org_id=public.current_org() and public.filey_is_workspace_member(org_id)
    and length(action)<=64 and jsonb_typeof(payload)='object' and jsonb_typeof(result)='object'
    and octet_length(payload::text)<=8388608 and octet_length(result::text)<=2048);

create or replace function public.filey_workflow_guard(p_actor uuid,p_org text,p_module text) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
  if auth.uid() is null or auth.uid() is distinct from p_actor or public.current_org() is distinct from p_org
    or not public.filey_is_workspace_member(p_org) or not public.filey_can_use(p_module) then
    raise exception 'Your account or workspace changed. Reopen this document.' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_org||':business-workflows',0));
end $$;
create or replace function public.filey_workflow_round(p_value numeric) returns numeric
language sql immutable as $$ select floor((p_value+0.0000000000000002)*100+0.5)/100 $$;
create or replace function public.filey_workflow_number(p_value text) returns numeric
language plpgsql immutable as $$
declare v text;
begin
  v:=substring(btrim(coalesce(p_value,'')) from '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?');
  if v is null then return 0; end if;
  if length(v)>100 then raise exception 'Item number is outside the valid range.' using errcode='22023'; end if;
  return v::numeric;
end $$;
create or replace function public.filey_workflow_totals(p_doc jsonb,p_items jsonb,p_purchase boolean default false)
returns jsonb language plpgsql immutable set search_path=public,pg_temp as $$
declare
  v_item jsonb; v_custom jsonb; v_i int:=0; v_qty numeric; v_price numeric; v_gross numeric; v_net numeric;
  v_pct numeric; v_rate numeric; v_key text; v_cat text; v_multiplier text; v_lines jsonb:='[]';
  v_subtotal numeric:=0; v_discount numeric; v_tax numeric:=0; v_total numeric; v_sum numeric:=0;
begin
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>500 then
    raise exception 'A document supports at most 500 valid item rows.' using errcode='22023';
  end if;
  foreach v_key in array array['discount','tax_rate'] loop
    if public.filey_workflow_number(p_doc->>v_key)<0 then raise exception 'Discount and tax cannot be negative.' using errcode='22023'; end if;
  end loop;
  for v_item in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_item) is distinct from 'object' then raise exception 'Invalid item row.' using errcode='22023'; end if;
    v_i:=v_i+1; v_custom:=coalesce(v_item->'custom','{}'::jsonb);
    v_qty:=public.filey_workflow_number(v_item->>case when p_purchase then 'quantity' else 'qty' end);
    v_price:=public.filey_workflow_number(v_item->>case when p_purchase then 'unit_cost' else 'unit_price' end);
    if least(v_qty,v_price)<0 or greatest(v_qty,v_price)>=1000000000000 then raise exception 'Enter valid non-negative quantities and prices.' using errcode='22023'; end if;
    v_multiplier:=coalesce(case when v_custom->>'__calc_mode'='formula' then nullif(v_custom->>'__formula_a','') end,nullif(p_doc->'unit_price_formula'->>'a',''),'qty');
    if v_custom->>'__calc_mode'='manual' then v_gross:=public.filey_workflow_number(v_custom->>'__manual_amount');
    else
      v_gross:=public.filey_workflow_round((case when v_multiplier='qty' then v_qty else public.filey_workflow_number(v_custom->>v_multiplier) end)*v_price);
    end if;
    v_pct:=public.filey_workflow_number(v_custom->>'__disc_pct');
    v_rate:=public.filey_workflow_number(v_custom->>'__tax_pct');
    if least(v_gross,v_pct,v_rate)<0 or greatest(v_pct,v_rate)>100 or v_gross>=100000000000000 then
      raise exception 'Enter valid item amounts, discounts and tax percentages.' using errcode='22023';
    end if;
    v_net:=public.filey_workflow_round(v_gross*(1-v_pct/100));
    v_subtotal:=v_subtotal+public.filey_workflow_round(v_gross);
    v_cat:=coalesce(nullif(v_item->>'tax_category',''),'S');
    if v_cat not in ('S','Z','E','O','AE') then raise exception 'Choose a supported tax category.' using errcode='22023'; end if;
    v_rate:=case when v_cat='S' then case when v_rate<>0 then v_rate else public.filey_workflow_number(p_doc->>'tax_rate') end else 0 end;
    if v_rate>100 then raise exception 'Tax rate cannot exceed 100 percent.' using errcode='22023'; end if;
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object('category',v_cat,'rate',v_rate,'cents',floor(v_net*100+0.5),'position',v_i));
  end loop;
  select coalesce(sum((value->>'cents')::numeric),0) into v_sum from jsonb_array_elements(v_lines);
  v_discount:=least(greatest(0,floor(public.filey_workflow_number(p_doc->>'discount')*100+0.5)),v_sum);
  -- Allocate document discount by largest remainder. Ties follow the first
  -- appearance of a tax group, exactly as the shared preview/PDF calculator.
  with groups as (
    select value->>'category' category,(value->>'rate')::numeric rate,sum((value->>'cents')::numeric) cents,
      min((value->>'position')::int) position from jsonb_array_elements(v_lines) group by 1,2
  ), shares as (
    select *,case when v_sum>0 then v_discount*cents/v_sum else 0 end exact from groups
  ), ranked as (
    select *,floor(exact) base,row_number() over(order by exact-floor(exact) desc,position) rank,
      v_discount-sum(floor(exact)) over() remainder from shares
  ) select coalesce(sum(public.filey_workflow_round(((cents-base-case when rank<=remainder then 1 else 0 end)/100)*rate/100)),0)
    into v_tax from ranked;
  v_net:=(v_sum-v_discount)/100;
  v_total:=public.filey_workflow_round(v_net+v_tax);
  if not p_purchase and coalesce((p_doc->>'round_off')::boolean,false) then v_total:=floor(v_total+0.5); end if;
  return jsonb_build_object('subtotal',v_subtotal,'net',public.filey_workflow_round(v_total-v_tax),'tax',v_tax,'total',v_total);
end $$;

create or replace function public.filey_workflow_fx(p_doc jsonb,p_rates jsonb default '{}') returns numeric
language plpgsql immutable as $$
declare v_currency text:=upper(coalesce(nullif(p_doc->>'currency',''),'AED')); v_fx numeric;
begin
  if v_currency='AED' then return 1; end if;
  v_fx:=coalesce(nullif(p_doc->>'fx_rate','')::numeric,nullif(p_rates->>v_currency,'')::numeric);
  if v_currency !~ '^[A-Z]{3}$' or v_fx is null or v_fx::text in ('NaN','Infinity','-Infinity') or v_fx<=0 or v_fx>1000000 then
    raise exception 'Set a valid exchange rate before posting this currency.' using errcode='22023';
  end if;
  return v_fx;
end $$;
-- Admin edits keep generated accounts and effects under the document author.
create or replace function public.filey_workflow_account_for_owner(p_type text,p_code text,p_name text,p_pattern text,p_owner uuid) returns bigint
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_id bigint;
begin
  if not public.filey_can_use('accounting') or p_owner is null or not (p_owner=auth.uid() or public.is_org_admin()) then raise exception 'Accounting access is required to post this document.' using errcode='42501'; end if;
  select id into v_id from public.accounts where org_id=public.current_org() and account_type=p_type
    and user_id=p_owner and name ~* p_pattern order by id limit 1;
  if v_id is null then insert into public.accounts(code,name,account_type,balance,user_id) values(p_code,p_name,p_type,0,p_owner) returning id into v_id; end if;
  return v_id;
end $$;
create or replace function public.filey_workflow_account(p_type text,p_code text,p_name text,p_pattern text) returns bigint
language plpgsql security invoker set search_path=public,pg_temp as $$
begin return public.filey_workflow_account_for_owner(p_type,p_code,p_name,p_pattern,auth.uid()); end $$;
create or replace function public.filey_workflow_entry(p_account bigint,p_side text,p_amount numeric,p_description text,p_ref text,p_source text,p_date date,
  p_invoice bigint default null,p_po bigint default null,p_payment bigint default null) returns bigint
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_type text; v_id bigint; v_changed bigint; v_delta numeric; v_owner uuid;
begin
  p_amount:=public.filey_workflow_round(p_amount);
  if p_amount=0 then return null; end if;
  if p_amount is null or p_amount::text in ('NaN','Infinity','-Infinity') or p_amount<0 or p_amount>=100000000000000
    or p_side not in ('debit','credit') or p_date is null then raise exception 'Invalid accounting entry.' using errcode='22023'; end if;
  select account_type,user_id into v_type,v_owner from public.accounts where id=p_account and org_id=public.current_org()
    and (user_id=auth.uid() or public.is_org_admin()) for update;
  if not found then raise exception 'Account not found or posting denied.' using errcode='42501'; end if;
  v_delta:=p_amount*case when (v_type in ('asset','expense'))=(p_side='debit') then 1 else -1 end;
  insert into public.transactions(account_id,txn_type,amount,description,ref,source,txn_date,invoice_id,po_id,workflow_payment_id,user_id)
    values(p_account,p_side,p_amount,p_description,p_ref,p_source,p_date,p_invoice,p_po,p_payment,v_owner) returning id into v_id;
  update public.accounts set balance=balance+v_delta where id=p_account returning id into v_changed;
  if v_changed is null then raise exception 'Account update denied.' using errcode='42501'; end if;
  return v_id;
end $$;
create or replace function public.filey_workflow_reverse(p_ids bigint[]) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_row record; v_type text; v_changed bigint;
begin
  for v_row in select * from public.transactions where id=any(p_ids) order by account_id,id for update loop
    select account_type into v_type from public.accounts where id=v_row.account_id and org_id=public.current_org()
      and (user_id=auth.uid() or public.is_org_admin()) for update;
    if not found then raise exception 'Account not found or reversal denied.' using errcode='42501'; end if;
    update public.accounts set balance=balance-v_row.amount*case when (v_type in ('asset','expense'))=(v_row.txn_type='debit') then 1 else -1 end
      where id=v_row.account_id returning id into v_changed;
    if v_changed is null then raise exception 'Account reversal denied.' using errcode='42501'; end if;
    delete from public.transactions where id=v_row.id returning id into v_changed;
    if v_changed is null then raise exception 'Ledger reversal denied.' using errcode='42501'; end if;
  end loop;
end $$;
create or replace function public.filey_workflow_stock(p_product bigint,p_delta numeric,p_kind text,p_id bigint,p_ref text,p_cost numeric default null) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_quantity numeric; v_cost numeric; v_before numeric; v_changed bigint; v_owner uuid; v_product_owner uuid;
begin
  if p_product is null or p_delta=0 then return; end if;
  if not public.filey_can_use('inventory') then raise exception 'Inventory access is required for stock-linked items.' using errcode='42501'; end if;
  select quantity,cost_price,user_id into v_quantity,v_cost,v_product_owner from public.products where id=p_product and org_id=public.current_org()
    and (user_id=auth.uid() or public.is_org_admin()) for update;
  if not found then raise exception 'Product not found or stock update denied.' using errcode='42501'; end if;
  if p_kind='invoice' then select user_id into v_owner from public.invoice_docs where id=p_id and org_id=public.current_org() and (user_id=auth.uid() or public.is_org_admin());
  elsif p_kind='po' then select user_id into v_owner from public.purchase_orders where id=p_id and org_id=public.current_org() and (user_id=auth.uid() or public.is_org_admin());
  elsif p_kind='order' then select user_id into v_owner from public.orders where id=p_id and org_id=public.current_org() and (user_id=auth.uid() or public.is_org_admin());
  else raise exception 'Invalid stock document.' using errcode='22023'; end if;
  if v_owner is null or v_product_owner is distinct from v_owner then raise exception 'Choose stock owned by this document author so its reservation remains reversible.' using errcode='42501'; end if;
  v_before:=v_cost;
  if p_delta>0 and p_cost>0 then
    v_cost:=public.filey_workflow_round(case when v_quantity>0 and v_cost>0 then (v_quantity*v_cost+p_delta*p_cost)/(v_quantity+p_delta) else p_cost end);
  end if;
  update public.products set quantity=quantity+p_delta,cost_price=v_cost where id=p_product returning id into v_changed;
  if v_changed is null then raise exception 'Stock update denied.' using errcode='42501'; end if;
  insert into public.stock_movements(product_id,qty,type,ref,note,workflow_kind,workflow_id,cost_before,user_id)
    values(p_product,p_delta,case when p_kind='order' then 'order' when p_delta>0 then 'purchase' else 'sale' end,p_ref,null,p_kind,p_id,case when p_delta>0 and p_cost is not null then v_before end,v_owner);
end $$;

-- Undo exactly this document's stock, including prior reversals. Historic
-- records have no IDs in the journal: only an unambiguous same-author reference
-- is eligible for legacy recovery; otherwise require reconciliation.
-- Historic admin-owned later movements can be invisible under staff RLS.
-- This returns only a permission-scoped yes/no and never private journal data.
create or replace function public.filey_workflow_receipt_reversible(p_kind text,p_id bigint,p_product bigint) returns boolean
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_first bigint;
begin
  if p_kind not in ('invoice','po') or not public.filey_workflow_effects_owned(p_kind,p_id,public.current_org()) or not public.filey_can_use('inventory') then return false; end if;
  select min(id) into v_first from public.stock_movements where org_id=public.current_org() and product_id=p_product
    and workflow_kind=p_kind and workflow_id=p_id and qty>0 and cost_before is not null;
  if v_first is null then return false; end if;
  return not exists(select 1 from public.stock_movements where product_id=p_product and id>v_first and qty<>0
    and (workflow_kind is distinct from p_kind or workflow_id is distinct from p_id));
end $$;
create or replace function public.filey_workflow_unstock(p_kind text,p_id bigint,p_ref text,p_owner uuid,p_items jsonb,p_legacy boolean,p_purchase boolean) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_row record; v_found boolean:=false; v_ambiguous boolean; v_first bigint; v_cost numeric;
begin
  for v_row in select product_id,sum(qty) qty from public.stock_movements where org_id=public.current_org()
    and workflow_kind=p_kind and workflow_id=p_id group by product_id loop
    v_found:=true;
    if p_purchase and v_row.qty>0 then
      select id,cost_before into v_first,v_cost from public.stock_movements where org_id=public.current_org() and product_id=v_row.product_id
        and workflow_kind=p_kind and workflow_id=p_id and qty>0 and cost_before is not null order by id limit 1;
      if v_first is null then raise exception 'This historic receipt needs cost reconciliation before reversal.' using errcode='22023'; end if;
      if not public.filey_workflow_receipt_reversible(p_kind,p_id,v_row.product_id) then raise exception 'Later stock movements use this receipt''s cost. Reconcile them before reversing it.' using errcode='22023'; end if;
      update public.products set cost_price=v_cost where id=v_row.product_id;
    end if;
    perform public.filey_workflow_stock(v_row.product_id,-v_row.qty,p_kind,p_id,p_ref);
  end loop;
  if v_found or not p_legacy then return; end if;
  if p_kind='invoice' then
    select count(*)>1 into v_ambiguous from public.invoice_docs where org_id=public.current_org() and user_id=p_owner
      and (case when doc_type='purchase' then 'Bill ' else 'Invoice ' end)||number=p_ref;
  else
    select count(*)>1 into v_ambiguous from public.purchase_orders where org_id=public.current_org() and user_id=p_owner and 'PO '||po_number=p_ref;
  end if;
  if p_purchase and exists(select 1 from jsonb_array_elements(p_items) where nullif(value->>'product_id','') is not null) then raise exception 'This historic receipt needs cost reconciliation before reversal.' using errcode='22023'; end if;
  if v_ambiguous then raise exception 'Historic document references overlap. Reconcile stock before changing this document.' using errcode='22023'; end if;
  for v_row in select product_id,sum(qty) qty from public.stock_movements where org_id=public.current_org()
    and user_id=p_owner and ref=p_ref and workflow_kind is null group by product_id loop
    v_found:=true;
    perform public.filey_workflow_stock(v_row.product_id,-v_row.qty,p_kind,p_id,p_ref);
    -- Attribute the old footprint after proving its reference unambiguous.
    update public.stock_movements set workflow_kind=p_kind,workflow_id=p_id
      where org_id=public.current_org() and user_id=p_owner and ref=p_ref and workflow_kind is null and product_id=v_row.product_id;
  end loop;
  if not v_found then
    for v_row in select value from jsonb_array_elements(p_items) loop
      perform public.filey_workflow_stock(nullif(v_row.value->>'product_id','')::bigint,
        abs(public.filey_workflow_number(v_row.value->>case when p_kind='po' then 'quantity' else 'qty' end))*case when p_purchase then -1 else 1 end,p_kind,p_id,p_ref);
    end loop;
    -- Missing historic journal: the reversal is an audited correction, but
    -- cannot represent a negative current footprint on the next edit.
    update public.stock_movements set workflow_kind='legacy-reversal' where workflow_kind=p_kind and workflow_id=p_id;
  end if;
end $$;

create or replace function public.filey_workflow_unpost(p_kind text,p_doc jsonb,p_items jsonb,p_delete boolean default false) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_id bigint:=(p_doc->>'id')::bigint; v_ref text; v_ids bigint[]; v_purchase boolean; v_posted boolean; v_owner uuid:=(p_doc->>'user_id')::uuid;
begin
  v_purchase:=p_kind='po' or coalesce(p_doc->>'doc_type'='purchase',false);
  v_posted:=case when p_kind='po' then p_doc->>'status' in ('received','completed') else p_doc->>'status' in ('sent','paid','overdue') end;
  v_ref:=case when p_kind='po' then 'PO '||(p_doc->>'po_number') when v_purchase then 'Bill '||(p_doc->>'number') else 'Invoice '||(p_doc->>'number') end;
  select array_agg(id) into v_ids from public.transactions where org_id=public.current_org() and (user_id=v_owner or public.is_org_admin())
    and (case when p_kind='po' then po_id=v_id or (po_id is null and invoice_id is null and ref=v_ref and user_id=v_owner)
      else invoice_id=v_id or (invoice_id is null and po_id is null and ref=v_ref and user_id=v_owner) end)
    and (p_delete or coalesce(source,'')<>'payment');
  if v_ids is not null and exists(select 1 from public.transactions where id=any(v_ids) and invoice_id is null and po_id is null) and
    (case when p_kind='po' then (select count(*) from public.purchase_orders where org_id=public.current_org() and user_id=v_owner and 'PO '||po_number=v_ref)
      else (select count(*) from public.invoice_docs where org_id=public.current_org() and user_id=v_owner and (case when doc_type='purchase' then 'Bill ' else 'Invoice ' end)||number=v_ref) end)>1 then
    raise exception 'Historic document references overlap. Reconcile the ledger before changing this document.' using errcode='22023';
  end if;
  perform public.filey_workflow_reverse(v_ids);
  if (v_posted or v_ids is not null or coalesce((p_doc->>'stock_received')::boolean,false))
    and not (p_kind='invoice' and coalesce(p_doc->>'invoice_type_code' in ('381','81'),false)) then
    perform public.filey_workflow_unstock(p_kind,v_id,v_ref,v_owner,p_items,
      case when p_kind='po' then coalesce((p_doc->>'stock_received')::boolean,false) else v_posted end,v_purchase);
  end if;
  if p_kind='po' then update public.purchase_orders set stock_received=false where id=v_id; end if;
  if p_kind='invoice' and not v_purchase then
    delete from public.orders where org_id=public.current_org() and (user_id=v_owner or public.is_org_admin()) and
      (invoice_id=v_id or (invoice_id is null and user_id=v_owner and order_number='SO-'||(p_doc->>'number')
        and not exists(select 1 from public.order_items oi where oi.order_id=orders.id)));
  end if;
end $$;

create or replace function public.filey_workflow_post(p_kind text,p_doc jsonb,p_items jsonb,p_rates jsonb default '{}') returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare
  v_id bigint:=(p_doc->>'id')::bigint; v_invoice bigint; v_po bigint; v_purchase boolean:=p_kind='po' or coalesce(p_doc->>'doc_type'='purchase',false);
  v_credit boolean:=p_kind='invoice' and coalesce(p_doc->>'invoice_type_code' in ('381','81'),false); v_totals jsonb; v_fx numeric;
  v_tax numeric; v_total numeric; v_net numeric; v_ref text; v_date date; v_source text; v_item jsonb;
  v_product bigint; v_qty numeric; v_cost numeric; v_cogs numeric:=0; v_target bigint; v_counter bigint;
begin
  if not public.filey_can_use('accounting') then raise exception 'Accounting access is required to post this document.' using errcode='42501'; end if;
  if v_credit and v_purchase then raise exception 'Keep supplier credit notes as drafts until supplier credit posting is available.' using errcode='22023'; end if;
  if v_credit and p_doc->'einvoice'->>'credit_reason' is distinct from 'VD'
    and (coalesce(p_doc->>'original_invoice_number','')='' or coalesce(p_doc->>'original_invoice_date','')='') then
    raise exception 'Add the original invoice number and date before posting a credit note.' using errcode='22023';
  end if;
  if coalesce(p_doc->>case when p_kind='po' then 'po_number' else 'number' end,'')='' then
    raise exception 'Add a document number before posting.' using errcode='22023';
  end if;
  v_fx:=public.filey_workflow_fx(p_doc,p_rates); v_totals:=public.filey_workflow_totals(p_doc,p_items,p_kind='po');
  v_total:=public.filey_workflow_round((v_totals->>'total')::numeric*v_fx);
  v_tax:=public.filey_workflow_round((v_totals->>'tax')::numeric*v_fx); v_net:=v_total-v_tax;
  if p_kind='po' then v_po:=v_id; else v_invoice:=v_id; end if;
  v_ref:=case when p_kind='po' then 'PO '||(p_doc->>'po_number') when v_purchase then 'Bill '||(p_doc->>'number') else 'Invoice '||(p_doc->>'number') end;
  v_source:=case when v_purchase then 'purchase_invoice' else 'invoice' end;
  v_date:=coalesce(nullif(p_doc->>case when p_kind='po' then 'order_date' else 'issue_date' end,'')::date,current_date);
  if not v_credit then
    for v_item in select value from jsonb_array_elements(p_items) loop
      v_product:=nullif(v_item->>'product_id','')::bigint; if v_product is null then continue; end if;
      v_qty:=abs(public.filey_workflow_number(v_item->>case when p_kind='po' then 'quantity' else 'qty' end));
      select cost_price into v_cost from public.products where id=v_product;
      if not found then raise exception 'Product not found or access denied.' using errcode='42501'; end if;
      v_cogs:=v_cogs+v_qty*v_cost;
      perform public.filey_workflow_stock(v_product,v_qty*case when v_purchase then 1 else -1 end,p_kind,v_id,v_ref,
        case when v_purchase then public.filey_workflow_number(v_item->>case when p_kind='po' then 'unit_cost' else 'unit_price' end)*v_fx else null end);
    end loop;
    if p_kind='po' then update public.purchase_orders set stock_received=true where id=v_id;
    elsif not v_purchase then
      insert into public.orders(order_number,customer_name,customer_id,status,total,invoice_id,user_id)
        values('SO-'||(p_doc->>'number'),coalesce(p_doc->>'customer_name',''),nullif(p_doc->>'customer_id','')::bigint,'completed',v_total,v_id,(p_doc->>'user_id')::uuid);
      if public.filey_workflow_round(v_cogs)>0 then
        v_target:=public.filey_workflow_account_for_owner('expense','5050','Cost of Goods Sold','cost of goods|cogs',(p_doc->>'user_id')::uuid);
        v_counter:=public.filey_workflow_account_for_owner('asset','1300','Inventory','inventory|stock',(p_doc->>'user_id')::uuid);
        perform public.filey_workflow_entry(v_target,'debit',v_cogs,v_ref||' — cost of goods sold',v_ref,'invoice',v_date,v_id);
        perform public.filey_workflow_entry(v_counter,'credit',v_cogs,v_ref||' — inventory issued',v_ref,'invoice',v_date,v_id);
      end if;
    end if;
  end if;
  if v_total=0 then return; end if;
  v_target:=case when v_purchase then public.filey_workflow_account_for_owner('asset','1300','Inventory','inventory|stock',(p_doc->>'user_id')::uuid)
    else public.filey_workflow_account_for_owner('revenue','4000','Sales Revenue','sales|revenue|income',(p_doc->>'user_id')::uuid) end;
  v_counter:=case when v_purchase then public.filey_workflow_account_for_owner('liability','2000','Accounts Payable','\m(payable|creditors|ap)\M',(p_doc->>'user_id')::uuid)
    else public.filey_workflow_account_for_owner('asset','1200','Accounts Receivable','\m(receivable|debtors|ar)\M',(p_doc->>'user_id')::uuid) end;
  perform public.filey_workflow_entry(v_target,case when v_purchase or v_credit then 'debit' else 'credit' end,v_net,v_ref,v_ref,v_source,v_date,v_invoice,v_po);
  perform public.filey_workflow_entry(v_counter,case when v_purchase or v_credit then 'credit' else 'debit' end,v_total,v_ref,v_ref,v_source,v_date,v_invoice,v_po);
  if v_tax>0 then
    v_target:=case when v_purchase then public.filey_workflow_account_for_owner('asset','1250','Input VAT','input vat|vat on purchases|purchase vat|vat recoverable',(p_doc->>'user_id')::uuid)
      else public.filey_workflow_account_for_owner('liability','2100','Output VAT','output vat|vat on sales|sales vat',(p_doc->>'user_id')::uuid) end;
    perform public.filey_workflow_entry(v_target,case when v_purchase or v_credit then 'debit' else 'credit' end,v_tax,v_ref||' — VAT',v_ref,v_source,v_date,v_invoice,v_po);
  end if;
end $$;

-- Boolean-only privileged pool check: staff cannot spend read-only shared
-- deposits or miss consumption hidden behind another invoice author. New
-- allocations always use the original invoice author's pool, even for admins.
create or replace function public.filey_workflow_credit_available(p_type text,p_party bigint,p_owner uuid,p_exclude text,p_need numeric) returns boolean
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_available numeric; v_org text:=public.current_org(); v_invoice bigint;
begin
  if auth.uid() is null or not public.filey_is_workspace_member(v_org) or not public.filey_can_use('invoicing') or not public.filey_can_use('people')
    or p_owner is null or not (p_owner=auth.uid() or public.is_org_admin()) or p_need is null or p_need<0 then return false; end if;
  if p_exclude is not null then
    if p_exclude !~ '^applied:inv#[0-9]+$' then return false; end if;
    v_invoice:=substring(p_exclude from '[0-9]+$')::bigint;
    if not exists(select 1 from public.invoice_docs where id=v_invoice and org_id=v_org and user_id=p_owner) then return false; end if;
  end if;
  -- Older admin-created allocations can have a different author from their
  -- parent. They cannot be attributed safely to a private pool automatically.
  if exists(select 1 from public.advances a left join public.invoice_docs d
    on a.note='applied:inv#'||d.id and d.org_id=a.org_id
    where a.org_id=v_org and a.party_type=p_type and a.party_id=p_party and a.amount<0
      and (d.id is null or d.user_id is distinct from a.user_id)) then return false; end if;
  -- Old shared-credit spending can have matching parent/allocation authors
  -- while borrowing another author's deposit. A negative private pool makes
  -- that attribution unsafe; no other intact-looking deposit can be reused.
  if exists(select 1 from public.advances where org_id=v_org and party_type=p_type and party_id=p_party
    group by user_id having sum(amount)<-0.005) then return false; end if;
  select coalesce(sum(amount),0) into v_available from public.advances where org_id=v_org
    and party_type=p_type and party_id=p_party and user_id=p_owner and (p_exclude is null or note is distinct from p_exclude);
  return p_need<=v_available+0.005;
end $$;
create or replace function public.filey_workflow_advance(p_doc jsonb,p_amount numeric,p_previous jsonb) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_id bigint:=(p_doc->>'id')::bigint; v_owner uuid:=(p_doc->>'user_id')::uuid; v_party bigint:=nullif(p_doc->>'customer_id','')::bigint;
  v_base numeric; v_tag text:='applied:inv#'||v_id; v_items jsonb; v_total numeric; v_ids bigint[]; v_liability bigint; v_ar bigint; v_retain boolean:=false;
begin
  if not (v_owner=auth.uid() or public.is_org_admin()) then raise exception 'Invoice allocation denied.' using errcode='42501'; end if;
  p_amount:=coalesce(p_amount,0);
  if (p_amount>0 or coalesce((p_previous->>'advance_applied')::numeric,0)>0) and not public.filey_can_use('people') then raise exception 'Advance access is required to change allocated credit.' using errcode='42501'; end if;
  if p_amount::text in ('NaN','Infinity','-Infinity') or p_amount<0 then raise exception 'Enter a valid advance allocation.' using errcode='22023'; end if;
  if p_amount>0 and (v_party is null or p_doc->>'doc_type'='purchase' or p_doc->>'invoice_type_code' in ('381','81')) then
    raise exception 'Choose the customer before applying advance credit.' using errcode='22023'; end if;
  if p_amount>0 then
    v_base:=public.filey_workflow_round(p_amount*public.filey_workflow_fx(p_doc));
    select coalesce(jsonb_agg(to_jsonb(i)),'[]') into v_items from public.invoice_doc_items i where invoice_id=v_id;
    v_total:=(public.filey_workflow_totals(p_doc,v_items)->>'total')::numeric;
    if p_amount>v_total+0.005 then raise exception 'Advance allocation cannot exceed this invoice total.' using errcode='22023'; end if;
    perform 1 from public.crm_customers where id=v_party and org_id=public.current_org();
    if not found then raise exception 'Customer not found or access denied.' using errcode='42501'; end if;
    v_retain:=p_previous is not null and p_previous->>'customer_id' is not distinct from p_doc->>'customer_id'
      and coalesce(p_previous->>'currency','AED')=coalesce(p_doc->>'currency','AED')
      and p_previous->'fx_rate' is not distinct from p_doc->'fx_rate'
      and coalesce((p_previous->>'advance_applied')::numeric,0)=p_amount
      and exists(select 1 from public.advances where org_id=public.current_org() and user_id=v_owner
        and note=v_tag and party_type='customer' and party_id=v_party and amount=-v_base);
    if not v_retain and not public.filey_workflow_credit_available('customer',v_party,v_owner,v_tag,v_base) then
      raise exception 'Insufficient editable customer advance credit. Refresh the available balance or reconcile historic allocations.' using errcode='22023'; end if;
  end if;
  select array_agg(id) into v_ids from public.transactions where invoice_id=v_id and source='advance_allocation';
  perform public.filey_workflow_reverse(v_ids);
  if not v_retain then
    delete from public.advances where org_id=public.current_org() and user_id=v_owner and note=v_tag;
    if p_amount>0 then insert into public.advances(party_type,party_id,party_name,amount,note,user_id)
      values('customer',v_party,coalesce(p_doc->>'customer_name',''),-v_base,v_tag,v_owner); end if;
  end if;
  if p_amount>0 and p_doc->>'status' in ('sent','paid','overdue') then
    v_liability:=public.filey_workflow_account_for_owner('liability','2200','Customer Advances','customer advances|customer deposits',v_owner);
    v_ar:=public.filey_workflow_account_for_owner('asset','1200','Accounts Receivable','\m(receivable|debtors|ar)\M',v_owner);
    perform public.filey_workflow_entry(v_liability,'debit',v_base,'Customer advance applied',v_tag,'advance_allocation',coalesce(nullif(p_doc->>'issue_date','')::date,current_date),v_id);
    perform public.filey_workflow_entry(v_ar,'credit',v_base,'Customer advance applied — AR reduction',v_tag,'advance_allocation',coalesce(nullif(p_doc->>'issue_date','')::date,current_date),v_id);
  end if;
end $$;
-- Replace the historic two-argument signature too; upgrades leave no stale body.
create or replace function public.filey_workflow_advance(p_doc jsonb,p_amount numeric) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
begin perform public.filey_workflow_advance(p_doc,p_amount,null); end $$;
create or replace function public.filey_workflow_payment(p_kind text,p_doc jsonb,p_amount numeric,p_method text,p_date date,p_rates jsonb) returns bigint
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_id bigint:=(p_doc->>'id')::bigint; v_payment bigint; v_invoice bigint; v_po bigint;
  v_purchase boolean:=p_kind='po' or coalesce(p_doc->>'doc_type'='purchase',false); v_base numeric; v_spot numeric; v_diff numeric;
  v_cash bigint; v_counter bigint; v_fx bigint; v_ref text; v_total numeric; v_paid numeric; v_items jsonb;
begin
  if p_amount is null or p_amount::text in ('NaN','Infinity','-Infinity') or p_amount<=0 or p_amount>=1000000000000
    or p_amount<>round(p_amount,2) or p_date is null or length(coalesce(p_method,''))>200 then raise exception 'Enter a positive payment amount with at most two decimals and a valid payment date.' using errcode='22023'; end if;
  if p_doc->>'invoice_type_code' in ('381','81') then raise exception 'Credit notes cannot receive invoice payments.' using errcode='22023'; end if;
  if (case when p_kind='po' then p_doc->>'status' not in ('received','completed') else p_doc->>'status' not in ('sent','paid','overdue') end) then
    raise exception 'Finalize or receive this document before recording a payment. Use a party advance for prepayments.' using errcode='22023'; end if;
  v_base:=public.filey_workflow_round(p_amount*public.filey_workflow_fx(p_doc,p_rates));
  v_spot:=public.filey_workflow_round(p_amount*public.filey_workflow_fx(p_doc||jsonb_build_object('fx_rate',null),
    p_rates||case when p_rates->>coalesce(p_doc->>'currency','AED') is null then jsonb_build_object(coalesce(p_doc->>'currency','AED'),public.filey_workflow_fx(p_doc,p_rates)) else '{}'::jsonb end));
  v_diff:=v_spot-v_base;
  if p_kind='po' then
    v_po:=v_id; insert into public.po_payments(po_id,amount,method,paid_at,user_id) values(v_id,p_amount,p_method,p_date,(p_doc->>'user_id')::uuid) returning id into v_payment;
  else
    v_invoice:=v_id; insert into public.invoice_payments(invoice_id,amount,method,paid_at,user_id) values(v_id,p_amount,p_method,p_date,(p_doc->>'user_id')::uuid) returning id into v_payment;
    select coalesce(jsonb_agg(to_jsonb(i) order by position,id),'[]') into v_items from public.invoice_doc_items i where invoice_id=v_id;
    v_total:=(public.filey_workflow_totals(p_doc,v_items)->>'total')::numeric;
    select coalesce(sum(amount),0) into v_paid from public.invoice_payments where invoice_id=v_id;
    update public.invoice_docs set status=case when v_paid+coalesce((p_doc->>'advance_applied')::numeric,0)>=v_total-0.005 then 'paid' when status='paid' then 'sent' else status end where id=v_id;
  end if;
  v_ref:=case when p_kind='po' then 'PO payment #' else 'Invoice payment #' end||v_payment;
  v_cash:=public.filey_workflow_account_for_owner('asset','1000','Cash & Bank','cash|bank',(p_doc->>'user_id')::uuid);
  v_counter:=case when v_purchase then public.filey_workflow_account_for_owner('liability','2000','Accounts Payable','\m(payable|creditors|ap)\M',(p_doc->>'user_id')::uuid)
    else public.filey_workflow_account_for_owner('asset','1200','Accounts Receivable','\m(receivable|debtors|ar)\M',(p_doc->>'user_id')::uuid) end;
  perform public.filey_workflow_entry(v_cash,case when v_purchase then 'credit' else 'debit' end,v_spot,v_ref||' — cash',v_ref,'payment',p_date,v_invoice,v_po,v_payment);
  perform public.filey_workflow_entry(v_counter,case when v_purchase then 'debit' else 'credit' end,v_base,v_ref||case when v_purchase then ' — AP reduction' else ' — AR reduction' end,v_ref,'payment',p_date,v_invoice,v_po,v_payment);
  if abs(v_diff)>=0.01 then
    v_fx:=public.filey_workflow_account_for_owner('expense','5900','Foreign Exchange Gain/Loss','foreign exchange|fx gain|exchange (gain|loss)',(p_doc->>'user_id')::uuid);
    perform public.filey_workflow_entry(v_fx,case when (v_diff>0)=v_purchase then 'debit' else 'credit' end,abs(v_diff),v_ref||' — FX difference',v_ref,'payment',p_date,v_invoice,v_po,v_payment);
  end if;
  return v_payment;
end $$;

-- A boolean-only privileged read detects hidden corrupt historical children.
-- It first proves the parent writable; no private child values are returned.
create or replace function public.filey_workflow_children_owned(p_kind text,p_id bigint,p_org text) returns boolean
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_owner uuid; v_module text;
begin
  if auth.uid() is null or p_org is distinct from public.current_org() or not public.filey_is_workspace_member(p_org) then return false; end if;
  if p_kind='invoice' then select user_id,case when doc_type='purchase' then 'purchase-invoices' else 'invoicing' end into v_owner,v_module
    from public.invoice_docs where id=p_id and org_id=p_org and (user_id=auth.uid() or public.is_org_admin());
  elsif p_kind='po' then select user_id,'purchase-orders' into v_owner,v_module from public.purchase_orders where id=p_id and org_id=p_org and (user_id=auth.uid() or public.is_org_admin());
  elsif p_kind='order' then select user_id,'orders' into v_owner,v_module from public.orders where id=p_id and org_id=p_org and (user_id=auth.uid() or public.is_org_admin());
  else return false; end if;
  if v_owner is null or not public.filey_can_use(v_module) then return false; end if;
  -- A valid admin can replace another author's lines; their creator identity
  -- differs legitimately. The parent policy governs access, while its org
  -- must match every child, including rows hidden by the invoker's RLS.
  if p_kind='invoice' then return not exists(select 1 from public.invoice_doc_items where invoice_id=p_id and (org_id is distinct from p_org or (not public.is_org_admin() and user_id is distinct from v_owner)));
  elsif p_kind='po' then return not exists(select 1 from public.purchase_order_items where po_id=p_id and (org_id is distinct from p_org or (not public.is_org_admin() and user_id is distinct from v_owner)));
  else return not exists(select 1 from public.order_items where order_id=p_id and (org_id is distinct from p_org or (not public.is_org_admin() and user_id is distinct from v_owner))); end if;
end $$;

-- Generated private effects must remain reversible by the original author.
-- The privileged read returns only a boolean after verifying the parent.
create or replace function public.filey_workflow_effects_owned(p_kind text,p_id bigint,p_org text) returns boolean
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_owner uuid; v_ref text; v_legacy boolean; v_number text;
begin
  if p_kind='advance' then
    if auth.uid() is null or p_org is distinct from public.current_org() or not public.filey_is_workspace_member(p_org) or not public.filey_can_use('invoicing') or not public.filey_can_use('accounting') or not public.filey_can_use('people') then return false; end if;
    select user_id into v_owner from public.advances where id=p_id and org_id=p_org and (user_id=auth.uid() or public.is_org_admin());
    if v_owner is null then return false; end if;
  elsif not public.filey_workflow_children_owned(p_kind,p_id,p_org) then return false; end if;
  if p_kind='invoice' then select user_id,(case when doc_type='purchase' then 'Bill ' else 'Invoice ' end)||number,number into v_owner,v_ref,v_number from public.invoice_docs where id=p_id and org_id=p_org;
  elsif p_kind='po' then select user_id,'PO '||po_number into v_owner,v_ref from public.purchase_orders where id=p_id and org_id=p_org;
  elsif p_kind='order' then select user_id,'Order #'||id into v_owner,v_ref from public.orders where id=p_id and org_id=p_org;
  elsif p_kind<>'advance' then return false; end if;
  if exists(select 1 from public.transactions t left join public.accounts a on a.id=t.account_id
    where (case when p_kind='invoice' then t.invoice_id=p_id when p_kind='po' then t.po_id=p_id when p_kind='advance' then t.advance_id=p_id else false end)
      and (t.org_id is distinct from p_org or t.user_id is distinct from v_owner or a.org_id is distinct from p_org or a.user_id is distinct from v_owner))
    or exists(select 1 from public.stock_movements where workflow_kind=p_kind and workflow_id=p_id
      and (org_id is distinct from p_org or user_id is distinct from v_owner)) then return false; end if;
  if v_ref is not null then
    v_legacy:=exists(select 1 from public.transactions where org_id=p_org and invoice_id is null and po_id is null and ref=v_ref)
      or exists(select 1 from public.stock_movements where org_id=p_org and workflow_kind is null and ref=v_ref);
    if v_legacy and ((p_kind='invoice' and (select count(*) from public.invoice_docs where org_id=p_org and (case when doc_type='purchase' then 'Bill ' else 'Invoice ' end)||number=v_ref)>1)
      or (p_kind='po' and (select count(*) from public.purchase_orders where org_id=p_org and 'PO '||po_number=v_ref)>1)) then return false; end if;
    if exists(select 1 from public.transactions t left join public.accounts a on a.id=t.account_id
      where t.org_id=p_org and t.invoice_id is null and t.po_id is null and t.ref=v_ref
        and (t.user_id is distinct from v_owner or a.user_id is distinct from v_owner or a.org_id is distinct from p_org))
      or exists(select 1 from public.stock_movements where org_id=p_org and workflow_kind is null and ref=v_ref and user_id is distinct from v_owner) then return false; end if;
  end if;
  if p_kind='invoice' then
    if exists(select 1 from public.advances where org_id=p_org and note='applied:inv#'||p_id) and not public.filey_can_use('people') then return false; end if;
    if exists(select 1 from public.orders o where o.org_id=p_org and o.invoice_id is null and o.order_number='SO-'||v_number
      and not exists(select 1 from public.order_items where order_id=o.id) and o.user_id is distinct from v_owner) then return false; end if;
    if exists(select 1 from public.advances where note='applied:inv#'||p_id and (org_id is distinct from p_org or user_id is distinct from v_owner))
      or exists(select 1 from public.orders where invoice_id=p_id and (org_id is distinct from p_org or user_id is distinct from v_owner))
      or exists(select 1 from public.invoice_payments where invoice_id=p_id and (org_id is distinct from p_org or (not public.is_org_admin() and user_id is distinct from v_owner))) then return false; end if;
  elsif p_kind='po' and exists(select 1 from public.po_payments where po_id=p_id and (org_id is distinct from p_org or (not public.is_org_admin() and user_id is distinct from v_owner))) then return false; end if;
  return true;
end $$;
create or replace function public.filey_business_workflow(p_kind text,p_action text,p_payload jsonb,p_request uuid,p_actor uuid,p_org text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_doc jsonb; v_old jsonb; v_items jsonb:='[]'; v_old_items jsonb:='[]'; v_id bigint; v_payment bigint; v_payment_row jsonb;
  v_result jsonb; v_prior record; v_ids bigint[]; v_ref text; v_header jsonb; v_module text; v_paid numeric; v_total numeric;
begin
  if p_kind not in ('invoice','po') or p_action not in ('save','status','delete','receive','payment-add','payment-remove','advance')
    or p_request is null or jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>8388608 then
    raise exception 'Invalid document workflow request.' using errcode='22023'; end if;
  v_module:=case when p_kind='po' then 'purchase-orders' when p_payload->'header'->>'doc_type'='purchase' then 'purchase-invoices' else 'invoicing' end;
  perform public.filey_workflow_guard(p_actor,p_org,v_module);
  select * into v_prior from public.business_workflow_requests where user_id=p_actor and org_id=p_org and request_id=p_request;
  if found then
    if v_prior.action<>p_kind||':'||p_action or v_prior.payload<>p_payload then raise exception 'This request was already used for different changes.' using errcode='22023'; end if;
    return v_prior.result;
  end if;
  v_id:=nullif(p_payload->>'id','')::bigint;
  if p_action='payment-remove' then
    v_payment:=nullif(p_payload->>'payment_id','')::bigint;
    if p_kind='po' then select to_jsonb(p),po_id into v_payment_row,v_id from public.po_payments p where id=v_payment for update;
    else select to_jsonb(p),invoice_id into v_payment_row,v_id from public.invoice_payments p where id=v_payment for update; end if;
    if v_payment_row is null then raise exception 'Payment not found or access denied.' using errcode='42501'; end if;
  end if;
  if v_id is not null then
    if not public.filey_workflow_effects_owned(p_kind,v_id,p_org) then raise exception 'This document has inconsistent historic item or generated effect ownership. Reconcile it before changing the document.' using errcode='42501'; end if;
    if p_kind='po' then
      select to_jsonb(d) into v_old from public.purchase_orders d where id=v_id and org_id=p_org and (user_id=p_actor or public.is_org_admin()) for update;
      select coalesce(jsonb_agg(to_jsonb(i) order by position,id),'[]') into v_old_items from public.purchase_order_items i where po_id=v_id;
    else
      select to_jsonb(d) into v_old from public.invoice_docs d where id=v_id and org_id=p_org and (user_id=p_actor or public.is_org_admin()) for update;
      select coalesce(jsonb_agg(to_jsonb(i) order by position,id),'[]') into v_old_items from public.invoice_doc_items i where invoice_id=v_id;
    end if;
    if v_old is null then raise exception 'Document not found or write access denied.' using errcode='42501'; end if;
    perform public.filey_workflow_guard(p_actor,p_org,case when p_kind='po' then 'purchase-orders' when v_old->>'doc_type'='purchase' then 'purchase-invoices' else 'invoicing' end);
  elsif p_action<>'save' then raise exception 'Choose a saved document.' using errcode='22023'; end if;
  if p_action='save' then
    v_header:=p_payload->'header'; v_items:=p_payload->'items';
    if jsonb_typeof(v_header) is distinct from 'object' then raise exception 'Invalid document header.' using errcode='22023'; end if;
    if coalesce(v_header->>'status','draft') not in ('draft','sent','paid','overdue','cancelled','canceled','received','completed','ordered','pending') then raise exception 'Choose a valid document status.' using errcode='22023'; end if;
    if (case when p_kind='po' then v_header->>'status' in ('received','completed') else v_header->>'status' in ('sent','paid','overdue') end)
      and coalesce(btrim(v_header->>case when p_kind='po' then 'po_number' else 'number' end),'')='' then raise exception 'Enter a document number before posting.' using errcode='22023'; end if;
    if p_kind='invoice' and jsonb_typeof(v_header->'einvoice')='object' and nullif(v_header->'einvoice'->>'uuid','') is null then
      v_header:=jsonb_set(v_header,'{einvoice,uuid}',to_jsonb(gen_random_uuid()::text));
    end if;
    perform public.filey_workflow_totals(v_header,v_items,p_kind='po');
    if v_old is not null then
      -- Receipts continue to relieve the original amount/currency. Editing the
      -- settlement identity would strand them in a different control account.
      if (p_kind='invoice' and exists(select 1 from public.invoice_payments where invoice_id=v_id)) or
        (p_kind='po' and exists(select 1 from public.po_payments where po_id=v_id)) then
        if coalesce(v_header->>'currency','AED')<>coalesce(v_old->>'currency','AED') or v_header->'fx_rate' is distinct from v_old->'fx_rate'
          or coalesce(v_header->>'doc_type','sale')<>coalesce(v_old->>'doc_type','sale')
          or coalesce(v_header->>'status','draft') not in ('sent','paid','overdue','received','completed') then
          raise exception 'Remove the recorded payments before changing currency, document type or unposting.' using errcode='22023'; end if;
      end if;
      if p_kind='invoice' and v_old->>'status' in ('sent','paid','overdue') and
        (coalesce(v_header->>'invoice_type_code','') in ('381','81'))<>(coalesce(v_old->>'invoice_type_code','') in ('381','81')) then
        raise exception 'Create a separate credit note to correct a posted invoice.' using errcode='22023'; end if;
      if p_kind='invoice' and v_old->'einvoice'->>'uuid' is not null then
        v_header:=jsonb_set(v_header,'{einvoice}',coalesce(v_header->'einvoice','{}')||jsonb_build_object('uuid',v_old->'einvoice'->>'uuid'));
      end if;
      perform public.filey_workflow_unpost(p_kind,v_old,v_old_items);
    end if;
    if p_kind='po' then v_header:=v_header||jsonb_build_object('total',(public.filey_workflow_totals(v_header,v_items,true)->>'total')::numeric); end if;
    v_id:=public.filey_save_document(case when p_kind='po' then 'purchase_orders' else 'invoice_docs' end,v_header,v_items,v_id);
    if p_kind='po' then
      select to_jsonb(d) into v_doc from public.purchase_orders d where id=v_id;
      update public.purchase_order_items set user_id=(v_doc->>'user_id')::uuid where po_id=v_id;
      select coalesce(jsonb_agg(to_jsonb(i) order by position,id),'[]') into v_items from public.purchase_order_items i where po_id=v_id;
    else
      select to_jsonb(d) into v_doc from public.invoice_docs d where id=v_id;
      update public.invoice_doc_items set user_id=(v_doc->>'user_id')::uuid where invoice_id=v_id;
      select coalesce(jsonb_agg(to_jsonb(i) order by position,id),'[]') into v_items from public.invoice_doc_items i where invoice_id=v_id;
    end if;
    if (case when p_kind='po' then v_doc->>'status' in ('received','completed') else v_doc->>'status' in ('sent','paid','overdue') end) then
      perform public.filey_workflow_post(p_kind,v_doc,v_items,coalesce(p_payload->'rates','{}'));
    end if;
    if p_kind='invoice' then perform public.filey_workflow_advance(v_doc,nullif(v_doc->>'advance_applied','')::numeric,v_old); end if;
  elsif p_action in ('status','receive') then
    v_doc:=v_old||jsonb_build_object('status',case when p_action='receive' then 'received' else p_payload->>'status' end);
    if v_doc->>'status' not in ('draft','sent','paid','overdue','cancelled','canceled','received','completed','ordered','pending') then raise exception 'Choose a valid document status.' using errcode='22023'; end if;
    if (case when p_kind='po' then v_old->>'status' in ('received','completed') else v_old->>'status' in ('sent','paid','overdue') end)
      is distinct from (case when p_kind='po' then v_doc->>'status' in ('received','completed') else v_doc->>'status' in ('sent','paid','overdue') end) then
      if not (case when p_kind='po' then v_doc->>'status' in ('received','completed') else v_doc->>'status' in ('sent','paid','overdue') end)
        and ((p_kind='po' and exists(select 1 from public.po_payments where po_id=v_id)) or (p_kind='invoice' and exists(select 1 from public.invoice_payments where invoice_id=v_id))) then
        raise exception 'Remove the recorded payments before unposting this document.' using errcode='22023'; end if;
      perform public.filey_workflow_unpost(p_kind,v_old,v_old_items);
      if (case when p_kind='po' then v_doc->>'status' in ('received','completed') else v_doc->>'status' in ('sent','paid','overdue') end) then
        perform public.filey_workflow_post(p_kind,v_doc,v_old_items,coalesce(p_payload->'rates','{}'));
        if p_kind='invoice' then perform public.filey_workflow_advance(v_doc,nullif(v_doc->>'advance_applied','')::numeric,v_old); end if;
      end if;
    end if;
    if p_kind='invoice' and v_doc->>'status' in ('cancelled','canceled') then
      perform public.filey_workflow_advance(v_doc,0,v_old); v_doc:=v_doc||jsonb_build_object('advance_applied',0);
    end if;
    if p_kind='po' then update public.purchase_orders set status=v_doc->>'status',stock_received=(v_doc->>'status' in ('received','completed')) where id=v_id;
    else update public.invoice_docs set status=v_doc->>'status',advance_applied=coalesce((v_doc->>'advance_applied')::numeric,0) where id=v_id; end if;
  elsif p_action='delete' then
    perform public.filey_workflow_unpost(p_kind,v_old,v_old_items,true);
    if p_kind='po' then
      delete from public.po_payments where po_id=v_id; delete from public.purchase_order_items where po_id=v_id; delete from public.purchase_orders where id=v_id;
    else
      delete from public.advances where org_id=p_org and note='applied:inv#'||v_id;
      delete from public.invoice_payments where invoice_id=v_id; delete from public.invoice_doc_items where invoice_id=v_id; delete from public.invoice_docs where id=v_id;
    end if;
  elsif p_action='payment-add' then
    v_payment:=public.filey_workflow_payment(p_kind,v_old,(p_payload->>'amount')::numeric,p_payload->>'method',(p_payload->>'paid_at')::date,coalesce(p_payload->'rates','{}'));
  elsif p_action='payment-remove' then
    v_ref:=case when p_kind='po' then 'PO payment #' else 'Invoice payment #' end||v_payment;
    select array_agg(id) into v_ids from public.transactions where org_id=p_org and source='payment'
      and case when p_kind='po' then po_id=v_id else invoice_id=v_id end
      and (workflow_payment_id=v_payment or ref=v_ref);
    if v_ids is null and p_kind='invoice' and exists(select 1 from public.transactions where invoice_id=v_id and source='payment' and ref ~ ' Payment$') then
      -- Old receipts were not given an ID. Never guess which historical bundle
      -- to erase when it could change another receipt or a different currency.
      raise exception 'This historic payment needs ledger reconciliation before removal.' using errcode='22023';
    end if;
    perform public.filey_workflow_reverse(v_ids);
    if p_kind='po' then delete from public.po_payments where id=v_payment;
    else
      delete from public.invoice_payments where id=v_payment;
      select coalesce(sum(amount),0) into v_paid from public.invoice_payments where invoice_id=v_id;
      v_total:=(public.filey_workflow_totals(v_old,v_old_items)->>'total')::numeric;
      if v_old->>'status'='paid' and v_paid+coalesce((v_old->>'advance_applied')::numeric,0)<v_total-0.005 then update public.invoice_docs set status='sent' where id=v_id; end if;
    end if;
  elsif p_action='advance' then
    if p_kind<>'invoice' then raise exception 'Advance allocation requires a customer invoice.' using errcode='22023'; end if;
    if p_payload ? 'party_id' and nullif(p_payload->>'party_id','')::bigint is distinct from nullif(v_old->>'customer_id','')::bigint then raise exception 'The invoice customer changed. Reopen the invoice before allocating credit.' using errcode='22023'; end if;
    v_doc:=v_old||jsonb_build_object('advance_applied',(p_payload->>'amount')::numeric);
    perform public.filey_workflow_advance(v_doc,(p_payload->>'amount')::numeric,v_old);
    update public.invoice_docs set advance_applied=(p_payload->>'amount')::numeric where id=v_id;
  end if;
  v_result:=jsonb_build_object('id',v_id,'payment_id',v_payment);
  insert into public.business_workflow_requests(request_id,action,payload,result) values(p_request,p_kind||':'||p_action,p_payload,v_result);
  return v_result;
end $$;
alter function public.filey_business_workflow(text,text,jsonb,uuid,uuid,text) owner to filey_workflow_executor;

create or replace function public.filey_order_workflow(p_action text,p_payload jsonb,p_request uuid,p_actor uuid,p_org text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_id bigint:=nullif(p_payload->>'id','')::bigint; v_doc jsonb; v_header jsonb; v_items jsonb; v_item jsonb;
  v_prior record; v_result jsonb; v_old_qty record; v_new_qty record; v_total numeric:=0; v_status text; v_old_status text;
begin
  if p_action not in ('save','status','delete') or p_request is null or jsonb_typeof(p_payload) is distinct from 'object'
    or octet_length(p_payload::text)>8388608 then raise exception 'Invalid order workflow request.' using errcode='22023'; end if;
  perform public.filey_workflow_guard(p_actor,p_org,'orders');
  select * into v_prior from public.business_workflow_requests where user_id=p_actor and org_id=p_org and request_id=p_request;
  if found then
    if v_prior.action<>'order:'||p_action or v_prior.payload<>p_payload then raise exception 'This request was already used for different changes.' using errcode='22023'; end if;
    return v_prior.result;
  end if;
  if v_id is not null then
    if not public.filey_workflow_effects_owned('order',v_id,p_org) then raise exception 'This order has inconsistent historic item ownership. Reconcile it before changing the order.' using errcode='42501'; end if;
    select to_jsonb(o) into v_doc from public.orders o where id=v_id and org_id=p_org and (user_id=p_actor or public.is_org_admin()) for update;
    if v_doc is null then raise exception 'Order not found or write access denied.' using errcode='42501'; end if;
    if nullif(v_doc->>'invoice_id','') is not null then raise exception 'Change the linked invoice to update this generated order.' using errcode='22023'; end if;
  elsif p_action<>'save' then raise exception 'Choose a saved order.' using errcode='22023'; end if;
  v_header:=coalesce(p_payload->'header','{}');
  v_old_status:=coalesce(v_doc->>'status','draft');
  v_status:=case when p_action='delete' then 'cancelled' when p_action='status' then p_payload->>'status' else coalesce(v_header->>'status',v_old_status) end;
  if v_status not in ('draft','pending','processing','completed','cancelled','canceled','shipped','delivered','confirmed') then raise exception 'Choose a valid order status.' using errcode='22023'; end if;
  if p_action='save' then
    v_items:=p_payload->'items';
    if jsonb_typeof(v_items) is distinct from 'array' or jsonb_array_length(v_items)>500 then raise exception 'An order supports at most 500 valid item rows.' using errcode='22023'; end if;
    for v_item in select value from jsonb_array_elements(v_items) loop
      if nullif(v_item->>'product_id','')::bigint is null or public.filey_workflow_number(v_item->>'quantity')<0 or public.filey_workflow_number(v_item->>'unit_price')<0 then raise exception 'Choose valid order products, quantities and prices.' using errcode='22023'; end if;
      v_total:=v_total+public.filey_workflow_round(public.filey_workflow_number(v_item->>'quantity')*public.filey_workflow_number(v_item->>'unit_price'));
    end loop;
    if jsonb_array_length(v_items)=0 then v_total:=coalesce(nullif(v_header->>'total','')::numeric,0); end if;
    if v_total::text in ('NaN','Infinity','-Infinity') or v_total<0 or v_total>=1000000000000 then raise exception 'Enter a valid order total.' using errcode='22023'; end if;
    if nullif(v_header->>'customer_id','') is not null and not exists(select 1 from public.crm_customers where id=(v_header->>'customer_id')::bigint and org_id=p_org) then raise exception 'Customer not found or access denied.' using errcode='42501'; end if;
    if v_id is null then
      insert into public.orders(order_number,customer_name,customer_id,status,total)
        values(coalesce(v_header->>'order_number',''),coalesce(v_header->>'customer_name',''),nullif(v_header->>'customer_id','')::bigint,v_status,v_total) returning id into v_id;
    end if;
  else select coalesce(jsonb_agg(to_jsonb(i) order by id),'[]') into v_items from public.order_items i where order_id=v_id; end if;
  -- Apply only the difference between the current journal footprint and the
  -- desired reservation. Reopening a cancelled historic order uses its actual
  -- movement history, and an unchanged status creates no movement noise.
  for v_old_qty in select product_id from public.order_items where order_id=v_id union
    select nullif(value->>'product_id','')::bigint from jsonb_array_elements(v_items) union
    select product_id from public.stock_movements where org_id=p_org and ((workflow_kind='order' and workflow_id=v_id) or (workflow_kind is null and ref='Order #'||v_id)) loop
    select coalesce(sum(qty),0) qty,count(*) n into v_new_qty from public.stock_movements where org_id=p_org and product_id=v_old_qty.product_id
      and ((workflow_kind='order' and workflow_id=v_id) or (workflow_kind is null and ref='Order #'||v_id));
    if v_new_qty.n=0 and v_doc is not null and v_old_status not in ('cancelled','canceled') then
      select -coalesce(sum(quantity),0),0 into v_new_qty from public.order_items where order_id=v_id and product_id=v_old_qty.product_id;
    end if;
    if v_status not in ('cancelled','canceled') then select coalesce(sum(public.filey_workflow_number(value->>'quantity')),0) into v_total
      from jsonb_array_elements(v_items) where nullif(value->>'product_id','')::bigint=v_old_qty.product_id;
    else v_total:=0; end if;
    perform public.filey_workflow_stock(v_old_qty.product_id,-v_new_qty.qty-v_total,'order',v_id,'Order #'||v_id);
  end loop;
  v_total:=case when jsonb_array_length(v_items)=0 then coalesce(nullif(v_header->>'total','')::numeric,0) else
    (select coalesce(sum(public.filey_workflow_round(public.filey_workflow_number(value->>'quantity')*public.filey_workflow_number(value->>'unit_price'))),0) from jsonb_array_elements(v_items)) end;
  if p_action='delete' then delete from public.order_items where order_id=v_id; delete from public.orders where id=v_id;
  elsif p_action='status' then update public.orders set status=v_status where id=v_id;
  else
    update public.orders set customer_name=coalesce(v_header->>'customer_name',customer_name),
      customer_id=case when v_header ? 'customer_id' then nullif(v_header->>'customer_id','')::bigint else customer_id end,
      status=v_status,total=v_total where id=v_id;
    delete from public.order_items where order_id=v_id;
    for v_item in select value from jsonb_array_elements(v_items) loop
      insert into public.order_items(order_id,product_id,quantity,unit_price,user_id)
        values(v_id,(v_item->>'product_id')::bigint,(v_item->>'quantity')::numeric,(v_item->>'unit_price')::numeric,coalesce((v_doc->>'user_id')::uuid,p_actor));
    end loop;
  end if;
  v_result:=jsonb_build_object('id',v_id);
  insert into public.business_workflow_requests(request_id,action,payload,result) values(p_request,'order:'||p_action,p_payload,v_result);
  return v_result;
end $$;
alter function public.filey_order_workflow(text,jsonb,uuid,uuid,text) owner to filey_workflow_executor;

create or replace function public.filey_advance_workflow(p_action text,p_payload jsonb,p_request uuid,p_actor uuid,p_org text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_id bigint:=nullif(p_payload->>'id','')::bigint; v_old public.advances; v_header jsonb:=coalesce(p_payload->'header','{}');
  v_row public.advances; v_prior record; v_result jsonb; v_available numeric; v_ids bigint[]; v_account bigint; v_cash bigint; v_entry bigint;
begin
  if p_action not in ('add','update','delete') or p_request is null or jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>32768 then raise exception 'Invalid advance request.' using errcode='22023'; end if;
  perform public.filey_workflow_guard(p_actor,p_org,'invoicing');
  perform public.filey_workflow_guard(p_actor,p_org,'accounting');
  select * into v_prior from public.business_workflow_requests where user_id=p_actor and org_id=p_org and request_id=p_request;
  if found then if v_prior.action<>'advance:'||p_action or v_prior.payload<>p_payload then raise exception 'This request was already used for different changes.' using errcode='22023'; end if; return v_prior.result; end if;
  if p_action<>'add' then
    if not public.filey_workflow_effects_owned('advance',v_id,p_org) then raise exception 'This advance has inconsistent historic posting ownership. Reconcile it before changing the advance.' using errcode='42501'; end if;
    select * into v_old from public.advances where id=v_id and org_id=p_org and (user_id=p_actor or public.is_org_admin()) for update;
    if not found then raise exception 'Advance not found or write access denied.' using errcode='42501'; end if;
    if v_old.amount<0 or v_old.note like 'applied:inv#%' then raise exception 'Change the linked invoice to update an applied advance.' using errcode='22023'; end if;
    v_header:=to_jsonb(v_old)||v_header;
  end if;
  v_row:=jsonb_populate_record(null::public.advances,v_header);
  v_row.user_id:=coalesce(v_old.user_id,p_actor);
  if v_row.party_type not in ('customer','supplier') or v_row.party_id is null or v_row.amount is null or v_row.amount::text in ('NaN','Infinity','-Infinity')
    or v_row.amount<=0 or v_row.amount>=1000000000000 or v_row.amount<>round(v_row.amount,2) or coalesce(v_row.note,'') like 'applied:%'
    or v_row.paid_at is null then raise exception 'Choose a party, a positive advance amount and valid date.' using errcode='22023'; end if;
  if (v_row.party_type='customer' and not exists(select 1 from public.crm_customers where id=v_row.party_id and org_id=p_org))
    or (v_row.party_type='supplier' and not exists(select 1 from public.suppliers where id=v_row.party_id and org_id=p_org)) then raise exception 'Party not found or access denied.' using errcode='42501'; end if;
  if p_action<>'add' then
    if v_old.amount>(case when p_action='delete' then 0 else v_row.amount end) and
      not public.filey_workflow_credit_available(v_old.party_type,v_old.party_id,v_old.user_id,null,v_old.amount-(case when p_action='delete' then 0 else v_row.amount end)) then raise exception 'This advance is already allocated. Release the invoice allocation before reducing it.' using errcode='22023'; end if;
    select array_agg(id) into v_ids from public.transactions where advance_id=v_id;
    perform public.filey_workflow_reverse(v_ids);
  end if;
  if p_action='delete' then delete from public.advances where id=v_id;
  else
    if p_action='add' then
      insert into public.advances(party_type,party_id,party_name,amount,note,paid_at,accounting_posted)
        values(v_row.party_type,v_row.party_id,coalesce(v_row.party_name,''),v_row.amount,v_row.note,v_row.paid_at,true) returning id into v_id;
      v_row.accounting_posted:=true;
    else
      update public.advances set amount=v_row.amount,note=v_row.note,paid_at=v_row.paid_at where id=v_id;
      v_row.accounting_posted:=v_old.accounting_posted;
    end if;
    if v_row.accounting_posted then
      v_account:=case when v_row.party_type='customer' then public.filey_workflow_account_for_owner('liability','2200','Customer Advances','customer advances|customer deposits',v_row.user_id)
        else public.filey_workflow_account_for_owner('asset','1260','Supplier Advances','supplier advances|supplier prepayments',v_row.user_id) end;
      v_cash:=public.filey_workflow_account_for_owner('asset','1000','Cash & Bank','cash|bank',v_row.user_id);
      v_entry:=public.filey_workflow_entry(v_cash,case when v_row.party_type='customer' then 'debit' else 'credit' end,v_row.amount,'Advance #'||v_id,'Advance #'||v_id,'advance',v_row.paid_at);
      update public.transactions set advance_id=v_id where id=v_entry;
      v_entry:=public.filey_workflow_entry(v_account,case when v_row.party_type='customer' then 'credit' else 'debit' end,v_row.amount,'Advance #'||v_id,'Advance #'||v_id,'advance',v_row.paid_at);
      update public.transactions set advance_id=v_id where id=v_entry;
    end if;
  end if;
  v_result:=jsonb_build_object('id',v_id);
  insert into public.business_workflow_requests(request_id,action,payload,result) values(p_request,'advance:'||p_action,p_payload,v_result);
  return v_result;
end $$;
alter function public.filey_advance_workflow(text,jsonb,uuid,uuid,text) owner to filey_workflow_executor;

create or replace function public.filey_journal_workflow(p_action text,p_payload jsonb,p_request uuid,p_actor uuid,p_org text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_id bigint:=nullif(p_payload->>'id','')::bigint; v_prior record; v_result jsonb; v_row public.transactions; v_account public.accounts; v_ids bigint[]; v_removed bigint:=0;
begin
  if p_action not in ('post','delete','repair','account-delete','account-update') or p_request is null or jsonb_typeof(p_payload) is distinct from 'object'
    or octet_length(p_payload::text)>32768 then raise exception 'Invalid accounting request.' using errcode='22023'; end if;
  perform public.filey_workflow_guard(p_actor,p_org,'accounting');
  select * into v_prior from public.business_workflow_requests where user_id=p_actor and org_id=p_org and request_id=p_request;
  if found then if v_prior.action<>'journal:'||p_action or v_prior.payload<>p_payload then raise exception 'This request was already used for different changes.' using errcode='22023'; end if; return v_prior.result; end if;
  if p_action='post' then
    v_id:=public.filey_workflow_entry((p_payload->>'account_id')::bigint,p_payload->>'txn_type',(p_payload->>'amount')::numeric,p_payload->>'description',null,null,(p_payload->>'txn_date')::date);
    if v_id is null then raise exception 'Enter a positive journal amount.' using errcode='22023'; end if;
  elsif p_action='delete' then
    select * into v_row from public.transactions where id=v_id and org_id=p_org and (user_id=p_actor or public.is_org_admin()) for update;
    if not found then raise exception 'Journal entry not found or write access denied.' using errcode='42501'; end if;
    if v_row.invoice_id is not null or v_row.po_id is not null or v_row.advance_id is not null or nullif(v_row.source,'') is not null or nullif(v_row.ref,'') is not null then
      raise exception 'Change the source document or payment to reverse these linked postings together.' using errcode='22023'; end if;
    perform public.filey_workflow_reverse(array[v_id]);
  elsif p_action in ('account-delete','account-update') then
    select * into v_account from public.accounts where id=v_id and org_id=p_org and (user_id=p_actor or public.is_org_admin()) for update;
    if not found then raise exception 'Account not found or write access denied.' using errcode='42501'; end if;
    if p_action='account-delete' then
      if v_account.balance<>0 or exists(select 1 from public.transactions where account_id=v_id) or exists(select 1 from public.expenses where account_id=v_id) then
        raise exception 'An account with a balance or activity must be retained for the audit trail.' using errcode='22023'; end if;
      delete from public.accounts where id=v_id;
    else
      if (p_payload->'header' ? 'account_type' and p_payload->'header'->>'account_type' not in ('asset','liability','equity','revenue','expense'))
        or (p_payload->'header' ? 'balance' and ((p_payload->'header'->>'balance')::numeric::text in ('NaN','Infinity','-Infinity') or abs((p_payload->'header'->>'balance')::numeric)>=1000000000000)) then raise exception 'Enter a valid account type and finite balance.' using errcode='22023'; end if;
      if exists(select 1 from public.transactions where account_id=v_id) and
        (coalesce(p_payload->'header'->>'account_type',v_account.account_type)<>v_account.account_type or coalesce((p_payload->'header'->>'balance')::numeric,v_account.balance)<>v_account.balance) then
        raise exception 'An active account type and balance are maintained by its journal. Record an adjustment instead.' using errcode='22023'; end if;
      update public.accounts set code=coalesce(p_payload->'header'->>'code',code),name=coalesce(p_payload->'header'->>'name',name),
        account_type=coalesce(p_payload->'header'->>'account_type',account_type),balance=coalesce((p_payload->'header'->>'balance')::numeric,balance) where id=v_id;
    end if;
  elsif p_action='repair' then
    -- Equal manual entries can both be real. Only remove duplicates with the
    -- same immutable source identity, reference, account, side, value and date.
    select array_agg(id) into v_ids from (
      select id,row_number() over(partition by user_id,invoice_id,po_id,advance_id,workflow_payment_id,ref,source,account_id,txn_type,amount,description,txn_date order by id) n
      from public.transactions where org_id=p_org and (user_id=p_actor or public.is_org_admin()) and nullif(ref,'') is not null and nullif(source,'') is not null
        and (invoice_id is not null or po_id is not null or advance_id is not null or workflow_payment_id is not null)
        and (source<>'payment' or workflow_payment_id is not null)
    ) candidates where n>1;
    v_removed:=coalesce(cardinality(v_ids),0); perform public.filey_workflow_reverse(v_ids); v_id:=1;
  end if;
  v_result:=jsonb_build_object('id',v_id,'removed',v_removed);
  insert into public.business_workflow_requests(request_id,action,payload,result) values(p_request,'journal:'||p_action,p_payload,v_result);
  return v_result;
end $$;
alter function public.filey_journal_workflow(text,jsonb,uuid,uuid,text) owner to filey_workflow_executor;

create or replace function public.filey_stock_workflow(p_action text,p_payload jsonb,p_request uuid,p_actor uuid,p_org text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_id bigint:=(p_payload->>'id')::bigint; v_delta numeric:=(p_payload->>'delta')::numeric; v_prior record; v_result jsonb; v_qty numeric; v_changed bigint; v_owner uuid;
begin
  if p_action<>'adjust' or p_request is null or jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>32768
    or v_delta is null or v_delta::text in ('NaN','Infinity','-Infinity') or abs(v_delta)>=100000000000 or v_delta<>round(v_delta,3)
    or p_payload->>'type' not in ('in','out','adjust') then raise exception 'Enter a valid stock adjustment with at most three decimals.' using errcode='22023'; end if;
  perform public.filey_workflow_guard(p_actor,p_org,'inventory');
  select * into v_prior from public.business_workflow_requests where user_id=p_actor and org_id=p_org and request_id=p_request;
  if found then if v_prior.action<>'stock:adjust' or v_prior.payload<>p_payload then raise exception 'This request was already used for different changes.' using errcode='22023'; end if; return v_prior.result; end if;
  select quantity,user_id into v_qty,v_owner from public.products where id=v_id and org_id=p_org and (user_id=p_actor or public.is_org_admin()) for update;
  if not found then raise exception 'Product not found or stock update denied.' using errcode='42501'; end if;
  update public.products set quantity=quantity+v_delta where id=v_id returning id into v_changed;
  if v_changed is null then raise exception 'Stock update denied.' using errcode='42501'; end if;
  if v_delta<>0 then insert into public.stock_movements(product_id,qty,type,ref,note,moved_at,workflow_kind,workflow_id,user_id)
    values(v_id,v_delta,p_payload->>'type',p_payload->>'ref',p_payload->>'note',coalesce(nullif(p_payload->>'date','')::date::timestamptz,now()),'manual',v_id,v_owner); end if;
  v_result:=jsonb_build_object('id',v_id);
  insert into public.business_workflow_requests(request_id,action,payload,result) values(p_request,'stock:adjust',p_payload,v_result);
  return v_result;
end $$;
alter function public.filey_stock_workflow(text,jsonb,uuid,uuid,text) owner to filey_workflow_executor;

-- Internal writes are callable only from the trusted dispatcher, retaining
-- ordinary RLS there. Clients cannot bypass the receipt/atomic entry point.
-- Pure calculators and bounded permission-scoped booleans remain public RPCs
-- for authenticated clients; anonymous callers have no workflow.
do $$ declare v record; begin
  for v in select proname,oid::regprocedure signature from pg_proc where pronamespace='public'::regnamespace and
    (proname like 'filey_workflow_%' or proname in ('filey_business_workflow','filey_order_workflow','filey_journal_workflow','filey_advance_workflow','filey_stock_workflow')) loop
    execute format('revoke all on function %s from public,anon',v.signature);
    if v.proname like 'filey_workflow_%' and v.proname not in ('filey_workflow_round','filey_workflow_number','filey_workflow_totals','filey_workflow_fx',
      'filey_workflow_children_owned','filey_workflow_effects_owned','filey_workflow_credit_available','filey_workflow_receipt_reversible') then
      execute format('revoke all on function %s from authenticated,service_role',v.signature);
      execute format('grant execute on function %s to filey_workflow_executor',v.signature);
    else
      execute format('grant execute on function %s to authenticated',v.signature);
    end if;
  end loop;
end $$;
revoke create on schema public from filey_workflow_executor;
do $$ begin
  if has_schema_privilege('filey_workflow_executor','public','CREATE') then
    raise exception 'The workflow executor inherits public schema CREATE. Correct the schema grants before installing this workflow.';
  end if;
end $$;
notify pgrst,'reload schema';

-- Source: supabase/2026-10-04-atomic-recurrence.sql
-- One locked recurring cycle creates a draft and advances its schedule once.

-- A boolean integrity gate must see legacy malformed children hidden by RLS.
-- It exposes no child content and checks ownership/module authority itself.
create or replace function public.filey_recurring_items_owned(p_id bigint,p_org text)
returns boolean language plpgsql security definer set search_path=public,pg_temp as $$
declare b public.invoice_docs;
begin
  if auth.uid() is null or public.current_org() is distinct from p_org or not public.filey_is_workspace_member(p_org) then raise exception 'Invoice unavailable' using errcode='42501'; end if;
  select * into b from public.invoice_docs where id=p_id and org_id=p_org and (user_id=auth.uid() or public.is_org_admin());
  if not found or not public.filey_can_use(case when b.doc_type='purchase' then 'purchase-invoices' else 'invoicing' end) then raise exception 'Invoice unavailable' using errcode='42501'; end if;
  return not exists(select 1 from public.invoice_doc_items where invoice_id=p_id and org_id is distinct from p_org);
end $$;
revoke all on function public.filey_recurring_items_owned(bigint,text) from public,anon;
grant execute on function public.filey_recurring_items_owned(bigint,text) to authenticated;
create or replace function public.filey_generate_recurring_invoice(p_id bigint,p_expected date,p_today date,p_next date,p_actor uuid,p_org text)
returns boolean language plpgsql security invoker set search_path=public,pg_temp as $$
declare r public.invoice_recurrence; b public.invoice_docs; header jsonb; lines jsonb; next_date date; number text; pattern text; kind text; steps int:=0;
begin
  if auth.uid() is null or auth.uid() is distinct from p_actor or public.current_org() is distinct from p_org or not public.filey_is_workspace_member(p_org) then
    raise exception 'Your account or workspace changed. Reopen recurring invoices.' using errcode='42501';
  end if;
  select * into r from public.invoice_recurrence where id=p_id for update;
  if not found or r.org_id is distinct from p_org or (r.user_id is distinct from p_actor and not public.is_org_admin()) then
    raise exception 'Recurring invoice unavailable or edit access denied' using errcode='42501';
  end if;
  if not r.active or r.next_run is distinct from p_expected then return false; end if;
  if p_expected is null or p_today is null or p_next is null or p_today<>(now() at time zone 'UTC')::date or p_expected>p_today or p_next<=p_today or r.interval not in ('weekly','monthly','yearly') then
    raise exception 'The recurring invoice schedule is invalid. Review its dates.' using errcode='22023';
  end if;
  select * into b from public.invoice_docs where id=r.base_invoice_id for update;
  if not found or b.org_id is distinct from p_org or (b.user_id is distinct from p_actor and not public.is_org_admin()) then
    raise exception 'Base invoice unavailable or edit access denied' using errcode='42501';
  end if;
  kind:=case when b.doc_type='purchase' then 'purchase_invoice' else 'invoice' end;
  if not public.filey_can_use(case when kind='invoice' then 'invoicing' else 'purchase-invoices' end) then raise exception 'Invoice module access is required' using errcode='42501'; end if;
  next_date:=r.next_run;
  loop
    next_date:=(next_date+case r.interval when 'weekly' then interval '7 days' when 'monthly' then interval '1 month' else interval '1 year' end)::date;
    steps:=steps+1;
    if steps>10000 then raise exception 'The recurring schedule is outside the supported date range'; end if;
    exit when next_date>p_today;
  end loop;
  if next_date<>p_next then raise exception 'The recurring schedule changed. Refresh and retry.' using errcode='40001'; end if;
  select value into pattern from public.app_settings where org_id=p_org and user_id=p_actor and key=case kind when 'invoice' then 'invoice_number_format' else 'purchase_invoice_number_format' end order by id limit 1;
  if pattern is null or pattern !~ '\{[0-9]+\}' then pattern:=case kind when 'invoice' then 'INV' else 'PINV' end||'-{YYYY}-{0001}'; end if;
  number:=public.filey_reserve_document_number(kind,pattern,extract(year from p_today)::int,gen_random_uuid(),p_actor,p_org);
  header:=to_jsonb(b)-array['id','user_id','org_id','created_at','updated_at','sync_revision','shared','shared_with','share_token','due_date','quotation_id','order_id'];
  header:=header||jsonb_build_object('number',number,'status','draft','issue_date',p_today,'advance_applied',0);
  if jsonb_typeof(header->'einvoice')='object' then header:=jsonb_set(header,'{einvoice}',(header->'einvoice')||jsonb_build_object('uuid',gen_random_uuid())); end if;
  select coalesce(jsonb_agg(to_jsonb(i)-array['id','user_id','org_id','created_at','updated_at','sync_revision','shared','shared_with'] order by position,id),'[]'::jsonb) into lines from public.invoice_doc_items i where invoice_id=b.id and org_id=p_org;
  if not public.filey_recurring_items_owned(b.id,p_org) then raise exception 'Review the base invoice item ownership'; end if;
  perform public.filey_save_document('invoice_docs',header,lines);
  update public.invoice_recurrence set next_run=next_date,last_run=p_today where id=r.id;
  if not found then raise exception 'Recurring schedule update denied' using errcode='42501'; end if;
  return true;
end $$;
revoke all on function public.filey_generate_recurring_invoice(bigint,date,date,date,uuid,text) from public,anon;
grant execute on function public.filey_generate_recurring_invoice(bigint,date,date,date,uuid,text) to authenticated;
notify pgrst,'reload schema';

-- Source: supabase/2026-10-04-stripe-invoice-total-parity.sql
-- Legacy, already-created Stripe invoice checkouts use current document totals.
-- No new public checkout, ledger backfill or historical receipt rewrite.

do $$ begin
  if to_regprocedure('public.filey_workflow_totals(jsonb,jsonb,boolean)') is null then
    raise exception 'Apply 2026-10-04-atomic-business-workflows.sql before Stripe total parity.';
  end if;
end $$;
create or replace function public.filey_settle_stripe_checkout(
  p_session text,p_kind text,p_user uuid,p_invoice bigint,
  p_amount numeric,p_currency text,p_intent text
) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare doc public.invoice_docs%rowtype; existing public.stripe_settled_checkouts%rowtype;
  buyer uuid; items jsonb; total numeric; paid numeric;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Service-role settlement required' using errcode='42501';
  end if;
  if p_session is null or p_session !~ '^cs_[A-Za-z0-9_]+$' or length(p_session)>255
    or p_intent is null or p_intent !~ '^pi_[A-Za-z0-9_]+$' or length(p_intent)>255
    or p_currency is null or p_currency !~ '^[A-Z]{3}$'
    or p_amount is null or p_amount::text in ('NaN','Infinity','-Infinity') or p_amount<=0 or p_amount>999999999999.99
    or round(p_amount,2)<>p_amount or p_kind is null or p_kind not in ('invoice_payment','lite_license') then
    raise exception 'Invalid Stripe settlement';
  end if;
  if p_kind='invoice_payment' then
    if p_user is not null or p_invoice is null then raise exception 'Invalid invoice settlement'; end if;
    select * into doc from invoice_docs where id=p_invoice for update;
    if not found or upper(coalesce(doc.currency,''))<>p_currency then raise exception 'Invoice currency or reference mismatch'; end if;
    buyer:=doc.user_id;
  else
    if p_user is null or p_invoice is not null then raise exception 'Invalid license settlement'; end if;
    buyer:=p_user;
  end if;
  insert into stripe_settled_checkouts(session_id,payment_intent,kind,user_id,invoice_id,amount,currency)
    values(p_session,p_intent,p_kind,buyer,p_invoice,p_amount,p_currency)
    on conflict do nothing;
  if not found then
    select * into existing from stripe_settled_checkouts where session_id=p_session;
    if not found or existing.payment_intent<>p_intent or existing.kind<>p_kind or existing.user_id<>buyer
      or existing.invoice_id is distinct from p_invoice or existing.amount<>p_amount or existing.currency<>p_currency then
      raise exception 'Stripe settlement replay mismatch';
    end if;
    return jsonb_build_object('received',true,'duplicate',true);
  end if;
  if p_kind='lite_license' then
    if not exists(select 1 from licenses where stripe_payment_intent=p_intent) then
      insert into licenses(user_id,product,status,stripe_payment_intent)
        values(buyer,'filey-desktop','active',p_intent);
    end if;
  else
    -- Service-role reads can see malformed legacy children that ordinary RLS
    -- hides. Refuse partial totals; preserve the original records for repair.
    if exists(select 1 from invoice_doc_items where invoice_id=doc.id and org_id is distinct from doc.org_id) then
      raise exception 'Invoice lines require workspace reconciliation.' using errcode='22023';
    end if;
    select coalesce(jsonb_agg(to_jsonb(i) order by position,id),'[]'::jsonb)
      into items from invoice_doc_items i where invoice_id=doc.id and org_id=doc.org_id;
    total:=(public.filey_workflow_totals(to_jsonb(doc),items,false)->>'total')::numeric;
    if doc.advance_applied<0 or doc.advance_applied>total then
      raise exception 'Invoice advance requires reconciliation.' using errcode='22023';
    end if;
    insert into invoice_payments(invoice_id,user_id,org_id,amount,method,paid_at)
      values(doc.id,doc.user_id,doc.org_id,p_amount,'card',now());
    select coalesce(sum(amount),0)+coalesce(doc.advance_applied,0) into paid
      from invoice_payments where invoice_id=doc.id and org_id=doc.org_id;
    if paid>=total and doc.status in ('sent','overdue') then
      update invoice_docs set status='paid',updated_at=now() where id=doc.id;
    end if;
  end if;
  return jsonb_build_object('received',true,'duplicate',false);
end;
$$;
revoke all on function public.filey_settle_stripe_checkout(text,text,uuid,bigint,numeric,text,text) from public,anon,authenticated;
grant execute on function public.filey_settle_stripe_checkout(text,text,uuid,bigint,numeric,text,text) to service_role;
notify pgrst,'reload schema';

-- Source: supabase/2026-10-04-cloud-storage-privacy.sql
-- Repeatable privacy boundary for hosted files and service-only retention.
-- Apply after the storage buckets/tool_runs features. No object or user data
-- is deleted and existing size/MIME restrictions are preserved.

-- Public downloads bypass object SELECT RLS. Earlier bucket creation used
-- ON CONFLICT DO NOTHING, which retained a previously public bucket.
update storage.buckets set public=false
where id in ('files','tool-inputs','tool-outputs','team-attachments')
  and public is distinct from false;

-- Managed default grants include authenticated EXECUTE. This definer routine
-- deliberately deletes across owners; only the scheduled/service job may call
-- it. Revoking PUBLIC alone does not remove those explicit client grants.
create or replace function public.prune_tool_runs(max_age interval default '30 days')
returns void language plpgsql security definer
set search_path=public,storage as $$
begin
  delete from storage.objects o using public.tool_runs r
    where o.bucket_id='tool-outputs' and o.name=any(r.storage_paths)
      -- A run's paths are client supplied. A forged old run must never make
      -- the service-role cleanup delete another user's stored output.
      and public.filey_tool_path_owned(o.name,r.user_id)
      and r.created_at<now()-max_age;
  delete from public.tool_runs where created_at<now()-max_age;
end $$;
revoke execute on function public.prune_tool_runs(interval)
  from public,anon,authenticated;
grant execute on function public.prune_tool_runs(interval) to service_role;

-- Source: supabase/2026-10-04-scheduled-agent-privacy.sql
-- A scheduled service-role job must retain its original workspace authority
-- before publishing private data. One statement checks both active workspace
-- and membership; this helper grants no authority to client roles.

create or replace function public.filey_agent_workspace_allowed(p_owner uuid,p_org text)
returns boolean language sql stable security invoker
set search_path=public,pg_temp as $$
  select exists(select 1 from public.profiles p
    join public.org_members m on m.org_id=p.org_id and m.user_id=p.id
    where p.id=p_owner and p.org_id=p_org and m.role in ('owner','admin'))
$$;
revoke all on function public.filey_agent_workspace_allowed(uuid,text)
  from public,anon,authenticated;
grant execute on function public.filey_agent_workspace_allowed(uuid,text) to service_role;
notify pgrst,'reload schema';

-- Source: supabase/2026-10-04-ai-credit-test-promotion.sql
-- One explicitly authorized, selected-account test checkout. No public coupon
-- input or synthetic cash receipt can authorize a zero-paid Coin grant.

alter table public.ai_credit_orders
  add column if not exists promotion_id uuid,
  add column if not exists promotion_discount_id text,
  add column if not exists promotion_discount_code text,
  add column if not exists promotion_customer_id text,
  add column if not exists promotion_email text,
  add column if not exists promotion_expires_at timestamptz,
  add column if not exists expected_paid_cents bigint,
  add column if not exists checkout_session_id text;
do $$ begin
  if not exists(select 1 from pg_constraint where conrelid='public.ai_credit_orders'::regclass and conname='ai_credit_promotion_binding') then
    alter table public.ai_credit_orders add constraint ai_credit_promotion_binding check (
      (promotion_id is null and promotion_discount_id is null and promotion_discount_code is null
        and promotion_customer_id is null and promotion_email is null and promotion_expires_at is null and expected_paid_cents is null)
      or (promotion_id is not null and promotion_discount_id is not null and promotion_discount_code is not null
        and promotion_customer_id is not null and promotion_email is not null and promotion_expires_at is not null
        and expected_paid_cents is not null and expected_paid_cents=0 and credits_micros=5000000 and service_fee_cents=50
        and length(promotion_discount_id) between 2 and 200 and promotion_discount_id !~ '[^A-Za-z0-9_-]'
        and length(promotion_customer_id) between 2 and 200 and promotion_customer_id !~ '[^A-Za-z0-9_-]'
        and length(promotion_discount_code) between 3 and 16 and promotion_discount_code !~ '[^A-Z0-9_-]'
        and length(promotion_email) between 3 and 254 and position('@' in promotion_email)>1
        and promotion_email !~ '[[:space:]]' and isfinite(promotion_expires_at)));
  end if;
end $$;
-- Insertion reserves this one-use offer, including concurrent/opened sessions.
create unique index if not exists ai_credit_promotion_once on public.ai_credit_orders(promotion_id) where promotion_id is not null;
create unique index if not exists ai_credit_promotion_discount_once on public.ai_credit_orders(promotion_discount_id) where promotion_id is not null;
revoke all on public.ai_credit_orders from public, anon, authenticated;
grant all on public.ai_credit_orders to service_role;

create or replace function public.filey_ai_wallet(p_action text, p_user uuid, p_args jsonb default '{}')
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  a public.ai_credit_accounts%rowtype;
  r public.ai_credit_requests%rowtype;
  o public.ai_credit_orders%rowtype;
  amount bigint; released bigint;
  event_id text; request_id uuid; task_id uuid;
  dispute_at timestamptz;
  payment_at timestamptz;
  payment_args jsonb; payment_refund jsonb;
begin
  if p_user is null then raise exception 'Account required'; end if;
  insert into ai_credit_accounts(user_id) values(p_user) on conflict do nothing;
  select * into strict a from ai_credit_accounts where user_id = p_user for update;

  if p_action='reconcile_payment' then
    if jsonb_typeof(p_args->'refunds') is distinct from 'array'
      or coalesce(p_args->>'dispute_action','') not in ('','dispute','resolve_dispute') then
      raise exception 'Invalid payment reconciliation';
    end if;
    payment_args := jsonb_build_object('order_id',p_args->'order_id',
      'event_type',p_args->'event_type','event_at',p_args->'event_at');
    -- Nested calls share this transaction and reentrant account lock. Return
    -- before the outer expiry CTE so only the nested calls update hold expiry.
    if p_args->>'dispute_action'='dispute' then
      perform public.filey_ai_wallet('dispute',p_user,payment_args);
    end if;
    perform public.filey_ai_wallet('topup',p_user,jsonb_build_object(
      'order_id',p_args->'order_id','payment_id',p_args->'payment_id','paid_cents',p_args->'paid_cents',
      'payment_event_type',p_args->'event_type','payment_event_at',p_args->'event_at'));
    for payment_refund in select value from jsonb_array_elements(p_args->'refunds') loop
      if jsonb_typeof(payment_refund) is distinct from 'object' then
        raise exception 'Invalid payment refund';
      end if;
      perform public.filey_ai_wallet('refund',p_user,jsonb_build_object('order_id',p_args->'order_id',
        'refund_id',payment_refund->'refund_id','refund_cents',payment_refund->'refund_cents'));
    end loop;
    if p_args->>'dispute_action'='resolve_dispute' then
      perform public.filey_ai_wallet('resolve_dispute',p_user,payment_args);
    end if;
    return public.filey_ai_wallet('status',p_user);
  end if;

  -- An interrupted edge worker must not lock funds forever. No uncertain usage
  -- is charged to the customer; Filey absorbs it. Chat holds last 10 minutes;
  -- accepted asynchronous video jobs explicitly extend their hold to 24 hours.
  with expired as (
    update ai_credit_requests set state='released', finished_at=now()
    where user_id=p_user and state='reserved' and expires_at < now()
    returning reserved_micros
  ) select coalesce(sum(reserved_micros),0) into released from expired;
  a.reserved_micros := a.reserved_micros - released;

  if p_action = 'limits' then
    a.task_limit_micros := (p_args->>'task_limit_micros')::bigint;
    a.daily_limit_micros := (p_args->>'daily_limit_micros')::bigint;
    if a.task_limit_micros is null or a.daily_limit_micros is null then raise exception 'Both limits are required'; end if;
  elsif p_action = 'reserve' then
    request_id := (p_args->>'request_id')::uuid;
    task_id := (p_args->>'run_id')::uuid;
    amount := (p_args->>'amount_micros')::bigint;
    if amount is null or amount < 1 or amount > 50000000 or task_id is null or request_id is null
      or coalesce(length(p_args->>'model'),0) not between 1 and 200
      or (p_args->>'markup_bps')::integer not between 0 and 10000 then raise exception 'Invalid AI reservation'; end if;
    if exists(select 1 from ai_credit_requests where id=request_id) then raise exception 'This request was already submitted. Refresh your balance before retrying.'; end if;
    if exists(select 1 from ai_credit_orders where user_id=p_user and disputed) then raise exception 'AI credits are paused while a payment dispute is reviewed.'; end if;
    if (select count(*) from ai_credit_requests where user_id=p_user and created_at>now()-interval '1 minute') >= 30 then raise exception 'AI request limit reached. Wait a minute.'; end if;
    if a.balance_micros-a.reserved_micros < amount then raise exception 'Not enough available AI credits for this request. Add credits or lower the output limit.'; end if;
    insert into ai_credit_requests(id,user_id,run_id,model,state,reserved_micros,markup_bps)
      values(request_id,p_user,task_id,p_args->>'model','reserved',amount,(p_args->>'markup_bps')::integer);
    a.reserved_micros := a.reserved_micros+amount;
  elsif p_action in ('settle','release') then
    select * into strict r from ai_credit_requests where id=(p_args->>'request_id')::uuid and user_id=p_user for update;
    if r.state='reserved' then
      amount := case when p_action='release' then 0 else (p_args->>'charged_micros')::bigint end;
      if amount is null or amount<0 then raise exception 'Invalid usage charge'; end if;
      -- Never charge beyond the approved reservation, even if a provider's
      -- tokenizer/pricing changes. The merchant absorbs any excess.
      amount := least(amount,r.reserved_micros);
      update ai_credit_requests set state=case when p_action='release' then 'released' else 'settled' end,
        charged_micros=amount, provider_cost_micros=(p_args->>'provider_cost_micros')::bigint,
        provider_id=left(p_args->>'provider_id',200), input_tokens=(p_args->>'input_tokens')::bigint,
        output_tokens=(p_args->>'output_tokens')::bigint, finished_at=now() where id=r.id;
      if p_action='settle' then
        insert into ai_credit_ledger(user_id,event_key,kind,amount_micros,description)
          values(p_user,'usage:'||r.id,'usage',-amount,r.model);
      end if;
      a.balance_micros := a.balance_micros-amount;
      a.reserved_micros := a.reserved_micros-r.reserved_micros;
    end if;
  elsif p_action in ('topup','refund','dispute','resolve_dispute') then
    select * into strict o from ai_credit_orders where id=(p_args->>'order_id')::uuid and user_id=p_user for update;
    if p_action='topup' then
      if o.payment_id is null then
        if coalesce(btrim(p_args->>'payment_id'),'')='' or (p_args->>'paid_cents') is null or (p_args->>'paid_cents')::bigint<0 then raise exception 'Invalid payment'; end if;
        if o.promotion_id is not null then
          if o.expected_paid_cents is distinct from 0 or (p_args->>'paid_cents')::bigint<>0
            or o.promotion_discount_id is null or o.promotion_customer_id is null or o.promotion_email is null
            or o.promotion_discount_code is null or o.promotion_expires_at is null or coalesce(o.checkout_session_id,'')=''
            or o.credits_micros<>5000000 or o.service_fee_cents<>50 then raise exception 'Invalid promotional payment'; end if;
          payment_at := (p_args->>'payment_event_at')::timestamptz;
          if p_args->>'payment_event_type' is distinct from 'payment.succeeded' or payment_at is null
            or not isfinite(payment_at) or payment_at>o.promotion_expires_at then raise exception 'Invalid promotional payment'; end if;
        elsif (p_args->>'paid_cents')::bigint<=0 then raise exception 'Invalid payment'; end if;
        update ai_credit_orders set payment_id=p_args->>'payment_id',paid_cents=(p_args->>'paid_cents')::bigint where id=o.id;
        insert into ai_credit_ledger(user_id,event_key,kind,amount_micros,description)
          values(p_user,'payment:'||(p_args->>'payment_id'),'topup',o.credits_micros,'AI credit top-up');
        a.balance_micros := a.balance_micros+o.credits_micros;
      elsif o.payment_id <> p_args->>'payment_id' or o.paid_cents is distinct from (p_args->>'paid_cents')::bigint then raise exception 'Payment does not match this top-up'; end if;
    elsif p_action='refund' then
      if o.payment_id is null then raise exception 'Payment must be reconciled before its refund'; end if;
      event_id := 'refund:'||(p_args->>'refund_id');
      if event_id is null or length(event_id)<9 then raise exception 'Refund ID required'; end if;
      if not exists(select 1 from ai_credit_ledger where event_key=event_id) then
        if coalesce((p_args->>'refund_cents')::bigint,0)<=0 or coalesce(o.paid_cents,0)<=0 then raise exception 'Invalid refund amount'; end if;
        amount := least(o.credits_micros-o.refunded_micros,ceil(o.credits_micros::numeric*(p_args->>'refund_cents')::bigint/o.paid_cents)::bigint);
        insert into ai_credit_ledger(user_id,event_key,kind,amount_micros,description)
          values(p_user,event_id,'refund',-amount,'AI credit refund');
        update ai_credit_orders set refunded_micros=refunded_micros+amount where id=o.id;
        a.balance_micros := a.balance_micros-amount;
      end if;
    else
      dispute_at := (p_args->>'event_at')::timestamptz;
      if dispute_at is null or not isfinite(dispute_at) then
        raise exception 'Credit dispute event timestamp required';
      end if;
      if p_action='resolve_dispute' and p_args->>'event_type' is distinct from 'dispute.won' then
        raise exception 'A verified won dispute event is required';
      end if;
      -- A delayed snapshot cannot reopen disputed spending. At the same
      -- timestamp, blocking wins regardless of concurrent delivery order.
      if o.dispute_event_at is null or dispute_at > o.dispute_event_at
        or (dispute_at = o.dispute_event_at and p_action='dispute') then
        update ai_credit_orders set disputed=(p_action='dispute'),
          dispute_event_at=dispute_at where id=o.id;
      end if;
    end if;
  elsif p_action <> 'status' then raise exception 'Unknown wallet action'; end if;

  if p_action <> 'status' or released > 0 then
  update ai_credit_accounts set balance_micros=a.balance_micros, reserved_micros=a.reserved_micros,
    task_limit_micros=a.task_limit_micros,daily_limit_micros=a.daily_limit_micros,updated_at=now() where user_id=p_user;
  end if;
  return to_jsonb(a)||jsonb_build_object('available_micros',a.balance_micros-a.reserved_micros,
    'blocked',exists(select 1 from ai_credit_orders where user_id=p_user and disputed));
end;
$$;
revoke all on function public.filey_ai_wallet(text,uuid,jsonb) from public, anon, authenticated;
grant execute on function public.filey_ai_wallet(text,uuid,jsonb) to service_role;

-- Source: supabase/2026-10-04-ai-credit-checkout-resume.sql
-- Persist an acknowledged provider checkout before returning it to its owner.
-- Existing unknown claims remain unknown; no new session or Coin is inferred.

alter table public.ai_credit_orders add column if not exists checkout_url text;
do $$ begin
  if not exists(select 1 from pg_constraint where conrelid='public.ai_credit_orders'::regclass and conname='ai_credit_checkout_url_safe') then
    alter table public.ai_credit_orders add constraint ai_credit_checkout_url_safe check (
      checkout_url is null or (length(checkout_url) between 1 and 2048
        and checkout_url ~ '^https://([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)*dodopayments\.com([/?#]|$)'
        and checkout_url !~ '[[:space:][:cntrl:]\\]'));
  end if;
end $$;
-- Checkout URLs contain private session identities and keep the existing
-- service-only order authority. Authenticated clients use the verified action.
revoke all on public.ai_credit_orders from public, anon, authenticated;
grant all on public.ai_credit_orders to service_role;

-- Source: supabase/2026-10-04-ai-completion-recovery.sql
-- Cloud Filey AI delivery recovery. No prompts, credentials or local records
-- are persisted. A request UUID can launch inference only once; its response
-- and charge commit together. Private results expire after 30 minutes.

create table if not exists public.ai_completion_results (
  request_id uuid primary key references public.ai_credit_requests(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  org_id text not null,
  run_id uuid not null,
  fingerprint text not null check (fingerprint ~ '^[0-9a-f]{64}$'),
  state text not null default 'pending' check (state in ('pending','complete','failed')),
  completion jsonb,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '30 minutes',
  check (octet_length(completion::text) <= 2000000)
);
create index if not exists ai_completion_results_expiry on public.ai_completion_results(expires_at)
  where completion is not null;
alter table public.ai_completion_results enable row level security;
revoke all on public.ai_completion_results from public, anon, authenticated;
grant all on public.ai_completion_results to service_role;

create or replace function public.filey_ai_completion_recovery(p_action text,p_user uuid,p_args jsonb)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  j public.ai_completion_results%rowtype;
  a jsonb;
  rid uuid := (p_args->>'request_id')::uuid;
  org text := p_args->>'org_id';
  charge bigint;
begin
  if p_user is null or rid is null then raise exception 'Invalid AI request'; end if;
  -- The lock order always matches the wallet: account, then request/result.
  a := public.filey_ai_wallet('status',p_user);
  if p_action in ('begin','status') and not exists (
    select 1 from public.profiles p join public.org_members m on m.org_id=p.org_id and m.user_id=p.id
    where p.id=p_user and p.org_id=org
  ) then raise exception 'Workspace access unavailable'; end if;
  update public.ai_completion_results set completion=null
    where user_id=p_user and expires_at<=now() and completion is not null;
  select * into j from public.ai_completion_results where request_id=rid for update;
  if found and (j.user_id<>p_user or j.org_id is distinct from org) then
    -- Same response as an unknown identifier, without exposing another owner.
    if p_action='status' then return jsonb_build_object('state','missing'); end if;
    raise exception 'Invalid AI request';
  end if;
  if p_action='begin' and j.request_id is null then
    if coalesce(p_args->>'fingerprint','') !~ '^[0-9a-f]{64}$' or (p_args->>'run_id')::uuid is null then
      raise exception 'Invalid AI request';
    end if;
    perform public.filey_ai_wallet('reserve',p_user,p_args);
    insert into public.ai_completion_results(request_id,user_id,org_id,run_id,fingerprint)
      values(rid,p_user,org,(p_args->>'run_id')::uuid,p_args->>'fingerprint');
    return jsonb_build_object('state','pending','dispatch',true);
  elsif p_action='begin' and (j.run_id is distinct from (p_args->>'run_id')::uuid
    or j.fingerprint is distinct from p_args->>'fingerprint') then
    raise exception 'AI request does not match its original content';
  elsif p_action in ('settle','fail') then
    if j.request_id is null then raise exception 'AI request unavailable'; end if;
    if j.state='pending' then
      if p_action='settle' then
        if jsonb_typeof(p_args->'completion') is distinct from 'object'
          or octet_length((p_args->'completion')::text)>2000000 then raise exception 'Invalid AI response'; end if;
        a := public.filey_ai_wallet('settle',p_user,p_args);
        select charged_micros into charge from public.ai_credit_requests where id=rid and user_id=p_user;
        update public.ai_completion_results set state='complete',completion=p_args->'completion'
          where request_id=rid;
      else
        a := public.filey_ai_wallet('release',p_user,jsonb_build_object('request_id',rid));
        update public.ai_completion_results set state='failed',completion=null where request_id=rid;
      end if;
    end if;
    return a;
  elsif p_action not in ('begin','status') then raise exception 'Unknown AI recovery action'; end if;
  if j.request_id is null then return jsonb_build_object('state','missing'); end if;
  if j.expires_at<=now() then
    return jsonb_build_object('state','failed','message','This reply has expired. Start a new task.');
  end if;
  -- A worker that never finished cannot strand a client indefinitely. Do not
  -- dispatch it again or charge uncertain provider work; let the hold expire.
  if j.state='pending' and j.created_at<now()-interval '3 minutes' then
    perform public.filey_ai_wallet('release',p_user,jsonb_build_object('request_id',rid));
    update public.ai_completion_results set state='failed' where request_id=rid;
    return jsonb_build_object('state','failed','message','Filey AI could not finish this request. No Coins were charged.');
  end if;
  if j.state='complete' then
    select charged_micros into charge from public.ai_credit_requests where id=rid and user_id=p_user;
    return jsonb_build_object('state','complete','completion',j.completion,'account',a,'charged_micros',charge);
  elsif j.state='failed' then
    return jsonb_build_object('state','failed','message','Filey AI could not finish this request. No Coins were charged.');
  end if;
  return jsonb_build_object('state','pending');
end;
$$;
revoke all on function public.filey_ai_completion_recovery(text,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.filey_ai_completion_recovery(text,uuid,jsonb) to service_role;

create or replace function public.filey_ai_completion_purge()
returns void language sql security definer set search_path=public,pg_temp as $$
  update public.ai_completion_results set completion=null where expires_at<=now() and completion is not null
$$;
revoke all on function public.filey_ai_completion_purge() from public,anon,authenticated;
grant execute on function public.filey_ai_completion_purge() to service_role;
-- Hosted installs with pg_cron purge expired response content each minute.
-- Fresh installs without it still reject expired reads and purge per account.
do $$ begin
  if exists(select 1 from pg_extension where extname='pg_cron') then
    perform cron.schedule('filey-ai-completion-purge','* * * * *','select public.filey_ai_completion_purge()');
  end if;
end $$;
notify pgrst,'reload schema';

-- Source: supabase/2026-10-06-letter-rich-document.sql
-- Safe Word-style Letter editor JSON in the existing org-scoped collection.
-- Additive: no business rows or issued snapshots are rewritten.

create or replace function public.filey_letter_rich_text_units(p_text text) returns integer
language sql immutable set search_path=public,pg_temp as $$
  select case when length(p_text)>250000 then 250001 else length(p_text) + coalesce((select count(*)::integer
    from regexp_split_to_table(p_text,'') as chars(character) where ascii(character)>65535),0) end
$$;

-- Returns [node count, bounded content units, plain-text units, company marks], or null for an
-- invalid node. Depth is checked before following any child references.
create or replace function public.filey_letter_rich_node_stats(p_node jsonb,p_parent text,p_depth integer,p_position integer)
returns integer[] language plpgsql immutable set search_path=public,pg_temp as $$
declare
  v_type text; v_key text; v_value jsonb; v_attrs jsonb; v_mark jsonb; v_child jsonb;
  v_seen text[]:=array[]::text[]; v_stats integer[]; v_nodes integer:=1; v_units integer:=0;
  v_plain integer:=0; v_marks integer:=0; v_index integer:=0; v_start integer:=1; v_count integer;
begin
  if p_depth is null or p_depth<1 or p_depth>16 or p_position is null or p_position<0 or p_position>20000 or
    p_parent is null or p_parent not in ('doc','paragraph','heading','bulletList','orderedList','listItem','blockquote') or
    jsonb_typeof(p_node) is distinct from 'object' or octet_length(p_node::text)>2000000 then return null; end if;
  if exists(select 1 from jsonb_object_keys(p_node) k where k not in ('type','attrs','content','text','marks')) then return null; end if;
  if jsonb_typeof(p_node->'type') is distinct from 'string' then return null; end if;
  v_type:=p_node->>'type';
  if p_parent in ('paragraph','heading') then
    if v_type not in ('text','hardBreak') then return null; end if;
  elsif p_parent in ('bulletList','orderedList') then
    if v_type<>'listItem' then return null; end if;
  else
    if v_type not in ('paragraph','heading','bulletList','orderedList','blockquote','companySignature','companyStamp') then return null; end if;
    if p_parent='listItem' and p_position=0 and v_type<>'paragraph' then return null; end if;
  end if;

  if v_type='text' then
    if p_node?'attrs' or p_node?'content' or jsonb_typeof(p_node->'text') is distinct from 'string' or length(p_node->>'text')=0 then return null; end if;
    v_units:=public.filey_letter_rich_text_units(p_node->>'text');
    if v_units>250000 then return null; end if;
    if p_node?'marks' then
      if jsonb_typeof(p_node->'marks') is distinct from 'array' or jsonb_array_length(p_node->'marks')>4 then return null; end if;
      for v_mark in select value from jsonb_array_elements(p_node->'marks') loop
        if jsonb_typeof(v_mark) is distinct from 'object' or jsonb_typeof(v_mark->'type') is distinct from 'string' then return null; end if;
        if (v_mark->>'type')=any(v_seen) then return null; end if;
        v_seen:=array_append(v_seen,v_mark->>'type');
        if v_mark->>'type' in ('bold','italic','underline') then
          if exists(select 1 from jsonb_object_keys(v_mark) k where k<>'type') then return null; end if;
        elsif v_mark->>'type'='textStyle' then
          if exists(select 1 from jsonb_object_keys(v_mark) k where k not in ('type','attrs')) or jsonb_typeof(v_mark->'attrs') is distinct from 'object' then return null; end if;
          v_attrs:=v_mark->'attrs';
          for v_key,v_value in select key,value from jsonb_each(v_attrs) loop
            if v_key not in ('fontFamily','fontSize','color') then return null; end if;
            if v_value='null'::jsonb then continue; end if;
            if jsonb_typeof(v_value)<>'string' then return null; end if;
            if v_key='fontFamily' and (v_value#>>'{}') not in ('Inter','Arial','Georgia','Times New Roman','Courier New','Lora','IBM Plex Mono') then return null; end if;
            if v_key='fontSize' then
              if (v_value#>>'{}') !~ '^\d{1,2}(\.\d{1,2})?pt$' then return null; end if;
              if replace(v_value#>>'{}','pt','')::numeric<8 or replace(v_value#>>'{}','pt','')::numeric>36 then return null; end if;
            end if;
            if v_key='color' and (v_value#>>'{}') !~* '^#[0-9a-f]{6}$' then return null; end if;
          end loop;
        else return null;
        end if;
      end loop;
    end if;
    return array[1,v_units,v_units,0];
  elsif v_type='hardBreak' then
    if exists(select 1 from jsonb_object_keys(p_node) k where k<>'type') then return null; end if;
    return array[1,1,1,0];
  end if;

  if p_node?'text' or p_node?'marks' then return null; end if;
  if v_type in ('companySignature','companyStamp') then
    if p_node?'content' or jsonb_typeof(p_node->'attrs') is distinct from 'object' then return null; end if;
    v_attrs:=p_node->'attrs';
    if exists(select 1 from jsonb_object_keys(v_attrs) k where k not in ('label','textAlign')) then return null; end if;
    if jsonb_typeof(v_attrs->'label') is distinct from 'string' or public.filey_letter_rich_text_units(v_attrs->>'label')>200 or (v_attrs->>'label')~ E'[\r\n]' then return null; end if;
    if v_attrs?'textAlign' and v_attrs->'textAlign'<>'null'::jsonb and
      (jsonb_typeof(v_attrs->'textAlign')<>'string' or v_attrs->>'textAlign' not in ('left','center','right')) then return null; end if;
    return array[1,0,0,1];
  end if;
  if p_node?'attrs' then
    if v_type not in ('orderedList','paragraph','heading') then return null; end if;
    if jsonb_typeof(p_node->'attrs') is distinct from 'object' then return null; end if;
    v_attrs:=p_node->'attrs';
    for v_key,v_value in select key,value from jsonb_each(v_attrs) loop
      if v_type='orderedList' then
        if v_key<>'start' then return null; end if;
        if v_value='null'::jsonb then continue; end if;
        if jsonb_typeof(v_value)<>'number' or (v_value#>>'{}')::numeric<1 or (v_value#>>'{}')::numeric>9999 or trunc((v_value#>>'{}')::numeric)<>(v_value#>>'{}')::numeric then return null; end if;
        v_start:=(v_value#>>'{}')::integer;
      elsif v_type in ('paragraph','heading') then
        if v_key not in ('textAlign','lineSpacing','paragraphSpacing') and not(v_type='heading' and v_key='level') then return null; end if;
        if v_value='null'::jsonb and v_key<>'level' then continue; end if;
        if v_key='textAlign' then
          if jsonb_typeof(v_value)<>'string' or (v_value#>>'{}') not in ('left','center','right','justify') then return null; end if;
        else
          if jsonb_typeof(v_value)<>'number' then return null; end if;
          if v_key='level' and ((v_value#>>'{}')::numeric not in (1,2,3)) then return null; end if;
          if v_key='lineSpacing' and ((v_value#>>'{}')::numeric<1 or (v_value#>>'{}')::numeric>2.5) then return null; end if;
          if v_key='paragraphSpacing' and ((v_value#>>'{}')::numeric<0 or (v_value#>>'{}')::numeric>32) then return null; end if;
        end if;
      else return null;
      end if;
    end loop;
  elsif v_type='heading' then return null;
  end if;
  if v_type='heading' and not(p_node->'attrs'?'level') then return null; end if;
  if p_node?'content' and jsonb_typeof(p_node->'content') is distinct from 'array' then return null; end if;
  v_count:=coalesce(jsonb_array_length(p_node->'content'),0);
  if v_type not in ('paragraph','heading') and v_count=0 then return null; end if;
  for v_child in select value from jsonb_array_elements(coalesce(p_node->'content','[]'::jsonb)) loop
    v_stats:=public.filey_letter_rich_node_stats(v_child,v_type,p_depth+1,v_index);
    if v_stats is null then return null; end if;
    v_nodes:=v_nodes+v_stats[1]; v_units:=v_units+v_stats[2]; v_plain:=v_plain+v_stats[3]; v_marks:=v_marks+v_stats[4];
    if v_type='bulletList' then v_plain:=v_plain+2;
    elsif v_type='orderedList' then v_plain:=v_plain+length((v_start+v_index)::text)+2;
    end if;
    if v_nodes>20000 or v_units>250000 or v_plain>250000 or v_marks>89 then return null; end if;
    v_index:=v_index+1;
  end loop;
  v_units:=v_units+1;
  if v_type not in ('paragraph','heading') then v_plain:=v_plain+greatest(v_count-1,0); end if;
  if v_units>250000 or v_plain>250000 then return null; end if;
  return array[v_nodes,v_units,v_plain,v_marks];
exception when numeric_value_out_of_range or invalid_text_representation then return null;
end $$;

create or replace function public.filey_letter_rich_document_valid(p_document jsonb) returns boolean
language plpgsql immutable set search_path=public,pg_temp as $$
declare v_child jsonb; v_stats integer[]; v_nodes integer:=0; v_units integer:=0; v_plain integer:=0; v_marks integer:=0; v_count integer;
begin
  if jsonb_typeof(p_document) is distinct from 'object' or p_document->>'type' is distinct from 'doc' or
    exists(select 1 from jsonb_object_keys(p_document) k where k not in ('type','content')) then return false; end if;
  if jsonb_typeof(p_document->'content') is distinct from 'array' then return false; end if;
  v_count:=jsonb_array_length(p_document->'content');
  if v_count=0 or v_count>20000 or octet_length(p_document::text)>2000000 then return false; end if;
  for v_child in select value from jsonb_array_elements(p_document->'content') loop
    v_stats:=public.filey_letter_rich_node_stats(v_child,'doc',1,0);
    if v_stats is null then return false; end if;
    v_nodes:=v_nodes+v_stats[1]; v_units:=v_units+v_stats[2]; v_plain:=v_plain+v_stats[3]; v_marks:=v_marks+v_stats[4];
    -- At most eleven projected text tails + 89 company slots fit 100 legacy blocks.
    if v_nodes>20000 or v_units>250000 or v_plain+v_count-1>250000 or v_marks>89 then return false; end if;
  end loop;
  return true;
end $$;

create or replace function public.filey_letter_form_format_valid(p_form jsonb) returns boolean
language plpgsql immutable set search_path=public,pg_temp as $$
declare v_key text; v_block jsonb;
begin
  if jsonb_typeof(p_form) is distinct from 'object' then return false; end if;
  foreach v_key in array array['show_reference','show_company_header'] loop
    if p_form?v_key and jsonb_typeof(p_form->v_key)<>'boolean' then return false; end if;
  end loop;
  foreach v_key in array array['text_style','title_style'] loop
    if p_form?v_key and not public.filey_letter_text_style_valid(p_form->v_key) then return false; end if;
  end loop;
  if jsonb_typeof(p_form->'blocks') is distinct from 'array' then return false; end if;
  for v_block in select value from jsonb_array_elements(p_form->'blocks') loop
    if jsonb_typeof(v_block)<>'object' then return false; end if;
    if v_block?'style' and not public.filey_letter_text_style_valid(v_block->'style') then return false; end if;
  end loop;
  if p_form?'rich_document' and not public.filey_letter_rich_document_valid(p_form->'rich_document') then return false; end if;
  return true;
end $$;

revoke all on function public.filey_letter_rich_text_units(text) from public,anon;
revoke all on function public.filey_letter_rich_node_stats(jsonb,text,integer,integer) from public,anon;
revoke all on function public.filey_letter_rich_document_valid(jsonb) from public,anon;
grant execute on function public.filey_letter_rich_text_units(text) to authenticated,service_role;
grant execute on function public.filey_letter_rich_node_stats(jsonb,text,integer,integer) to authenticated,service_role;
grant execute on function public.filey_letter_rich_document_valid(jsonb) to authenticated,service_role;

notify pgrst,'reload schema';

-- Source: supabase/2026-10-07-removed-member-workspace-recovery.sql
-- Removing team access must not strand an account in its former workspace.
-- Reuse the signup-owned workspace; never move records or restore membership.

create or replace function public.filey_switch_workspace(p_id text) returns void
language plpgsql security definer set search_path=public,pg_temp as $$
begin
  -- Hold membership until the profile update commits. Without this lock a
  -- concurrent removal can recover the profile before this switch overwrites it.
  perform 1 from public.org_members where org_id=p_id and user_id=auth.uid() for share;
  if not found then raise exception 'You are not a member of this workspace'; end if;
  update public.profiles set org_id=p_id where id=auth.uid();
  if not found then raise exception 'Profile not found'; end if;
end $$;
revoke all on function public.filey_switch_workspace(text) from public,anon;
grant execute on function public.filey_switch_workspace(text) to authenticated;

create or replace function public.accept_invitation(invite uuid) returns void
language plpgsql security definer set search_path=public,pg_temp as $$
declare inv public.invitations; v_email text:=public.my_email();
begin
  if auth.uid() is null or v_email is null then raise exception 'Verify your account email before joining'; end if;
  select * into inv from public.invitations where id=invite for update;
  if inv.id is null or lower(inv.email)<>v_email then raise exception 'Sign in with the email address this invitation was sent to'; end if;
  if inv.status<>'pending' or inv.expires_at<=now() then raise exception 'This invitation has expired or is no longer available. Ask for a new invitation'; end if;
  if inv.role not in ('admin','manager','accountant','staff') then raise exception 'Ask the owner to replace this invitation'; end if;
  -- An old invite cannot change an existing member's permissions.
  insert into public.org_members(org_id,user_id,role,modules) values(inv.org_id,auth.uid(),inv.role,inv.modules)
    on conflict(org_id,user_id) do nothing;
  perform public.filey_switch_workspace(inv.org_id);
  update public.invitations set status=case when id=inv.id then 'accepted' else 'revoked' end,updated_at=now()
    where org_id=inv.org_id and lower(invitations.email)=v_email and status='pending';
end $$;
revoke all on function public.accept_invitation(uuid) from public,anon;
grant execute on function public.accept_invitation(uuid) to authenticated;

-- Bind permission responses to their authoritative workspace. Older clients
-- ignore the additive field; current clients cannot apply recovered owner
-- access to cached records from the former team while their profile catches up.
create or replace function public.filey_module_access() returns jsonb
language sql stable security definer set search_path=public,pg_temp as $$
  select coalesce((select jsonb_build_object('allowed',true,'org_id',m.org_id,
      'admin',m.role in ('owner','admin'),'modules',m.modules)
    from public.org_members m where m.org_id=public.current_org() and m.user_id=auth.uid() limit 1),
    jsonb_build_object('allowed',false,'org_id',public.current_org(),'admin',false,'modules','[]'::jsonb))
$$;
revoke all on function public.filey_module_access() from public,anon;
grant execute on function public.filey_module_access() to authenticated;

create or replace function public.filey_restore_removed_member_workspace()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_org text;
begin
  -- Account deletion must not provision or resurrect any workspace/profile.
  if not exists(select 1 from auth.users where id=old.user_id) then return old; end if;
  select o.id::text into v_org from public.organizations o join public.org_members m
    on m.org_id=o.id::text and m.user_id=o.owner_id and m.role='owner'
    where o.owner_id=old.user_id and o.id::text<>old.org_id
    order by o.created_at,o.id limit 1 for share of m for key share of o;
  if v_org is not null then
    update public.profiles p set org_id=v_org
      where p.id=old.user_id and p.org_id=old.org_id
        and not exists(select 1 from public.org_members m where m.org_id=old.org_id and m.user_id=old.user_id);
  end if;
  return old;
end $$;
revoke all on function public.filey_restore_removed_member_workspace() from public,anon,authenticated,service_role;
drop trigger if exists filey_restore_removed_member_workspace on public.org_members;
create trigger filey_restore_removed_member_workspace after delete on public.org_members
  for each row execute function public.filey_restore_removed_member_workspace();

-- Repair earlier removals, using only a real owned workspace and owner role.
-- A valid active workspace is preserved; missing owner workspaces stay denied.
with recovery as (
  select distinct on (p.id) p.id,p.org_id as previous_org,o.id::text as org_id
    from public.profiles p join auth.users u on u.id=p.id
    join public.organizations o on o.owner_id=p.id
    join public.org_members m on m.org_id=o.id::text and m.user_id=p.id and m.role='owner'
    where p.org_id is not null and p.org_id<>'default'
      and not exists(select 1 from public.org_members active where active.org_id=p.org_id and active.user_id=p.id)
    order by p.id,o.created_at,o.id
)
update public.profiles p set org_id=r.org_id from recovery r
  where p.id=r.id and p.org_id=r.previous_org
    and not exists(select 1 from public.org_members active where active.org_id=p.org_id and active.user_id=p.id);

notify pgrst,'reload schema';

-- Source: supabase/2026-10-07-profile-workspace-authority.sql
-- Active workspace changes must use the membership-locking switch RPC.
-- A direct profile UPDATE can use a stale statement snapshot after removal.
-- Apply after removed-member workspace recovery; no stored rows are changed.

do $$ declare v_role text; v_columns text; begin
  -- Table UPDATE overrides a column REVOKE. Preserve the existing grants for
  -- every other column, including limited-grant installations and repeat runs.
  foreach v_role in array array['public','anon','authenticated'] loop
    select string_agg(quote_ident(a.attname),', ' order by a.attnum) into v_columns
      from pg_attribute a join pg_class c on c.oid=a.attrelid
      where a.attrelid='public.profiles'::regclass and a.attnum>0 and not a.attisdropped and a.attname<>'org_id'
        and case when v_role='public' then
          exists(select 1 from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) acl
            where acl.grantee=0 and acl.privilege_type='UPDATE')
          or exists(select 1 from aclexplode(a.attacl) acl where acl.grantee=0 and acl.privilege_type='UPDATE')
        else has_column_privilege(v_role,c.oid,a.attnum,'UPDATE') end;
    -- The role names come only from the fixed list above (PUBLIC is a keyword).
    execute format('revoke update on public.profiles from %s',v_role);
    execute format('revoke update (org_id) on public.profiles from %s',v_role);
    if v_columns is not null then
      execute format('grant update (%s) on public.profiles to %s',v_columns,v_role);
    end if;
  end loop;
end $$;
notify pgrst,'reload schema';

-- Source: supabase/2026-10-07-mascot-avatars.sql
-- Extend the preset allowlist only. Membership checks and saved choices stay intact.

alter table public.org_members drop constraint if exists org_members_avatar_preset;
alter table public.org_members add constraint org_members_avatar_preset check (
  avatar is null or avatar in (
    '/avatars/sun.svg','/avatars/mint.svg','/avatars/coral.svg','/avatars/sky.svg',
    '/avatars/lilac.svg','/avatars/peach.svg','/avatars/slate.svg','/avatars/sage.svg',
    '/avatars/sunburst.svg','/avatars/triangle.svg'
  ) or avatar ~ '^/avatars/blobatar/(round|organic|boxy|capsule|nub|cloud|droplet|hexagon|sunburst|triangle)-(sun|mint|coral|sky|lilac|peach|slate|sage|amber|rose)[.]svg$'
    or avatar ~ '^/avatars/mascots/(bear|bunny|cat|deer|dino|fox|frog|hamster|hedgehog|koala|mouse|otter|owl|panda|penguin|pug|raccoon|redpanda|sheep|sloth|tiger|afro|astronaut|bald|ballerina|beard|builder|cap|chef|glasses|grandpa|granny|hijabi|kamran|nurse|pirate|scientist|sikh|skater|wizard|clockwork|crt|cube|drone|gearbot|knight|lantern|postbot|radio|rocket|scout|toaster|tv)[.]webp$'
);
comment on constraint org_members_avatar_preset on public.org_members is
  'Exact bundled Filey, Blobatar or Page Mascot portraits only; no external URLs or sprite sheets.';
notify pgrst, 'reload schema';

-- Source: supabase/2026-10-07-document-save-performance.sql
-- Parse each document/header line once, including inline company artwork.
-- Repeating jsonb_populate_record for every field made real invoice saves exceed
-- the API statement timeout. Keep caller RLS, omitted-column defaults, atomic
-- replacement and existing function ownership/privileges unchanged.

create or replace function public.filey_save_document(p_table text, p_header jsonb, p_items jsonb, p_id bigint default null)
returns bigint language plpgsql security invoker set search_path = public, pg_temp as $$
declare
  item_table text; fk text; header jsonb; item jsonb; cols text; vals text;
  result_id bigint; ordinal integer := 0; allowed text[]; original_status text; original_author uuid; original_org text;
begin
  if auth.uid() is null then raise exception 'Sign in to save documents'; end if;
  case p_table
    when 'invoice_docs' then item_table := 'invoice_doc_items'; fk := 'invoice_id';
    when 'quotations' then item_table := 'quotation_items'; fk := 'quotation_id';
    when 'purchase_orders' then item_table := 'purchase_order_items'; fk := 'po_id';
    else raise exception 'Unsupported document type';
  end case;
  if p_header is null or p_items is null or jsonb_typeof(p_header) <> 'object' or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 500 or octet_length(p_header::text)+octet_length(p_items::text)>8388608 then
    raise exception 'Invalid document payload';
  end if;
  header := p_header - array['id','user_id','org_id','created_at','updated_at','shared','shared_with','share_token','stock_received'];
  select array_agg(column_name::text) into allowed from information_schema.columns where table_schema='public' and table_name=p_table;
  if exists(select 1 from jsonb_object_keys(header) k where not (k = any(allowed))) then raise exception 'Unknown document field'; end if;
  if p_id is not null then
    execute format('select id, status, user_id, org_id from public.%I where id=$1 for update', p_table) into result_id, original_status, original_author, original_org using p_id;
    if result_id is null or original_org is distinct from public.current_org() or (original_author is distinct from auth.uid() and not public.is_org_admin()) then raise exception 'Document not found or edit access denied' using errcode='42501'; end if;
    if not public.filey_document_lines_replaceable(p_table,p_id) then raise exception 'Historic document lines require ownership reconciliation before replacement' using errcode='42501'; end if;
    if p_table in ('invoice_docs','purchase_orders') and current_user<>'filey_workflow_executor'
      and (original_status is distinct from 'draft' or coalesce(header->>'status',original_status) is distinct from 'draft') then
      raise exception 'Use the document workflow to change a finalized invoice or purchase order' using errcode='42501'; end if;
    select string_agg(format('%I = r.%I', k, k), ',') into vals from jsonb_object_keys(header) k;
    if vals is not null then execute format('update public.%I d set %s from jsonb_populate_record(null::public.%I,$1) r where d.id=$2 returning d.id',p_table,vals,p_table) into result_id using header,p_id; end if;
    if result_id is null then raise exception 'Document update denied'; end if;
    execute format('delete from public.%I where %I=$1',item_table,fk) using p_id;
  else
    if p_table in ('invoice_docs','purchase_orders') and current_user<>'filey_workflow_executor'
      and coalesce(header->>'status','draft') is distinct from 'draft' then
      raise exception 'Use the document workflow to finalize an invoice or purchase order' using errcode='42501'; end if;
    original_author:=auth.uid(); original_org:=public.current_org();
    select string_agg(format('%I', k), ','), string_agg(format('r.%I',k), ',') into cols,vals from jsonb_object_keys(header) k;
    if cols is null then raise exception 'Document header is required'; end if;
    execute format('insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I,$1) r returning id',p_table,cols,vals,p_table) into result_id using header;
  end if;
  select array_agg(column_name::text) into allowed from information_schema.columns where table_schema='public' and table_name=item_table;
  for item in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(item)<>'object' then raise exception 'Invalid document line'; end if;
    item := (item - array['id','user_id','org_id','created_at','updated_at','shared']) || jsonb_build_object(fk,result_id,'position',ordinal,'user_id',original_author,'org_id',original_org);
    if exists(select 1 from jsonb_object_keys(item) k where not (k = any(allowed))) then raise exception 'Unknown line field'; end if;
    select string_agg(format('%I',k),','), string_agg(format('r.%I',k),',') into cols,vals from jsonb_object_keys(item) k;
    execute format('insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I,$1) r',item_table,cols,vals,item_table) using item;
    ordinal := ordinal + 1;
  end loop;
  return result_id;
end;
$$;
notify pgrst,'reload schema';
